/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200923-8","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"建設委員会","time":"午前１０時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を113件整理しています。","topics":[{"id":"topic-01","title":"第６０号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第６０号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"区は、都市計画審議会の質疑では、校舎に日照が当たるのは１時間か２時間程度と答弁されていると思います。これで文部科学省が出している学校施設整備方針、ここにある良好な……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"その学校施設整備方針には、良好な日照を確保する必要がある、それが重要だということで書かれております。１時間から２時間で良好な日照を確保できるというお考えなのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"複合日影といいまして、学校に１時間から２時間程度日が当たるということで、そういう計算をしたという内容になってあります。この住環境を含めた計画ということで、法令の中でできる限りの配慮をしていただいて進めていると、そういう事業だと認識しています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"子どもたちが８時から３時、４時くらいまで学校にいるとすれば、五、六時間、その場所で過ごすことになるわけです。それで本当に足りていると区は考えているのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"そうしたら、こうした日照が１時間か２時間しか学校に当たらないという建築計画が適切なのかということで考えているのか、伺いたいと思います。２０ｍ以上確保できるようにということ、実際にその当時よりも間隔を空けることはできたのか、そこのところも伺いたいと思います。","respondent":"多並都市開発課長","answer":"その中でもできる限り周りへの配慮をということで、そういう形で今の計画を進めてきたということで、そのような点でご理解いただきたいと思います。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"特に日野学園は区立の学校ですから、きちんと日照を確保していくということで指導していくことが必要だと思います。単純に今までの最高の倍になってしまうというのは、都市計画上、不自然というか、根拠が分からないというところを伺いたいと思います。","respondent":"多並都市開発課長","answer":"業務・商業機能と大崎周辺の居住機能と、適切な役割分担の中で連携を図りながら、計画的に進めていく地区ということに位置づけられているところです。そういう形で進めている事業です。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"私が伺ったのは、容積率がなぜ６５０％必要なのかということです。日照の確保にもつながってくるということになると思うのですけれども、なぜ容積率６５０％にする必要があるのか、伺いたい。","respondent":"多並都市開発課長","answer":"このまちづくりの事業を進めるにあたっては、特にこの市街地再開発事業を進めるにあたって、都市計画についても非常に密接に関わってくるところです。その空地の割合が３５％以上図られる、今回の地区についての容積率ということで算定させていただいた、そういう内容です。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"今おっしゃった条件をクリアすれば、６５０％に容積率が緩和されるということですかね。学校の環境よりも再開発を優先していくというこの区の姿勢を改めるべきだということで、意見として言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、そのように区として指導していくということだったのですが、きちんと日照が確保できるのかというところを確認させてほしいと求めました。このＡ地区、Ｂ地区で、１１５ｍと１５１ｍと約４０ｍ違うではないか尋ねました。","respondent":"多並都市開発課長","answer":"２棟ある建物の間隔を空けることで、間隔が非常に狭くなってしまうと、入ってくる日が少なくなるということです。今まで進めてきた周囲の再開発事業がありまして、１つは、その隣接する地区も含めて配慮して進めたという内容です。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"それより低く条例では定められないものなのかというところを確認させていただきたいのです。いかがか尋ねました。","respondent":"長尾建築課長","answer":"建築確認申請の際に地区計画で定められた内容を担保するためというところで、各地区計画を定めた後に条例を改正しているところです。実際の計画する高さというのは、条例の中では、その高さをさらに低くするとかというような判断というのは行っておりません。","id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"それとも、もう絶対にできないものなのか、そこだけ少し確認させてほしいのですけれども。低くできるものならばしてほしいなと思って、それともできるものなのか、そこの部分だけ確認したいと求めました。","respondent":"長尾建築課長","answer":"この地区計画の制限条例につきましては、建築基準法の中でその制度というのが定められておりますので、その範囲の中で定めることとしております。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"これは容積率の緩和を６５０％ですか、１つ当たりの新しいところは当然ながら価値が上がってくるわけですから、それは計算式に基づいた。そこらあたり、行政としてどういうふうにお考えなのか尋ねました。","respondent":"多並都市開発課長","answer":"そのときの考え方の原則は、最終的に権利変換の計画をつくる際には、今の等価というところでもあります。生活再建という観点もよく踏まえながら皆さんで話し合っていただいて進めていくことが、やはり肝要ではないかなとは思って進めているところです。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"これだけは言えるのは、皆さん土地を提供していただいて、新しいまちをつくるということに対する感情的なものは非常に前向きにある。できてしまった後、いろいろな部分で、そういう声が聞こえてこないような介添え役としての区のメッセージを発信してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"この制限をかけることによって、どういう効果が得られるのか。１１５ｍ、１５１ｍという根拠はどこにあるのかというところを、まず説明を求めました。","respondent":"長尾建築課長、多並都市開発課長","answer":"壁面の位置の制限の効果に関してですけれども、この壁面位置の制限をかけることで、まず、建物の配置に関して制限がかかります。道路とか公園のような空地部分が一定程度確保されることになりますので… 低利用な地区の高度化を図っていただきたいという意味がありますので、最低限の用途、容積率というのを設定させていただいているところです。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"五反田駅、それから大崎駅、今でさえ満杯になっているのに、これからどうするのですか。なかなか一致しないというところにおいて、考え方も価値観も変わっていく中での区の立場というのをどうしていくのかを、少しお聞きしたいと思います。","respondent":"多並都市開発課長","answer":"具体的な策についてはまた段階を追いながら進めていきたいということで、今、協議を継続しています。ご支援をさせていただきながら、一緒に考えていくことが一番重要なのではないかなと、今後もそういうふうに進めていきたいと思っているところです。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろ日照で、日影になるから何とかしてほしいという住民の動きがあって、それで日野学園が何か斜線をとって、建築自体の制限を変えたのですよ。いろいろな話し合いの中で、それを踏まえての建築を考えてほしいと求めましたが、その辺の説明とかというのは何かされているのか尋ねました。","respondent":"多並都市開発課長","answer":"その際、説明会も開きながらやりましたが、あとは学校であったり教育委員会ともよく協議しながら、この考え方については進めてきたところです。この事業につきましては、今もご説明いたしましたけれども、よく情報共有をしながら的確に進めていきたいと思っているところです。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、やはりお互いさま、その中でまちづくりをどうするのかという話し合いにぜひしていただきたいなと。折り合いをつけるような建物にするとかということで、ぜひ前向きに進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今の話でどうしようかと思ったけれども、１点だけ考え方をお伺いしたいと思う。テナントをどうやって入れようかといえば、多分、上場企業でもメーカー系しか来ないだろうというくらいの話しかないわけではないか尋ねました。","respondent":"多並都市開発課長","answer":"ものづくりの部署であったり、いろいろな部署とよく連携を図って、進めていかなければいけないと考えているところです。しっかり議論しながら、将来の大崎の方向性というのは進めていくところでもありますので、検討は区としても進めていくべきとは考えているところです。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこにいろいろな情報が入ってくるわけではないですか。品川駅はどうだったといったら、品川でも手を挙げるところになったし、羽田もあれで本当によかったのかというのがあるわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"しっかり中に入っているのですよというところの確認をさせてほしいと求めました。いわゆる建築物、工作物を作る場合の何か制限とか、その有無について確認をさせていただきたい。","respondent":"多並都市開発課長","answer":"再開発等まちづくりを進める中で、公共性の高い施設を整備するということで、それをここに表させていただいているところであります。個別のご相談をいただきながら進めていくような内容で、基本的には空地は空けて広場にしてほしいという内容の、この地区計画上の考え方です。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"そういうところの１,５００m2に対して、掛け算すればいいのですけれども、こういう場ですから、建築面積の最低限度が５００m2。ただ、いわゆる都市公園法というのでしょうか、そういうところの説明をしっかり行っていただきたい。","respondent":"長尾建築課長","answer":"条例の中で４つ、そういったものを計画する場合は、関連する法令をすべて守った形で建築確認を行う必要が出てきます。具体的な計画については、そういう建築を計画される際は、この制限条例も規制の１つとして守った形で計画されることになります。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"この条例の高さの最高限度に関しては、やはり生活者ネットワークには、高さを求める声は聞こえてこないです。地域の声を聞いて、高さはなるべく低く、今も航空法で結構ぎりぎりの高さの設定となっているので、低くしてもらえるように求めたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"第５６号議案、令和２年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５６号議案、令和２年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"家庭用生ごみ処理機の需要がとても増えているということで、それがなぜ増えたのか、この理由を伺いたいと思います。この間そういったことがあったのかどうかも含めて、ご説明ほしいと求めました。","respondent":"工藤品川区清掃事務所長、鈴木都市計画課長","answer":"先ほどご説明したとおり、外出自粛等によりまして、回収量が増えているです。行動が働きまして、今申請が大幅に増えているというふうに、私どもも理解しております。 緊急事態宣言下の４月、５月においては、５割減という数字を伺ってあります。緊急的に廃止といいますか、一時中止をして、終バスの時間帯を繰り上げているというところもあると伺ってあります。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"それと併せて避難所生活環境改善経費ということで、今回備蓄を買い足すということで、この導入をした理由を伺いたいと思います。避難所のほうのトイレですとかパーテーションの数は、必要な数の備蓄になっているのか、そこのところも伺いたいと思います。","respondent":"中島防災課長、平原防災体制整備担当課長","answer":"私からは、電源の、今回補正予算に計上させていただきました理由について、ご説明をします。品川区といたしましても同様の問題認識のもと、災害時に備えていただく自助・共助の強化の観点から、計上させていただいたところです。今回導入を予定しておりますものにつきましては、それぞれの対応するものがありますけれども、基本の考え方といたしましては。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういった方々が数百人避難をしてきたということですけれども、そうした場合、自主避難施設などでもこのパーテーションを使っていくのか。私は、このコロナの中で距離を確保するという意味でも必要だと思うのですけれども、そこのお考えを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"もともとの考え方といたしましては、こちら、避難生活が長くなった場合の生活環境改善というところで考えさせていただいたところです。避難所におきましては、いろいろな考え方があるかと思いますけれども、そういったところで工夫してまいりたいと考えております。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"症状がある方だけでなくて、症状がない方も、避難所でしっかりと距離を取ってもらうと。毛布１枚で体育館に座り込んでいるという状況では、そういったプライベート空間を確保できるというふうに、ぜひ進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"田中委員","kind":"意見","question":"といったお話などがあったのですけれども、それらを防止するためにも、このパーテーションであったり生活環境の改善はしていくべきだと考えています。この経費の括弧の中では「パーテーション等」とあるのですけれども、この「等」についてお知らせほしいと求めました。","respondent":"平原防災体制整備担当課長","answer":"それ以外の「等」というところで資料上まとめさせていただきましたものにつきましてご説明しますと、まず１つ目には。いわゆる自動ラップ式のポータブルトイレ、こちらにつきましても、すべての避難所に対応できるような台数をご用意させていただきたいと考えています。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"この避難所生活の環境改善に向けては、きっちり検討というか、ぜひ進めてほしいと求めました。資料のほうで、対象は３事業者だということだったのですけれども、この場合どうなるのかといったところをお知らせいただければと思うのですが。","respondent":"鈴木都市計画課長","answer":"先ほどの説明で、都バスも含めてというご説明を差し上げましたが、今考えてあります。実施の段階で、要綱上もしっかり整理をして、助成を進めていきたいです。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問","question":"そういった場合はどうなるのだろうということとかも、少しお知らせいただければ。もう１回聞いてもいいか尋ねました。","respondent":"鈴木都市計画課長","answer":"それから、先ほど説明が少し不足しておりましたが、物によっては都内だけではなくて、神奈川県等に走るバスも当然あります。要綱上もしっかり記載をしながら、制度を進めていきたい、助成を進めていきたいです。","id":"exchange-028"},{"speaker":"西本委員","kind":"確認","question":"申請の時期も違うだろうし、それもすべて整合性が取れるように確認をとって支給をするということなのでしょうか。それを確認したいと求めました。","respondent":"鈴木都市計画課長","answer":"これ、歳入のほうでは新型コロナウイルス感染症対応地方創生臨時交付金というところで、この枠組みの中で区のほうも行うと。二重にお支払いすることがないように、要綱上でもしっかり縛りをかけて、事業を進めていくというものです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"広く適用してほしいと求めましたから、これが結果的にどうなるのかというところは、報告をいただきたいと考えていますけれども。そうした場合、もう支払いも終わってしまっているもの、それは後で申請をするという形が可能なのかどうかというのはいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"区内でいうと２事業者ということで、その内容についてもご説明しているというところもあって、できるだけスピーディーに行っていきたいです。先ほど区の枠組みの中で行うというご説明をさせていただきましたが、内容を確認して、助成金をお支払いするという考えです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"この５月２０日ぐらいですかね、早ければ早いほど前向きに考えているということであるし、貢献していることになると思うのです。パーテーションがどういう形になるとどこに滞留してしまうかとかというのが、その辺の考え方、対応についてお聞きします。","respondent":"工藤品川区清掃事務所長、中島防災課長、平原防災体制整備担当課長","answer":"私からは、２点のご質問にお答えいたします。すぐさま広報活動という部分を考えてございまして、そういった形で… 私からは、電源の整備のこれまでの実施と、今回の補助金と避難所の電源確保との違いについて答えします。その点の違いです。製品によっては１２０ｃｍから１８０ｃｍなどと様々なものがありますけれども、高さの違うものもご用意させていただきたいと考えています。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のお話をよく伺うと、品川区を通っているところがいろいろあるからと言うのだけれども、この辺のところがよく分からなかった。国には、だから２分の１だと全部出ているのかとか、そこら辺を少し説明を求めました。","respondent":"鈴木都市計画課長","answer":"やはり先ほどご説明した減便、一方ではやはり区としては、地域の身近な移動手段であるバスというのをしっかり考えていかなければいけないと。「何か区としてもご支援いただけないでしょうか」というお話も、今ご説明した、２分の１を出す。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"では、基本的には、国が２分の１出します、東京都は出しません、区が４分の１出します、事業者が４分の１出す、という理解でいいのかな。「これくらいの話は面的に特別区でやろうぜ」というぐらいの、そのほうがよかったような気がするのだけれども、どうか尋ねました。","respondent":"鈴木都市計画課長","answer":"枠組みについては国が２分の１、東京都が路線バスについては出さずに、区が４分の１という枠組みで、ご説明いただいたとおりです。この検討をするにあたっては、先ほどご説明しましたように、バス事業者はほかの自治体も含めていろいろ要望を行ってきたというのは伺っています。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"確認","question":"１つ確認なのですが、都バスは東京都が全部やるという理解でいいのでしょうか。それだけ最後、確認したいと求めました。","respondent":"鈴木都市計画課長","answer":"都バスについては、東京都が自ら行うという理解でおります。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"今まで購入していなかった方の中でどういう層の方が増えているのか、もし傾向が分かれば、併せてお知らせほしいと求めました。本来は、都市計画課以外の所管からもそれぞれ資料が出るべきかなと思いますけれども、口頭でお聞きしたいと思います。","respondent":"工藤品川区清掃事務所長、中島防災課長、平原防災体制整備担当課長","answer":"厳密にアンケートをしたわけではないのですけれども、やはりご家庭での使用ということで、ご家族３人、４人という方が多いようです。… 私からは、電源に関する補助金の内訳について説明をします。制度上６０万円の上限を設けてありますが、過去の実績に倣いまして… 簡易間仕切りですけれども、こちらにつきましては、そちらの２倍の数の方に対応できるということをまず基準とさせていただきました。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどもありましたけれども、やはり資料ですね。やはりこの補正予算の冊子になっている資料だけでは分からないところも多々ありますので、ぜひ今後、資料を付けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"ほかの委員からもあったのですが、やはり資料をもっと充実させてほしいと求めました。賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"令和２年陳情第４３号、「品川区自転車ネットワーク計画を含む自転車活用推進計画」（仮称）を策定することを求める陳情","agenda":"令和２年陳情第４３号、「品川区自転車ネットワーク計画を含む自転車活用推進計画」（仮称）を策定することを求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ネットワークですから、やはりこのネットワークを形成していくためにも、品川区でも計画の策定が必要だと考えております。この中で、品川区が自転車の活用をしていく意義をどう考えていらっしゃるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"まさに国の法律、側面的にはもうシェアサイクル等で実施しているところもありますが、観光での側面等もあろうかと思います。区としましては、この自転車の活用を今後区としてどう考えていくかというところは、今後についてしっかり検討していきたいです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"自転車活用を推進していく意義ということが語られましたけれども、その中で今ご答弁がありました、検討していくということです。なぜできないのか、策定するという方針をもっているにもかかわらず策定されないのか、そこの理由を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"本来であれば、この上位計画に基づいて、区としてもしっかり検討して、策定に向けた検討を進めていくという姿勢は、以前も今も変わってございません。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"他自治体とのつながりということもあるので、都の計画とかというのは、確かにその中身を勘案してつくっていくということは必要だと思います。その改定というのはいつまでにできて、それができたら品川区も早期に策定に取りかかるということでよいのか、伺います。","respondent":"鈴木都市計画課長","answer":"当初の計画が２０２０年度、また東京都においても、区としては来年度からは両計画が改定されるものというふうな受け止めでおります。これは予算的な検討を今まさに行っていまして、その出された両計画をしっかり見据えながら、検討・策定を進めていきたいとは考えてあります。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"その分、大気汚染が軽減していくということでもありますので、そういった形で進めてほしいと求めました。改めてというか、自転車の利用が大気汚染の改善にどのように寄与していると区のほうで考えていらっしゃるか、そこを最後に伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区内で自動車等をお使いの方が、自動車を使わずに、買い物、あるいは通勤等で自転車をお使いになるということは、やはり低炭素の観点からも環境に優しいというふうに、区としては受け止めているものです。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"この品川区でも、大きな道路、国道などができて、ぜんそくの患者の方などが増えました。やはり環境面を改善していくためにも、ぜひ自転車ネットワークを含めた自転車活用推進計画を迅速に策定していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"都と国の改定を見てから、でも、きっとこれまでの東京公害患者と家族の会品川支部の方たちとの話し合いの中でも検討はされてきたと思います。今、区としてどういう推進計画をつくっていくのか、どのような検討をしているのかというところを確認させていただきたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"区としては自転車の活用が進められていたりして、少し地域によって、区としてはどうしてほしいのかが分からない状況というのがあるのです。やはり方向性はきちんと位置づけるべきだと思いますし、国、その辺についてお伺いできればと思います。","respondent":"鈴木都市計画課長","answer":"違法駐輪対策ですとか、駐輪場の整備計画ですとか、やはり総合的に位置づけていかなければいけないというふうには考えてあります。繰り返しになりますが、どこに力を入れてどういう形で取り組んでいくかというところは、しっかり計画の中で総合的に検討していきたいです。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問","question":"もしかしたら住民にとっては、そういったこととかを踏まえて、いろいろな方が集まって意見を言えるような場を設けてほしいと思います。もし答弁があれば、お願いします。","respondent":"鈴木都市計画課長","answer":"どういう形で策定検討を進めていくかというところは、検討会の立ち上げですとか、その辺もしっかりと検討していきたいと考えています。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"ある意味で品川区ももうかなり進んでいるのではないのですか。それをまとめていくというのは、作業的にはすぐにできるのではないのでしょうかと考えていますが、そのお考えですよね。","respondent":"鈴木都市計画課長、川口交通安全担当課長","answer":"シェアサイクルの実施にあたっても、それから実施計画、２つ検討して。スピード感をもって、検討、策定を進めていきたいというふうには考えてあります。 私から、自転車の保険の関係につきまして説明します。都内１,０００人にウェブアンケートを実施した際には、さらに個別に加入の周知に向けて、広報活動を進めていきたいと考えております。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"やはりそれを軸としてきっちりと位置づけて、区民の方々に周知して、計画的に行っていただきたい。純粋にこの陳情の内容から建設委員会にかけられたということの経緯から、判断したいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"自転車レーンであるとか、いろいろ個々の実態の中で計画をどういうふうに考えていくのだというのは、非常に個々にわたって様々な面があると思います。そういう状況ですので、この陳情については不採択ということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"大沢委員","kind":"質問","question":"来年度に向けて予算立てをしているという、この件に関してはもう積極的に動き出しているところでありますので、採択をする必要はない。よって不採択ということで、今、お話しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"令和になる前の第４回定例会で、いわゆる「不要不急の自転車の使用は控えてください」というのが区全体としての当局の一貫した見解でございました。これまで積み重ねてきたものが品川区にはあるわけですから、そういう意味で、私どもとしてはこれはもう不採択で結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"交通ルールの周知などもぜひやってほしいと求めましたし、とらわれず、できるところは区としてぜひ進めてほしいと求めました。ということで、採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"いろいろな市民が関わって、いろいろな意見を盛り込んだ計画になるといいなということを、要望したいと思います。採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"それが、国、都とももう作業が始まっているという段階ですから、恐らくは品川区も早々に始まっていかなければいけないことだろう。様々な観点でも、これは非常に大切な位置づけだと思いますので、採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の意思が確認されないまま、推進側が一方的に進めるこの再開発事業をやめてほしい、そのためにまちづくり勉強会の中止を求めているものです。勉強会発足の経緯を伺います。","respondent":"多並都市開発課長","answer":"その中の有志の中に権利者の１つとして、その中で話があって、東急株式会社が事務局になって進めていると。そういうのを１回目から２回目と順を追って、区としては、オブザーバーとしても参加させていただいているところです。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"そうした中で、質問に答えられないというのはなぜなのか。そこがやはり地権者の方が、住民の方が質問しているところで、区のお考えを伺いたいと思います。","respondent":"多並都市開発課長","answer":"一緒に考えていくというのが重要なところですので、質疑云々というよりは、まずは皆さんで一緒に考えていくムードというのが非常に重要だと思います。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"多くの方に、その中で質問にまともに答えてもらえないというところで、答えられない理由があるのかなと思ってしまうわけです。双方の意見を聞いて、話し合いの場を作るというのが、少なくとも区のやるべきことなのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"新しく皆で作り上げていきたいという事業の趣旨としては、区としても考えてくださる方々については支援していきたいと思います。それはもちろん区としても支援、または助言させていただきたいと思っているところです。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"今心配する会の方々が話し合いをしようと求めても、返事もないという中で、話し合っていく土壌ができていないわけです。区としてどのように関わっていこうと考えているのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"このまちの将来を考えるときに、様々なご意見の方がいらっしゃるので、その方々がお話し合いされることが非常に重要だと思います。そこの会の中の皆さんの考え方には、進め方も含めて、よりよい方向にいくようにという形で一緒に進めていきたいと思っているところです。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"そこのところについて、区がどのように関わっていくのか。私は間を取り持って話し合いができるようにしていくということが必要だと思うのですけれども、そこのお考えを伺いたいと思います。","respondent":"多並都市開発課長","answer":"どういう進め方がいいのかというのは、それこそ本当に皆さんとよく話し合いながら進めていくべきものだと考えているところです。区としてまずは皆さんのご意向をお伺いしながら、最適な方法というのは見つけていきたいと思っているところです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"つまりどういうことかがよく分からないのですけれども、区としては見守っていくということなのですか。区がここでまちづくりを進めていこうと思えば、話し合いを取り持っていく必要があるのではないかというふうに思うのですけれども、改めて伺いたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"住民の合意が重要ですから、それは話し合いをしっかりとしていけるように区としても支援をしていくべきなのではないかと、私は思います。そういった中で、このまちづくり勉強会というのは、都市計画手続きの一部ではないのかというふうに思ってしまうわけですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"再開発という言葉の中に、市街地再開発事業という事業が事業の１つであるのですけれども、それ以外に都市計画法に基づく事業手法は様々あります。したがいまして、市街地再開発事業に直結するというわけではないというふうに区としては認識しております。","id":"exchange-060"},{"speaker":"のだて委員","kind":"意見","question":"再開発で３分の２が同意すれば進められてしまうということにもなりますので、長年住み続けてきた住民が合意していない中、追い出されてしまうと。こうしたことはやめるべきだと思いますし、こうした再開発は人権侵害ではないかと私も思いますけれども、いかがでしょうとの意見を述べました。","respondent":"多並都市開発課長","answer":"これはもちろん憲法にも従うところです。必ず法令遵守の形で進められるよう、そこの点はよく注意しながら指導・助言というのはそういう意味でもさせていただきたいと思っているところです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"正当な権利を侵してはならないということで、ここに住み続けてきた方々が生活を奪われるというのは大きな侵害だと思うのです。ですので、それが起きないよう指導していくということで、改めてお考えを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問","question":"陳情の中の項目２にある「再開発事業は」から始まり、「疑問・質問等に、先ほどご答弁があったとおり勉強会での質疑でのことを指しているのか。そういったことを、もし区が把握をしていれば示すよう求めました。","respondent":"多並都市開発課長","answer":"「今回の趣旨は幅広く勉強していますから」ということで説明されているのが何回か繰り返しになったときに、区としては受け止めているところです。","id":"exchange-063"},{"speaker":"田中委員","kind":"意見","question":"この陳情項目の中の１から４に関してはとても分かるのですけれども、５の部分がとても気になってしまっています。生活者ネットワークとしてはできないのですけれども、陳情者の怒りなどはとても分かるので、ぜひ区として調整をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"３０年前ですか、いろいろ議論がなされていて、立ち消えになった。ですので、すみません、質問ではないのですが、意見としてこういう意見が出たということは非常に残念だというふうに意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"再開発を心配する会の方々も２回ほど開催をされてきたということでありまして、今そういうふうにして、地域の中でどういう形で話をしていくか。不採択で必ず来ておりますので、それをご理解いただきたいと思っておりまして、これに関しては不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"若林委員","kind":"意見","question":"本日結論を出す、でお願いします。今の民民というところも含めて、私どもとしては採択しかねるということで、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"少なくとも話し合いができていないというところを、区が話し合いをしていくようにしていくべきだと私は思います。住民による話し合いをしていきたいという思いで勉強会の中止を求めているものだと考えますので、結論を出すということで、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"田中委員","kind":"質問・要望","question":"そうしていってほしいなというのは強く要望したいのと、また、この項目２にあるこの請願者の方が回答がされていないというところについても……。請願じゃないよ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"共通した思いの中で、ではどうするのだという話し合いが、今勉強会をやめていただきたいというのは逆行しているなと非常に残念に思っております。前向きに、ハードルは高いでしょうけれども、様々試行錯誤しながらやっていただきたいというふうに願っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]},{"id":"topic-04","title":"の(2)広町地区におけるまちづくりの検討状況","agenda":"の(2)広町地区におけるまちづくりの検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"報告について伺いたいと思います。都市計画手続きというのは何を指しているのか、伺います。","respondent":"多並都市開発課長","answer":"来年度の都市計画手続きの予定ですが、時期自体は未定です。この２つが種類です。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"都市計画手続きの地区計画をやっていきたいということで、その中には土地の再編のことですとか、あと、新たに道路を造ることになりますから、道路の配置とかそういう計画を載せてということが含まれるのか、伺います。","respondent":"多並都市開発課長","answer":"いわゆる整理後の姿をもって地区計画というのを定め、合わせて、要するに整合性を取りながら行っていくというのが今の考え。その中では道路であったり、各敷地がこのような形で示されるということで出てくるという予定です。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"どういうイメージなのかというところを伺いたいのと、あとは、これはつまり今回示された交通広場のことを指しているのでしょうかということ。もう少し具体的に伺えれば。","respondent":"多並都市開発課長","answer":"今それは区だけではなくて、よりよい形にできないかということで検討しているというのがここに書いてある交通結節機能の強化というところです。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"ＪＲと何か土地を売らないということとか協定をやっていくというお考えなのか、そこを伺いたいと思います。妥当性というのですか、必要性がよく分からなかったのですが、どういうことなのか。","respondent":"多並都市開発課長","answer":"ただ、交通広場自体は、今検討の中でお話ししているのは、立体的に区のほうで管理する形にできないかと。今後の交通の結節機能の連携を図ることを考えると、その中でほかの交通手段とも連携して進めるような形でできないかということで。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"区が整備すれば区が管理していくということになるのでしょうか。そこの点を伺いたいと思います。","respondent":"多並都市開発課長","answer":"これも基本的には、そこの１階部分というところを立体道路という手続きがありますから、そういう形で区の道路として担保できないかと。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"事業として道路を造って、最終的には区が管理をしていくということでしたけれども、新たに道路を造って、道路づけをよくして、ＪＲの開発を進めるために道路整備を行うということになってしまうのではないかなというふうに思うのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"より整理をしていくという事業の手法ですので、そちらを活用して、土地を再編していくというまず基本的な考え方です。道路敷地に充てていくということが土地区画整理事業の基本となりますから、公平性の中で行うものというふうにご理解いただければと思います。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"先ほどパブリックコメントを実施する要綱に該当しないと考えたということですけれども、具体的になぜ対象にしなかったのか。なぜやらなかったのかというところと、今回との違いというのは何か、伺いたいです。","respondent":"多並都市開発課長","answer":"今回の場合、(2)の「各行政分野の施策の基本方針または基本計画の策定および重要な改定」ということで、これがその中ではあたるかと思います。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"ですから、まちづくりの問題でも基本方針でも、この間パブリックコメントをやってきているわけですよね。そうすると、今までの考え方とは変わったということなのか、伺いたい。","respondent":"多並都市開発課長","answer":"先ほどご説明しましたが、まちづくりの進め方ということで地域等主体でやっていくという考えがあるので、先ほどもお話しさせていただいたところです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"この大井町駅周辺地域まちづくり方針についてパブリックコメントを実施しないという理由はないのではないかなというふうに私は思います。広く区政に参加してもらうという意味でも実施すべきだというふうに考えておりますけれども、コロナ禍のもとということについてお考えを伺います。","respondent":"多並都市開発課長","answer":"今回の説明会につきましても、会場については定員の半分とさせていただいて、間隔を取りながら行わせていただきたいと思っています。電話の問合せ等にも丁寧に説明させていただこうと思っていますので、今までもそうでしたけれども、説明会に来られた方のご意見だけではなくて。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"最後に伺いたいのですけれども、説明会終了後に資料を公開して意見を聞くということでしたので、それは取りまとめて、ご意見がありましたということで公開されるということでよいのか、伺いたい。","respondent":"多並都市開発課長","answer":"基本的には、まずは説明会のときのご意見を載せさせていただきたいなと思っています。計画を進める際に参考にするというのが基本的な考えですので、可能な限りは対応し、やり方についてはまた研究していきたいと思っているところです。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ広く意見を聞くという意味でも、パブリックコメントを実施していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"田中委員","kind":"確認","question":"陳情についてお話を伺えればと思います。パブリックコメントはすごく重要だと思うのですけれども、それでも区の姿勢というのは変わらないのかというところを確認したいと思います。","respondent":"多並都市開発課長","answer":"ただ、説明会の開き方についてというお話かと思いますけれども、今回は会場を感染に配慮した形でするとともに、あとは説明会の資料。そういう形で丁寧にさせていただいて進めることが肝要ではないかなと思って、区としてはそのように進めていきたいと思っているところです。","id":"exchange-082"},{"speaker":"田中委員","kind":"確認","question":"要綱を確認したときに、次に掲げるものとする」の(1)で、庁舎のことは必ず絡んでくる話ではないでしょうか。この流れが分かるもの、その流れが分かるものというのはどこに示されているのかということを示すよう求めました。","respondent":"多並都市開発課長","answer":"一定の規模以上のときには説明会を義務づけられたりとか、必要に応じた具体的な内容でご説明して、そういう中で絡んできているものです。標準的なフォーマットのやり方というのがありますから、また機会を捉えながら、ご説明しながら進めていきたいと思っているところです。","id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"行政側にとっては、区民にとっては全くそこは分からず、同じ地域で起きているまちづくりの１つとして捉えているのです。行政機能もあるので、ぜひ声を聞いてほしいといったことをこの陳情は求めているわけで、分かりやすく手順というのを公表してほしいというのが１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問","question":"候補地というのは確定しているのかどうかという話で、それを示してほしいという委員からのご意見が機能検討委員会ではありました。庁舎についても、このまちの全体のイメージというのができているのではないかなと思うのですけれども、そこを報告してほしいのです。","respondent":"多並都市開発課長","answer":"機能検討委員会につきましては、今日の資料の３の土地利用区分の中の「新庁舎建設候補地」と書いてあるここのところに印をつけてあります。それを前提に機能検討委員会のときにも説明させていただいて、ただ、今お話があったように。","id":"exchange-085"},{"speaker":"田中委員","kind":"意見","question":"機能検討委員会の１回目のときに、２回目のときには、そこがもう確定なのかどうかというやり取りがあったと思うのです。でも、今こうやってまちづくりとして示されているのであれば、ある程度出してほしいのですがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問・要望","question":"僕らも一生懸命聞いているのだから、もう少し分かりやすい言葉で、もう少し分かりやすい説明をしていただきたいと思うのです。区から資料が出されているのは、これは何でしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"大沢委員","kind":"意見","question":"その中で、あくまでも、今、話になっている陳情の主体となっているところというのは、この大井町駅周辺の一開発地域にしか過ぎないわけですよね。","respondent":"多並都市開発課長","answer":"今の委員のご指摘のところが我々の趣旨でありまして、この各地域のまちづくりの情報ということですので、区としてはパブリックコメントの対象にはならないということで判断しているものです。","id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問","question":"不採択でお願いをします。理由としては、先ほど大沢委員が質問し、行政が答弁したとおりで、私もそのとおりで結構だと考えていますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。主に区役所、こちらのほうにパブリックコメントを実施される際にはぜひお寄せいただきたいなという感想をもっていますので、不採択で結構だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"のだて委員","kind":"意見","question":"先ほど来、１つのところを指してということですが、区役所もあるし、広町地区の問題もありますし、大井町の広範囲の方針だと私は思っております。ぜひ住民参加を広げていくためにも実施すべきと考えますので、本日結論を出すということで、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"田中委員","kind":"質問・要望","question":"素案の中の１１ページで、庁舎のことにも触れており、区民としてはパブリックコメントを実施したいという思いはとてもよく分かります。ですので、ぜひ実施をしてほしいという要望も併せてしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"パブリックコメント自体について、パブリックコメント自体については、これからいろいろと議論をしていかなければならないことだろうと考えています。今回の陳情に関しましては、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"}]},{"id":"topic-05","title":"の(1)コミュニティバス導入に向けた検討状況","agenda":"の(1)コミュニティバス導入に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この陳情代表者の方からお話も伺いました。形式というのですか、そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"昨年度検討を進めてまいりました候補ルート案３案について、より具体的なご意見をいただくということでワークショップを実施したいと考えています。いろいろ検討を行いましたが、いろいろ検討を行いましたが、ご意見をいただくというふうに考えてあります。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"公募区民の導入について検討をしていただきたいと思うのですが、いかがでしょうか。荏原文化センターのほうも通ってほしいということでありましたので、ぜひ検討していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"検討会を３回行いましたが、地域に対しても説明をさせていただき、ご意見もいただいてまいりました。当然ながら実施にあたっては、中身をよく精査して検討していかなければいけないというところもあります。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"けれども、ここでも声を紹介させていただきましたので、ぜひ検討の中に入れてほしいと求めました。どちらも便利なコミュニティバスにしてほしいということで述べられているということだと思うのですけれども、区のお考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"あるいはバス停から遠い、近い等々１１項目で、そこは定量的な指標をもって客観的にしっかりと検討をこれまでも進めてまいりました。これからもその視点を大事にして、検討を進めていきたいです。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"客観的に進めていきたいということですけれども、ぜひ区民の意見を聞いて、いろいろ反映できるように進めていってほしいと求めました。は報告について伺いたいと思うのですけれども、１回目の地域公共交通会議で、本当に使えないのかというところで伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区民の代表の方というよりも事業者、その関係の方からご意見としていただいて、基本的には区の受け止めもそういうふうな形で認識しています。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどご紹介があった２７ページの図３０のところにも、今回３つの候補ルートの中に、なぜ候補ルートに入ってこなかったのか。そこのところを伺いたいのと、旧東海道のところを通っていただきたいという声も寄せられまして、お考えを伺いたいと。","respondent":"鈴木都市計画課長","answer":"基本的には先ほどご説明した１１の指標をもって、ルートの選定にあたっての７つか６つほどの視点も方針の中では提示していますが、公共施設。様々なルートは検討しましたが、そうした視点から、なかなかルートとして通れないというところも実際としてはあります。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ回ると遠回りになったりもしますけれども、それでもバスに乗って着くということになれば、お年寄りの方も便利に、多少遠回りでも利用するということになると思いますので、利用されるルートにしていくという点でも、ぜひ検討していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"田中委員","kind":"確認","question":"資料３の今後のスケジュールについて確認をしたいのですけれども。９月下旬から１１月下旬にかけて、１３地域でのワークショップを行うということだったのですけれども、その周知方法について確認したいと求めました。","respondent":"鈴木都市計画課長","answer":"資料につきましては、９月下旬からというふうになってありますが、地域センター管内を回って町会の方々にご説明をこれまでしてまいりました。先ほどもご説明しましたが、実施の説明については、こういうことを行っていきたいということをご説明し。","id":"exchange-100"},{"speaker":"田中委員","kind":"質問・要望","question":"各地域でいつ行われるのかといったことを、後で一覧として資料提供していただきたいと思うのですが、いかがでしょうか。今、町会宛ての通知や地域センターで話を進めているということなのですけれども、そこら辺についてのお考えを示すよう求めました。","respondent":"鈴木都市計画課長","answer":"日頃から町会の役員、特に会長を通じていただくご意見は、その推薦については役員に限らず広くご推薦いただきたいです。昨年度のコミュニティバスの検討会の実施状況は、検討会で使われている資料も直ちに公表してまいりましたし、議事録についても公表しておりますので。","id":"exchange-101"},{"speaker":"西本委員","kind":"意見","question":"推薦があって行くわけですよね。〔「そうだよ」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"田中委員","kind":"質問・要望","question":"ワークショップについて、傍聴は可能でしょうか。いろいろな地域での意見というのが聞けると思うので、ぜひ傍聴もさせていただきたいと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"１３地域の方、検討を進める中で、区内全域にアンケートも実施しています。やはりコミュニティバスをしっかりとまとめて、その手法について、１３地域一堂に会してご意見をいただくということは今は考えてございません。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問","question":"どういった様々な意見が各地域であるのかというのが、ぜひ傍聴は可能にできるようにお願いしたいと思います。いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"当委員会、あるいはホームページ等でも、あるいは検討の会議体でも。反映された意見だけではなくて、いただいたご意見というのはしっかりと取りまとめをして、広く皆さんに見ていただけるように工夫を行いたいです。","id":"exchange-104"},{"speaker":"西本委員","kind":"確認","question":"１ルートにするのですか。今さら聞くのですけれども、１ルートに決めるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"場合によっては３ルートもありますでしょうし、２ルート、あるいは１ルートのみという場合もあります。３ルート案について、先ほどご説明した運行間隔ですとか運行時間帯ですとか、反映していきたいという観点です。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"３つのルート案ができて、事業者選定をしようとやっていく中で、それでも涙を飲んでいるところはたくさんあるわけではないですか。意見を求めるなんて、私は非常に混乱するもとではないのかなと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"それが反映できるかどうかというのは当然検討が必要であると思いますが、多少そこを寄って、最後の候補ルート案として詰めていきたいと思います。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"非常に誤解を生んだり、過剰な期待をしていたりということにならないように、ぜひ配慮していただきたいなというふうに思います。せっかくここまでいろいろ検討されてやってきているので、それが崩されないような状況で、しっかりと進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、３案が出てきた中で、先ほどおっしゃったようなこととか、西大井も警察がいいと言えば通れる道路も出てくるわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"大沢委員","kind":"意見","question":"しかしながら、住民意見に対しても行政が受け入れるものの限界というものがあるのではなかろうかなと思います。ポピュリズム的になると思いますので、お気持ちは十分に分かりますけれども、この陳情に関しては受け入れることができないとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"のだて委員","kind":"質問・要望","question":"便利なコミュニティバスを求めるという陳情でありますし、住民の声を反映して、便利なコミュニティバスにしていくということが必要だと思います。議会として区民の声を受け止めて反映させていくというためにも、本日結論を出すということで、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"この要望については、話し合える場がなかった上でこのような意見が出されたということから、その趣旨には賛同したいと。例えばこの基本方針（素案）の２８ページの携帯電話の位置情報であったりとかも、各地域の方々皆が各地域について理解できる場を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"ここまできっちりやって、ここまでの中で３ルートにしたのですよというのは、しっかり伝えてほしいと求めました。それと、どういうふうな解釈をもってやっていくのか、そうではないのかということの現実をしっかり見ていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"のだて委員","kind":"意見","question":"共産党としては採択をしたいと思いますけれども、採決は１回しかできないということで、区民の声を受け止めるということを多くの議員で示していくということも重要だと思いますので、趣旨採択に変更したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4300#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":88871,"voices":312}},{"id":"r02-20200923-9","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"文教委員会","time":"午前１０時００分～午後 ４時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を143件整理しています。","topics":[{"id":"topic-01","title":"第５８号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第５８号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"その理由をお伺いしたいのと、品川区においては、具体的に何の事業を指すのか伺いたいと思います。事業実績をそれぞれ簡単に説明を求めました。","respondent":"若生保育支援課長","answer":"それから２点目のご質問ですけれども、当区における実施状況等ですけれども、子ども・子育て支援法の改正によって。居宅まで保育者が訪問して１対１で保育をするという事業でございまして、品川区では、１事業者が実施しています。","id":"exchange-001"}]},{"id":"topic-02","title":"第６１号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第６１号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回は、(1)の公務災害補償の限度額の引上げの改正ということですけれども、この限度額を引き上げることになった改正の理由についてお伺いしたいと思います。","respondent":"篠田学務課長","answer":"今回、大元となった文部科学省の所管する政令、こちらの改正の理由としているのは、労働者災害補償保険法の施行規則が改正されまして、その水準と合わせて、こちらのほうも見直しをしたと聞いているところです。","id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問","question":"今回改正されるこの介護補償と災害の発生日の法定利率も含めて、毎年、このような条例改正はあるのですけれども、学校歯科医の公務災害補償ですが、直近というか、ここ１０年、２０年で分かる範囲で結構ですけれども、このようなものを使われたケースがあるのか、分かれば説明を求めました。","respondent":"篠田学務課長","answer":"平成１４年の「三位一体改革」を受けた都からの制度移管により、区が独自で持つという形になってあります。それ以降、品川区では、１件も公務災害補償に関しては発生していないという状況です。","id":"exchange-003"}]},{"id":"topic-03","title":"第５６議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５６議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"教育委員会所管のほうについてお伺いしたいのですが、地域の保護者からご相談もいただきまして、要望させていただいておりました。それとも国がある程度メニューを示して、そこから選んでもらうような枠組みなのか、そういうことについてお伺いします。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"１点目の修学旅行の実施状況についてですが、現在、１５校中７校が中止となっています。今後の予定を、新型コロナウイルスの感染状況を鑑みて、学校のほうで検討していくところです。国からは、あるいは学習保障として、３密対策として空き教室等を活用して授業を実施する場合に必要となる備品の購入費等が挙げられているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"新たに２校中止が出ているということがありますし、予算を組んで対応すべきだと思いますけれども、いかがでしょうか。都や国の補助金は使えるのでしょうか、伺いたいと思いますし、もしつかんでいるところがあれば説明を求めました。","respondent":"有馬庶務課長","answer":"今後発生した場合については何らかの対応をしていくと、我々も考えているということですので、公費負担をしていきたいと考えています。公費負担しているところは半数以上と捉えておりまして、それから、それ以外のところも負担を検討中と聞いております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"入園事務業務委託の拡大ということですけれども、現在の委託職員の増員だと事前に伺いましたが、何人を増やすのかを確認したいと思います。その理由は何なのか伺いたいと思いますし、いわゆる非常勤と言われていた方についても、区立であれば出さないというような状況だと思うのです。","respondent":"立木保育課長","answer":"窓口電話対応業務、在園継続事務、そのほか随時必要と思われる業務をお願いしているところです。そこはしっかりと職務を果たしていく中で、身分保障もしっかりとしている中で、今回の給付金は該当させないと判断したものです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"それと、同じ仕事をしているので、支給すべきだと私は思いますけれども、それはいかがでしょうか。保育士へのＰＣＲ検査も行うべきだと思いますし、その実施を求めたいと思いますが、保育部門の考えはいかがなのか伺いたいと思いますとの意見を述べました。","respondent":"立木保育課長","answer":"窓口および電話対応業務では、ご説明が足りなかったかもしれないですが、在園事務全般に対する案内および受付という形で委託を出しております。保育現場に対してのＰＣＲ検査の予定はございませんが、今後、情勢に合わせて考えてまいりたいと考えています。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは６月の一般質問でも要望いたしまして、ほかの会派からのご要望もあったと思いますけれども、非常にありがたいと思います。それから相談支援のほうですけれども、これは、品川区専門の窓口を設けるということなのか尋ねました。","respondent":"若生保育支援課長、立木保育課長","answer":"今回は、それに加えて、さらに１園に５０万円がつくということで、都から１０割で出ているものです。コロナ禍が継続していく状況も予想されるところで… １名増員したことによって、明確な例えば削減効果が見込めるかどうかは、ひとつ大きなところです。応援金をというようなお話は… 相談支援の件についてのご質問ですが、これは品川区として設置をして、不安を抱えている方を専門に相談業務を行うということで考えてあります。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"特に新型コロナウイルス感染症ですし、保育課ならびに区の職員をもっと増やしてほしいと考えていますが、それについてもご見解を教えてください。これはいつ頃からスタートするのか、それから、何人ぐらいで受けられる体制になっているのか、そこの具体的なことを教えていただけますか尋ねました。","respondent":"若生保育支援課長、立木保育課長","answer":"やはり、そういった事業所の状況等もお聞きしながら、丁寧に対応していきたいと思います。そういったところで、専門のスタッフが対応しまして… 今回は、いろいろな手法を使いながら、少しでも窓口混雑を緩和できるようにやってまいりたいと考えています。職員のことに関しましても… すぐに準備等を行いまして、見積もり等は専門業者から取っているところですので、できる限り早く対応していきたいと考えています。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"要望とはいえ、見通しを教えてほしいと求めました。それとも、何か清算して、使わなかったら返すみたいな感じになるのか尋ねました。","respondent":"矢部教育総合支援センター長、篠田学務課長、若生保育支援課長","answer":"まだこれから実施予定の学校もありますので、中止になった学校につきましては、日帰りも含めて思い出作り中心の行事ができるかを検討中です。最終的に国庫の補助というものですので、必要な書類等を整備しまして、国に出して報告していることになります。ほかの予算でもそうなのですけれども… 当然、そういった対応にも、コロナではないからといってお断わりすることはないような形で、仕様のほう等も考えていきたいと思ってまいります。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"そうではなかったにせよ、これは具体的にどのようなシステムなのか。民間とか他の自治体で実際に使われているものなのか、具体的にどのようなシステムになるのかを説明するよう求めました。","respondent":"立木保育課長","answer":"こちらのシステムに関しましては、補助金を充てる際に、例えば東京都からこのような形でという指示があったということではございません。そういったところをいろいろと調査・検討した結果、これからこの契約でやりますという、予算をご承認いただければ出すという形になるです。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"具体的にどのようなシステムにするのか、どのような会社を選定するのかはこれからということでよろしいのか尋ねました。","respondent":"立木保育課長","answer":"今、特に随意契約でいくということではなく、必要な機能もこちらで絞り込みまして、それに合致するものを導入するという形で検討しているところです。","id":"exchange-012"},{"speaker":"筒井委員","kind":"確認","question":"他の委員からもご質問が出ていますけれども、これは別に公立保育園の保育士も相談を受けてもいいということなのでしょうかということの確認が１点。現時点のそうしたお悩みを抱えた保育士の数とか、おおよその感触というか、そうしたものは把握されているのか尋ねました。","respondent":"吉田保育施設調整担当課長、若生保育支援課長、立木保育課長","answer":"メンタルヘルスの関係につきましては、区立民営保育園が４園ありますけれども、指定管理もしくは委託にしているところが対象になっている次第です。 どういった対応をしていけばいいのかですとか、様々ご相談、不安の声等は頂いているところです。全国の社会福祉協議会が実施した保育士等へのアンケート調… そちらのほうでメンタルヘルス等を３段階、外部等を含めて段階をもって対応できる形を、そちらのほうで対応できる形になってあります。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"確認","question":"これは、この間の一般質問でも、この２万５,０００円なりがその保育士の手元に直接行っているということの報告を受けるということでいいのですか。要請をした上で、行ったかどうかの報告も取る、間違いなくご本人の元に行くことが確認できるのかということを確認したいと思います。","respondent":"立木保育課長、若生保育支援課長","answer":"引き続きそこは丁寧に対応するということで、引き続きやらせていただくということで、そこは変更するところではございません。引き続きやらせていただく予定です。 確実にこれが一人ひとりに渡っているかどうかというところは、それを事業者にお送りするという形で、確実に報告を求めたいと考えています。こういった趣旨で、きちんと伝わるように事業者等に説明していきたいと考えております。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ハンドソープがいいという明確な医学的なものはないと伺っているので、学校で先ほどの２００万円が最大で、学校によってはそのようなことを使われる。これは要望として、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"２点ほど伺います。保育士等への支援、応援給付金ですけれども、書いていないので確認ですが、すまいるスクールの職員は入らないのかを説明するよう求めました。","respondent":"立木保育課長、廣田子ども育成課長","answer":"窓口で受付やご案内をさせていただいたことに関しましては、きちっと入園相談担当職員と課内で共有されて、一律に同じ対応ができる形を取らせていただいております。スタッフの数も少なくなっているのですが、金額は落とさずに、もともと人数が多いスタッフの想定のままお渡ししています。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"いま一度、情報を統一していただいて、同じように案内できるように確認をお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"ウェブ予約ができるようになるのはすごくいいと私は思っておりまして、こちらはいつ頃にスタートできる見込みなのでしょうか。今後についても検討をぜひしていただきたいとは思うのですが、そのあたり、区のお考えを説明するよう求めました。","respondent":"立木保育課長","answer":"考えておりまして、１２月の一番混雑する時期前にとにかくスタートしないと意味がございませんので、準備を進めているところです。オンラインやリモートでの相談に関しましては、どういったことができるのかは、しっかりといろいろな事例を見ながら研究してまいりたいと思います。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"もし早めに申請が可能な方、併せて周知していただきたいと考えていますので、工夫していただきながら進めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"先ほど、空気清浄機が入っているところに何個も送ってもしようがないのかなとも思っていますので、これはぜひ希望を確認をしていただきたいのが１点。これは予算を見ると、来年度以降も必要があれば、区の予算も考えながらやっていきたいというようなものでよろしいのかを改めて説明を求めました。","respondent":"立木保育課長、吉田保育施設調整担当課長、若生保育支援課長","answer":"私から、窓口の件につきましてお答えをします。それから、お問い合わせがあった際のご案内の中で、しっかりとご利用者の方に周知をしていきたいと考えてお… 導入を予定しているものは、児童センターを含め、こちらに記載のところで導入を予定しています。 これは歳入が見込めるかどうかというところは未確定というか、来年度予算の検討を進めていくところですので、また考えていきたいと考えています。","id":"exchange-020"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"相談が終わった後や、今後はウェブでのシステムをこれから導入していきますという案内をしてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"公立で働けば、あるいはどのようにお考えなのか教えていただきたいのと、そういった方もご相談を受けていただけるのかを確認できればと思います。人はつけてほしいと思うのですけれども、いかがか尋ねました。","respondent":"立木保育課長、若生保育支援課長、篠田学務課長","answer":"メンタルヘルスの区の仕組みの中では、今のところは入っておりませんので、今回のメンタルヘルスのサポートのほうで入れするという形になってあります。そういった専門職を今のところは考えておりますが、また今後、事業の検討の中で考えていきたいと考えています。学校の補助金に関するお問い合わせです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"拡大するというのは問題があるので、やはりこれは正規の職員で対応すべきだという意見は言わせてほしいと求めました。その上で、感染リスクのさらに最前線で働いているのは医療従事者なので、そういったところにも支給を求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"いろいろと要望を出させていただきましたので、そういったこともご検討いただきながら、本件には賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-04","title":"す。 予定表では(1)令和２年度請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)令和２年度請願第１２号…","agenda":"す。 予定表では(1)令和２年度請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)令和２年度請願第１２号…","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"この方ご自身が病院勤務の看護師と伺いまして、保育園に入園できずに退職する看護師が多くいるのだというお話でした。伺いますけれども、現時点で区は、こういった特別な配慮が必要だと考える職種の方々をどのように考えているのかを伺いたいと思います。","respondent":"立木保育課長","answer":"それから支援が必要だと思われる方も、区の姿勢としては何かしらの支援が必要ということは、非常に範囲が広くなります。職種、それからどういった施設・事業所で働いているか等もありますので、そこら辺は慎重に判断することが必要と考えていたところです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"かなりいろいろと、社会を維持するのに必要な職種というのは、本当に広いと思いますし、支援が必要だというのは、私も同感です。中身にも関わると思うのですけれども、保育士の方を加点するということになった理由を聞きたかったので、もう一度お願いします。","respondent":"立木保育課長","answer":"国の通知の意図ですが、国からの通知の中で、保育士が働くことによりまして、その保育士不足でお子さんが預かれないということが解消される。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"保育従事者に調整指数プラス１とされたのは、平成２９年の国の通知によってだというご説明でしたけれども、現時点でどういった動向なのでしょうか。何か区として把握されていることがあったら、説明を求めました。","respondent":"立木保育課長","answer":"今のところ、職業に対しての加点というのは、ご説明に挙げた保育士等だけでございまして、厚生労働省に確認を取ったところ、ほかの職業に対して何かしら通知を出すということは、今のところないと聞いております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"そのようなことですけれども、ただ、区としては、医療従事者に対して何らかの保護というか、そうした優遇策をしてあげたいということでしたが、その１つが、保育園入園時の調整指数加点、こういったことも区としては一方策として受け入れられるということでよろしいのか尋ねました。","respondent":"立木保育課長","answer":"それとも、であるのであれば、むしろ優先順位を上げるという方法も考えられなくはないというふうには考えております。幾つか方法がある中で、どれがベターなのかというところは、いろいろなデータ等も参考にしながら検討する必要があると考えているところです。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"その辺の線引きは、技術的に可能でしょうか。ある程度線引きができるのであれば、ぜひ前向きに考えていただきたいですけれども、いかがか尋ねました。","respondent":"立木保育課長","answer":"１つは、例えば広げるのであれば、「医療従事者プラス介護従事者」というパターンももちろんあります。このどこら辺に線引きをするかというところは、現時点でどの程度というところまでは検討が進んでおりませんで、今後ということになるかと思います。","id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２３区でも少しあるかと思うので、その辺の情報があれば教えていただきたいのと、変な偏見のような報道もあります。変な意味で排除されることがないようなことも、ぜひ今のうちから考えていただきたいのですが、その考え方を説明するよう求めました。","respondent":"立木保育課長","answer":"２３区、このように何らかの形で、優先的入園等の対応をしている自治体はございません。優遇措置をした場合の園での対応、そういったことがないように、そこは改めてしっかりとやっていきたいと考えています。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"質問・要望","question":"さらなる何か、そのような人も中にはいらっしゃるので、そこはぜひしっかりと考えていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"私は、ある程度範囲をしっかりと絞って効果を出していただきたいと考えているのですけれども、そのあたりの現在のお考えはいかがでしょうか。そういった分かりやすいと考える立場から確認ですけれども、ほかにも何かあるようでしたら、区のお考えを説明するよう求めました。","respondent":"立木保育課長","answer":"どの職が欠けても、医療現場は何かしらの不都合が出てくるということで言えば、あまり制限はかけられないのではないかというところが一つあります。なかなか難しいところでありますので、すみません、今はすぐ思いつくところはございません。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"それ以外の区民の方に対して、なるべく早いタイミングで確実に情報が届くような方策を採用していただきたいと要望したいと思います。ひとつの大きな目安としてお考えください」というような一文があるのですけれども、発信できる内容から、周知の考え方について説明を求めました。","respondent":"立木保育課長","answer":"それとも決まった形で出すのか、いろいろとやり方はあろうかと思いますので、その辺は検討してまいりたいと思います。事前に制度上変わることがありますというような表記に関しましては、何か不都合がないかどうかは、確認した上で対応してまいりたいと思います。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"周知をできるだけ多くの必要な方に届く形で検討していただいて、工夫していただけたらと考えていますので、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"芹澤副委員長","kind":"意見","question":"内容としても、医療従事者が先端に立っていると考えていますので、ぜひ後押しをしていきたいという思いでの紹介議員にもなっておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"せお委員","kind":"意見","question":"医療従事者は、本当に大変な状態にありますので、保育をとても必要としていると思います。とても時間がないとは思うのですが、そこの議論もぜひ慎重にしていただいて、こちらをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問・要望","question":"何とか来年の４月に間に合うように、大変ですけれども、よろしくお願いいたします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"一言、述べさせていただきたいのですけれども、必要な保育園整備完了に向けた過程の中での暫定的な措置であるべきだというふうな考えがあります。今こそ保育をはじめ、ケアの手厚い区政にも転換してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。国や都の動向などもしっかりと注視していただくといったことを考慮していっていただいて、そうしたことも検討していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問・要望","question":"かつ、その方々については、できるだけ早くこの制度が実現できるように頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"横山委員","kind":"意見","question":"結論を出すで、採択でお願いします。早急かつ慎重な対応をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]},{"id":"topic-05","title":"令和２年請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年陳情第４１号、品川区立学校図書館設備充実に関する陳情","agenda":"令和２年請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年陳情第４１号、品川区立学校図書館設備充実に関する陳情","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"実は私、今回の陳情が出るまで学校図書館でインターネットが通じないなどと考えもしなかったものですから、ちょっとびっくりいたしました。品川区としては、今なぜつながっていない状態にあえてしているのか、今後の考え方について説明を求めました。","respondent":"横山品川図書館長、篠田学務課長","answer":"現状としては、説明申し上げましたように、わざわざ庁内のシステムの中に入っていたものを外出しにして危険性を分散するような形をとっています。生徒が１人１台機器を持つので、ご自分で学校内の授業の中で学んでいただき… 品川図書館長から説明があったとおりですけれども、現状は、もう既に無線ＬＡＮの構築は全ての学校で完了しています。","id":"exchange-042"},{"speaker":"あべ委員","kind":"質問・要望","question":"お伝えしたりということも、せっかく来ていただいているわけですから、したほうがいいに決まっているわけです。学校の学びにとって私は有利だと思いますけれども、あえて使わないのはむしろもったいなくないか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"現在、学務課長からも説明があったとおり、各学校に４０台のタブレットパソコンが置いてありますので、今、それを活用して学習しています。学校長と相談して、１台、２台を借りて検索するということはできるかと思います。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうした方向で、ぜひ考えていただきたいなと。それをすることのデメリットは特にないと思うのですが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"各校、校長を中心に調整していただいて、各校の現状に合わせた活用の仕方をしていっていただければと考えています。それが全体に及んだ際に、改めて学校図書館の配備も考えられると思います。","id":"exchange-044"},{"speaker":"たけうち委員","kind":"意見","question":"下から２段目の上から２行目の辺り、その辺の状況は、実態としてはどのような感じで教育委員会は捉えていますかとの意見を述べました。","respondent":"横山品川図書館長","answer":"まさにＧＩＧＡスクールで生徒が１人１台持っているという形になれば、そちらをサポートする形で調べ学習を進められるので、場所を問わず学ぶことができる環境がこれから整備されるものと考えております。","id":"exchange-045"},{"speaker":"たけうち委員","kind":"質問","question":"ＧＩＧＡスクール構想でいいますと、子どもたちには１台、それを重々活用しながらと。先ほどあったとおり、図書館スタッフの方も使えるようなものが既にあると、こういうことでよろしいのか尋ねました。","respondent":"篠田学務課長","answer":"現状は、今、委員ご指摘のとおり、要は、機械自体はいろいろな形で工夫をすれば学校の中にもあるということですので、そこはＧＩＧＡスクールの導入に合わせて、その使い道についてもいろいろと検討して工夫をしながらやっていけるのかというふうに思っているところです。","id":"exchange-046"},{"speaker":"筒井委員","kind":"確認","question":"予算の制約上、もともと司書が登校される日数が少ないということなどもあります。これも急ですから見えない中、その将来的な検討ということはお考えなのか確認したいのですが、その点はいかがか尋ねました。","respondent":"篠田学務課長","answer":"では、全ての方に機械を全部渡すのかということになると、なかなかそこまでは難しいのかなという思いは正直あります。ただ、最低限必要な部分にはきちんと手当てをしていくということで、私どもも取り組んでいるということで考えているところです。","id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"国はその点をどうお考えなのか、４０台の使えるＰＣがあるということなので、将来的なご検討をお願いしたいと考えております。やはりタブレット端末は１人１台持つように、将来的な検討の余地ということをお伺いしたいのですけれども、いかがか尋ねました。","respondent":"篠田学務課長","answer":"文部科学省の基本的な考え方としては、１人１台、区としてその辺は配慮するといったところです。これから先、また新たな動きがあれば、それはそのときにまた改めて考えていくというようなこともあり得るのかなというふうに考えているところです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"四角の部分です。学校図書館と情報活用能力の関係ですとか、どのような位置付けになっているのか、改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"学習指導要領、教育要領にもありますように、統計資料、新聞、その他様々な教材・教具を活用することが重要であると。インターネットの情報は、そういったものも含めた情報活用能力、広く育成が必要であるということは教育要領でも示しているところではあります。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"貸出システムに直接つなぐというのは、そうではなくて、それとは別に図書館にインターネット検索もできるような端末が必要だということだと思います。もう少し聞かせていただきたいのと、ＧＩＧＡスクールの１人１台ということなのですけれども、そこら辺も説明するよう求めました。","respondent":"篠田学務課長","answer":"ただ、そのタブレットも全て無線ＬＡＮに対応している形ですので、校内であればどこでも今はつながるというような環境にあるです。例えばプログラム教育などでもＷｉｎｄｏｗｓではないと動かないとかがあったときの対応ということも含めて、今、考えているところですので。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"これからの時代、しかもこれから求められるような教育を行っていくためには、専用で使えるような端末整備は絶対なくてはいけないことだと思います。必要であれば、財政措置も講じて整備するということは必要だと思いますけれども、いかがか尋ねました。","respondent":"篠田学務課長","answer":"機械もこういった状況の中で、いろいろな形で今入ってきているものですから、必ずしも全然足りないわけではないという現状があります。先ほど申し上げたとおり、それぞれ学校の事情もありますから、考えながら進めていけるのかと考えているところです。","id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"最後に意見ですけれども、学校教育、教育の環境整備というのは、やっぱり区の役割といいますか、教育行政の大事な役割だと思いますので、ぜひしっかりと整備していただくようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"まず合っているのかどうか教えていただきたいのと、あと、児童の端末に対しては補助金が一定程度あったと思うのです。教員または、当然今議論になっている図書館の端末も対象外だと理解をしているのですけれども、その認識でいいのか、２点、説明を求めました。","respondent":"篠田学務課長","answer":"例えば契約にしても、今回、必要な台数の３分の２だけを補助しますという仕組みになっています。３分の１までは今まで様々な形でやってきているから、当然設置がされているだろうという前提になっているというようなことがあります。","id":"exchange-053"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"もう１点確認で、パスワード等を教えてもらってという話ではなくて、複雑な設定があるということなのですか。当日、インターネット接続をさせていただきたいというようなお話があっても、なかなか使うことはできないのか尋ねました。","respondent":"篠田学務課長","answer":"インターネットの設定ですが、実はセキュリティをきちんとかけているところがあります。１台１台、事前に私どもの学務課に校務情報管理対策担当がおりますので、そこと調整していただく形が必要になってくると思います。","id":"exchange-054"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。まずは持っている端末を使っていただいて、まずは今の時点では使えるものを使っていただきたいという意味での不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"せお委員","kind":"意見","question":"不採択でお願いします。１人１台、そこのところが整理できてから検討していただくのもよろしいかと思いますので、本日は不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今、お二人からもありましたけれども、ＧＩＧＡスクール構想の中で１人１台のタブレットがこれから今年度中に配付される。どういうことをやっていけるのか等、その上で果たして専用のものが必要かどうかも含めて検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"安藤委員","kind":"意見","question":"採択なのですけれども、あと、それが今後の学習環境整備において大変大事なのだというようなことをおっしゃっていると思います。ですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"図書館スタッフのお話を伺って、将来はしっかりと図書館スタッフにも１人１台端末が行き渡るような検討をしていってほしいと求めました。これは要望といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいと思います。繰り返しますが、現状の持っているもので十分進めていくことは可能だと思いますので、できる学校から進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"横山委員","kind":"質問・要望","question":"現在の優先順位としては、まずは新たに児童・生徒に１人１台配備されるタブレット端末の活用が先決と考えています。どういった使い方、まずは子どもたちが活用できるということが今一番求められていることだと思いますので、そのような形でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-06","title":"令和２年陳情第４５号、２０人学級で学べるよう教職員の数と予算を増やし教育環境整備を求める陳情","agenda":"令和２年陳情第４５号、２０人学級で学べるよう教職員の数と予算を増やし教育環境整備を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"子どもや教員からどういう声が挙がっていたのか、どのような声を聞いたのかということと、その受け止めです。聞いた声のご紹介などがあれば伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"３密を避けるというところから、静かなスタートでございました。ただ、みんなと会えてうれしいということと、ずっと進んでいなかった学習が進んだことについては安心感を持っているということを聞いております。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"一般質問で私も同様のことを求めて質問しましたが、改めてどういう意味だったのか伺いたいのですが、しなかったのでしょうか。伺いたいと思います。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"１点目につきましては、子どもたちと非常に似ていることだと思います。同じように学習の状況についても、自分の心配があったところが少しほっとしたというところが、ほぼ同じご意見でございました。 ２０人学級にした場合の増える教室、教員の数という形の試算の関係です。そうしたところ、やはり５００以上の学級数が増えるのは間違いないというところは出ています。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"一般質問のあれですけれども、再々質問で伺ったところ、加配を要望しているというようなご答弁があったと思うのです。これは具体的に何を国や東京都に要望しているのかということを伺いたいと思います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"２回指導を繰り返すということにもなりますし、ちょっとしょぼんとしている子どもがいることは間違いない、そういうこともあります。運動会の練習等をしていますが、本当ににぎやかで活気のある姿も見られますので… 教育総合支援センター長からもありましたように、私どもも重要に考えておりますので、また指導者の目できめ細かく対応できるようにしています。教員の加配につきましても、東京都に対しては要望しているというところがあります。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"小学校２年生ぐらいから算数の習熟度別学習をやっていまして、結局、あれはあれですごく問題が指摘されているところがあります。それは違うと思うのですが、そこは認めますか尋ねました。","respondent":"工藤指導課長","answer":"ＴＴの形で行いますので、また、その場面は適切に行うことが重要であると考えています。","id":"exchange-065"},{"speaker":"安藤委員","kind":"提案","question":"私ももちろん提案しましたけれども、何よりも子どもの現状がそういうことを求めているというふうな状況だと思いますので、詳しくは繰り返しません。少人数学級導入をすべきだという立場なのですけれども、ちょっと難しい質問ですが、ご答弁をお願いしますとの意見を述べました。","respondent":"篠田学務課長","answer":"４０人学級というのは、４１人になった瞬間に２クラスに分けるということをせざるを得ない、しなければいけないというものです。１０人のクラスと１１人のクラスをつくらなければいけないということになりますから、学級編制を考える上で、ご理解をいただきたいと思います。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"実は２１人と２０人なのだなどということを踏まえて言っているかというのは、例えば２０人ぐらいの規模にしてほしい、そういうふうに思いました。本当に求められている内容だと思いますので、ぜひこれは区の意思として、議会の意思としても採択していきたいという思いがあります。","respondent":"齋藤教育次長","answer":"アバウト２０人ということはありません。２０人での学級編制は難しい以上は、４０人を２人の大人の教員の目で見る、２０人の児童・生徒ありきという前提での議論とは我々は当然違います。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"ここを変えていくことに挑戦すべきだと思うし、思い等に共鳴して進めていく先頭に立っていただきたいというふうに私は思っております。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問・要望","question":"でも、やっぱり国に対しては、現場の声として学級編制をもう少し緩やかにしてほしいというような声は、ぜひ上げてほしいと思うのです。そういったことは区としてはされていますか尋ねました。","respondent":"篠田学務課長","answer":"区におきましては、これは特別区の教育長会などの様々な機会で、少人数の学習を保障するような形で様々言わせていただいて要望しています。","id":"exchange-069"},{"speaker":"あべ委員","kind":"質問・要望","question":"区として現場の声として考えていただきたいし、その方向はぜひ言い続けてほしいと思うのですけれども、どうでしょうか。いかがでしょうか、教育委員会のお考えとしては。","respondent":"齋藤教育次長","answer":"本会議でご答弁したとおり、国、都の基準が基本ですので、まずはこれに従った教育活動を実施してまいります。","id":"exchange-070"},{"speaker":"筒井委員","kind":"質問","question":"２０人学級、何回かお話が出たかもしれないですが、改めて大人数学級のメリットはあるのか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"全体の迫力、見ている方たちもいますので、そういったところかと思います。全体でやることで士気が上がったり、時にはライバル意識を高めて力が入ったりという相乗効果もあるかと考えております。","id":"exchange-071"},{"speaker":"筒井委員","kind":"質問","question":"品川区が２０人学級を実現したとしましたら、教員数がどのくらい増やさなければいけないのかということは、大体お分かりになっているのか尋ねました。","respondent":"篠田学務課長","answer":"２０人学級にするというのは、現状の４０人学級の半分を受け入れるだけの設備が必要ということになりますから、倍必要だという形でお話をしています。","id":"exchange-072"},{"speaker":"筒井委員","kind":"質問","question":"知事会などの３会長などの文部科学大臣との面談で、ちょっと難しいかと私も思っているのですが、そうした状況の変化とかに応じたら２０人学級にする可能性はあるのか尋ねました。","respondent":"篠田学務課長、工藤指導課長","answer":"必ずしも知事会等の考え方が東京都のような状況を踏まえた形でされているかというと、必ずしもそうではないのではないかというふうに考えております。それ以外は４０人という形で規定がされていますから… ２年生での３５人学級、７年生での３５人学級が実現しておりますが、それが実現しているところもなかなか少ない。","id":"exchange-073"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。区においては４０人学級、国と都の基準に従って教育現場をつくっていただきたいというのと、こちらも引き続き適切に臨んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"２０人学級のメリットは理解できます。ですが、先ほどから答弁がありますように、課題は多過ぎて現実的ではないと思いますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、やはりそういった現状が学級規模のさらなる縮小を強く求めておりますので、柔軟で手厚い教育を実現させていく必要があると思います。採択を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、不採択といたします。将来的に方向性としては少人数学級の方向に行く可能性はあるでしょうけれども、具体的に２０人という数字は現実的に言って困難だということからですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"あべ委員","kind":"意見","question":"私ももう少し編制が少ないほうがよりよい部分が多いだろう、メリットが大きいだろうというふうに考えております。具体的に踏み出す状況にはないということで、申し訳ないですけれども、これは不採択ということで考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。内容と、少人数指導や習熟度別学習や、またチームティーチングなどを適切に実施していただきたいというふうに考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"}]},{"id":"topic-07","title":"令和２年陳情第４８－２号、子どもが健やかに育つための陳情（陳情項目１、２）","agenda":"令和２年陳情第４８－２号、子どもが健やかに育つための陳情（陳情項目１、２）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ質疑の前に陳情者のご意見は聞きたいと、その上で、そういったことも含めて質疑に活かせると思いますので、そのようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"あべ委員","kind":"意見","question":"それを聞いた上で審議してほしいということだと思いますので、数字は持っていないのですけれども、そのように感じております。品川区議会でも意見陳述の機会がより有効に働くようにご配慮いただけるとうれしいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"たけうち委員","kind":"質問","question":"事前にお聞きするものと、非常に分かりやすい内容になっているかと思いますので、質疑を終わった後で必要かどうか諮ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"あべ委員","kind":"質問","question":"陳情１のほうですけれども、何かを１回渡したからこれで十分ということではなくて、いかがでしょうか。チャイルドラインを含む子どもたちが相談できる機関の電話番号をお伝えするということはできるのではないかと思いますけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長、黛生活安全担当課長","answer":"相談窓口の周知につきましては、委員おっしゃったとおり、相談窓口については約１０か所程度、１枚にまとまった東京都からの案内があります。その中で、このカードも配布するということで、組み合わせて利用をさせていただいています。 まだいろいろと検討しなければいけないところはあるとは思うのですけれども、検討の余地は十分あるのではないかというふうに考えておりますので、調査研究をしてまいりたいと思います。","id":"exchange-083"},{"speaker":"たけうち委員","kind":"提案","question":"９年生までということで、１８歳までとなっていますけれども、ちゃんと届いているということは確認をされているのかどうか。あべ委員からもいい提案があったと思うのですが、その検討の中の選択の１つとして、ぜひ検討してほしいと求めました。","respondent":"矢部教育総合支援センター長、黛生活安全担当課長","answer":"２点目の都から区に、様々なカードとチラシ等が参りますので、その管理はそれぞれであるかと思います。少しご心配の旨かと思いますが、学校は… チラシを入れるなりして周知を図っていくかというのは、また教育委員会とも連携をしながら、引き続き検討をしてまいりたいと思います。先生方… ３点目につきまして、確認できているところをお伝えします。","id":"exchange-084"},{"speaker":"たけうち委員","kind":"質問・要望","question":"物理的に今すぐにできないこととできることがあると思いますので、その辺はぜひ働きかけてほしいと求めましたので、よろしくお願いします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"横山委員","kind":"確認","question":"万が一、例えば小学校１年生は公衆電話の使い方ですとか、フリーダイヤルのかけ方を知っているのかということが確認できたらと思いました。使ったことがない子どもは合わせて８４.３％いるというようなデータがありまして、ちょっとこの辺りを確認、もし分かれば説明を求めました。","respondent":"有馬庶務課長","answer":"そのオプションに加入すれば１０件ほど登録ができて、その案内の中には、子どもはその範囲で活用はしていると思います。基本的には家庭でというところになるかと考えています。","id":"exchange-086"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、まもるっちに、今、登録として、ＨＥＡＲＴＳはもともと入っている。ＨＥＡＲＴＳが入っている理由は、やはり教育総合支援センターという区の公的機関だからという理由でよろしいか尋ねました。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおりです。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"傾向として、保護者の方は大体どのような番号を登録されているのでしょうか。分かる範囲で。","respondent":"黛生活安全担当課長","answer":"大変申し訳ございません。契約に関するところにつきましては、当担当で認知はございません。","id":"exchange-088"},{"speaker":"安藤委員","kind":"提案","question":"ですから、やはり区も支援を強めてほしいと求めました。ＮＰＯでやっているわけですから、そういう支援は必要だと思うのですけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"委員お話のように、大変ありがたい取組みだと思って感謝しているところですが、本区では、重複しますが、市民科の５年生から７年生でカード自体も取り上げて指導しておりますので、支援を強めるという委員のお言葉に当たるかというふうに考えております。","id":"exchange-089"},{"speaker":"安藤委員","kind":"意見","question":"ぜひこうした区民の方の思いを議会として拝聴する場は貴重ですし、この陳情審査においても非常に有益だと思いますので、意見陳述をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"あべ委員","kind":"質問","question":"私も意見陳述を伺いたいと思います。ぜひ今、聞きたくてうずうずしているのですけれども、ぜひ意見陳述をお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"筒井委員","kind":"意見","question":"私も陳情者の方の直接的なお考えを聞いてみて判断していきたいと考えておりますので、意見陳述に賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"理解できた方にぜひ教えていただきたいのですが、では、なぜこの陳情が出てきたということなのでしょうか。そこは理解できた方は、しっかりとご理解ができたからもういいとおっしゃっているわけか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今、あべ委員の質問が、仮に答えが分からなくても、ここに出てきている要望は分かりますので、特にそれを分かる必要はないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"２に関してはオプション等の都合で難しいということですので、１に関しても、さらに周知をしてほしいということだと思います。２番に関しても、それは区としても様々模索をしていただきたいという思いで趣旨採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"せお委員","kind":"質問・要望","question":"定期的に、１回昔に届けたということではなくて、定期的にやっていくことは大切かと思います。項目２のフリーダイヤルのほうも、新しいまもるっちのほうでも検討していただきたいという思いもありまして、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いします。今回新しくまもるっちを変えていく中での検討の１つに加えていただくというお話もいただきましたので、この２つ、趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"安藤委員","kind":"意見","question":"それと、まもるっちへの登録は、本当にこれはナイスアイデアといいますか、子どもの現状にとっても大事なことだと思いました。採択をして、議会としてもそういった検討を後押ししていくほうがいいかと思いますので、そういった趣旨で採択を主張いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いします。課題はありますけれども、やはり１つの有力な選択肢として区としては提示をしていっていただきたいという思いから、趣旨採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"あべ委員","kind":"質問・要望","question":"では、それまでの２年間の子どもたちはかけられないのかということで、電話に日常的にアクセスできないお子さんもいらっしゃるでしょうから。いずれにせよ、より緊密にこうした地域の活動と連携をして行政を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"横山委員","kind":"意見","question":"相談先は１つではなく複数あって、その中から本人がより話しやすい相手や相談先を選択してアクセスできる環境は必要だというふうに考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"安藤委員","kind":"意見","question":"一応会派で相談して態度を決めていますので、採択すべき内容だと思っているのですが、やっぱり全会一致で趣旨採択ということで結論を出していくというのは大きな力になりますので、趣旨採択に変えしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"}]},{"id":"topic-08","title":"令和２年請願第１１号、大学生に返還免除規定を持つ奨学金制度の創設を求める請願","agenda":"令和２年請願第１１号、大学生に返還免除規定を持つ奨学金制度の創設を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"様々な制度がある中で、それが受けられたり、現状でもそれは十分ではないということをここで書いているわけではないですか。なぜ区がこうした区民の学生に対して支援をしないのか、給付型の奨学金を行わないのか、もう一度お聞かせほしいと求めました。","respondent":"三ッ橋子育て応援課長","answer":"区が高校生の返還免除制度を新設いたしておりますので、今現在のところ、大学までの奨学金を創設する考えはございません。様々な事業者が奨学金制度を設けておりますので、区といたしましては、大学までの奨学金制度を創設する考えはございません。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、区はやらないと言うのですけれども、東京の中で２３区ほかでも自治体で、こうした施策は実はいっぱいやられています。どのように把握しているのか伺いたいというのが２点です。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、大学生まで拡大する新創設はございません。他区の状況ですけれども、港区や大田区などが実施しているものと捉えております。","id":"exchange-104"},{"speaker":"安藤委員","kind":"提案","question":"もう一度伺いますけれども、なぜ品川区ではやらないの。なぜできないのか伺いたいと思いますとの意見を述べました。","respondent":"三ッ橋子育て応援課長","answer":"品川区では、高校生までの返還免除制度を新設して、今、対応しています。こちらの検証なども含めて、今現在のところ、大学生までの奨学金を創設する考えはございません。","id":"exchange-105"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区としては、こういう区内の大学生に対して手を差し伸べないのでしょうか。伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"令和２年４月から文科省が法律関係を含めて様々な制度を対応しています。区といたしましては、区民を守るという立場は変わりませんが、今後も国や都の動向を注視してまいります。","id":"exchange-106"},{"speaker":"安藤委員","kind":"質問","question":"ですから、私が伺ったのは、こうした目の前で実際に困っている方、何とかしてほしいという方に対して、区は手を差し伸べないのでしょうか。伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"国で授業料減免や奨学金拡大を行う法律が制定されましたので、東京都や大学をはじめ様々な事業者が奨学金制度を設けております。したがいまして、区といたしましては、大学生までの奨学金を創設する考えはございません。","id":"exchange-107"},{"speaker":"あべ委員","kind":"質問","question":"その根拠としては、学生の約２割が対象になるようにということで設定されたと聞いております。品川区では、品川区の大学生２割を対象としようとすると、一体幾らの世帯年収になってくるのかというのは、どのように試算をされているか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"品川区の大学生２割の世帯年収ですけれども、区といたしましては把握ができません。","id":"exchange-108"},{"speaker":"あべ委員","kind":"提案","question":"港区の例が出ましたので１つ申し上げますと、港区の場合は、給付型の奨学金と、貸与型奨学金の返還免除制度と同時に条例が提案されています。ちょっとニュアンスが違う２つのご答弁があったと思うのですが、それとも単に検討していないだけなのか、どちらか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、港区の状況や、もちろん大田区の状況なども鑑みながら、今後のことを見据えなければいけないと考えています。東京都や大学をはじめ、様々な事業者で奨学金制度が創設されている状況を鑑みて、今後の国や都の状況を注視してまいります。","id":"exchange-109"},{"speaker":"あべ委員","kind":"質問","question":"では、品川区の学生にとってはどのくらいカバーできるものなのかというのは、まさに今の数字で分かるものなのです。数字が出そろった今、検証を始められたらいいのではないかなというふうに思いますが、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"検証につきましては、しかるべきときに検証してまいります。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"しかるべき条件が出そろっているから、それは今ではないですかという話をしておりますが。一律の数字で設計をすると、ぜひそこを勘案した上で奨学金制度をもう一度正面から考えていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"考えなくてはいけないところがあるというところで、進行形で動いているところですので、まだ厳しい部分があるというのは正直なところです。国のほうの動きも出ているというところを考えたときには、今、その辺はきちんと研究しなくてはいけないテーマだろうというふうに思います。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問・要望","question":"しかし、少なくともかなり性格の違う高校生の制度を見た上で大学生について考えるというのは、私はちょっと順番としてはどうかなと。そうした面では、ぜひ前向きな検討を、しかも高校の条件とは違った視点でぜひ検討していただきたいと、これは最後に要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"安藤委員","kind":"質問","question":"今回、そういったこともあって、他区などでもいろいろと動きもあると思うのです。専門学生などについて、あるいは退学せざるを得ないですとか、そういう学生の今の困窮実態はつかんでいらっしゃるのか伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"特に今の段階では、学生の困窮状態については把握しておりません。","id":"exchange-113"},{"speaker":"安藤委員","kind":"質問・要望","question":"この方もアルバイトをやりながらという話も聞きましたけれども、本当に大変な思いで自ら出しているわけなのですが、まずこれが現実としてある。しかも、実態を区としてもつかんでいただくよう求めますし、そのようなことについての現時点での区の考えも伺って終わりにしたいと思います。","respondent":"柏原子ども未来部長","answer":"いろいろなことを考えながら、委員おっしゃるようなところで、全く何もしていないということではないというところはご理解いただきたい。ただ、全部が全部できるということではありませんので、その中で判断させていただいているです。","id":"exchange-114"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"個人的には区が模索してもいいのではないかとも思っていますけれども、この二、三年で非常に制度が変わってきています。より多くの学生を救っていただきたいというふうに思っていますので、まずはやはり国の動向を引き続き見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"せお委員","kind":"質問・要望","question":"コロナ禍ですので、やっぱり区も限られた財政というところで、やはり優先順位は必要だと考えています。ただ、そういったところはやっていただきたいという要望はありますが、こちらに関しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"意見","question":"私も親の立場でつい最近まで２人同時に大学に通わせて、非常に大変だ、なぜこのように高いのだろうと思っています。それは今すぐ品川区がまずというところではないと私は思っているので、そこをしっかりと見据えていくということで、不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-117"},{"speaker":"安藤委員","kind":"質問・要望","question":"根本的には、お金のあるなしで未来がある若者が学べないというような社会でいいのかというのが、どのステージでも問われていると思います。区としてできることを早急にやっていただきたいというふうに思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"筒井委員","kind":"質問・要望","question":"コロナで苦しんでいるのは大学生だけではないのですけれども、やはり今、大学生は日本経済を将来的に支える１つの重要な存在だと思います。ぜひこうした給付金、奨学金制度の創設に前向きな検討をしていただきたいという理由で、採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほども伺っていますと、そうすると、つなぎとしての効果も発揮できるだろうというふうに考えます。あるいは学業が続けられない状況というのは、これまでの投資がむだになってしまいますので、そこをぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"横山委員","kind":"質問・要望","question":"は区の新制度について、成果、課題などの検証や分析を実施していただきたいというふうに考えています。今後の高等教育の修学支援の状況については、引き続き、国の新制度ですとか、国の動向などを注視してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"}]},{"id":"topic-09","title":"令和２年陳情第４７号、離婚等のこども養育支援にかかる陳情","agenda":"令和２年陳情第４７号、離婚等のこども養育支援にかかる陳情","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"では、その件数のうち、何％が解決したのでしょうか。それは答えられますか。","respondent":"三ッ橋子育て応援課長","answer":"相談につきましては、きちんと対応して、面会交流や養育費の問題など、様々、公益社団法人に紹介しておりますので、基本的には１００％と考えております。","id":"exchange-122"},{"speaker":"あべ委員","kind":"質問","question":"１００％解決が図られているというご答弁でよろしいのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"解決と申しますのは、それぞれの方の答えというものも非常に難しい問題があります。しかしながら、面会交流についてご紹介をして、１００％を目指しているという考え方です。","id":"exchange-123"},{"speaker":"あべ委員","kind":"質問","question":"その後どうなっているのか、ちゃんと満足いける状態なのか、それとも課題があるのかということを区として把握されているのでしょうか。それなしに、さっきおっしゃっていた子どもたちの最善の利益というのは普通にできないのではないかと思いますけれども、いかがか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"その中で、また改めてご相談に来る方も中にはありますけれども、この面会交流に関しましては、簡単に解決できる問題ではないと考えています。ご紹介をして、そこの次の段階で何らかの対応をしているということはできますので、その意味で図られていると申し上げました。","id":"exchange-124"},{"speaker":"あべ委員","kind":"質問","question":"課長がおっしゃられる問題解決が図られているというのは、相談を受けて次の機関に紹介したら、それでもう一件落着という意味なのでしょうか。は区民の方々が本当に困っているのか、次にもう１回相談が来ないと、紹介した後のことは追えていないということでよろしいのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"「図られている」という言葉の捉え方については、実際には品川区としては紹介をしている、そしてもちろん相談は受け付けているという状況です。","id":"exchange-125"},{"speaker":"あべ委員","kind":"質問","question":"でも、区としては、もう全て問題解決しているという認識なのですか。もう１回聞きます。","respondent":"三ッ橋子育て応援課長","answer":"しかしながら、１件１件の案件が、そのご夫婦間のこととか、あと、お子さんの問題とか、非常に難しい部分はあります。もちろん区としても面会交流の支援はしていきたいと考えておりますけれども、本当に難しい問題で、国や都の動向を注視しています。","id":"exchange-126"},{"speaker":"あべ委員","kind":"質問","question":"１００％は目指しているけれども、解決は１００％ではないというところまでは区として認識はされているということ、これはいいですか。つまり、品川区としてはこの問題には直接的には関わらないということでいいのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"何にしろ、子どものことをきちんと大事に考えていかなければならないと考えています。１点補足ですけれども、支援につなげていく、ご相談に応じて対応はしております。","id":"exchange-127"},{"speaker":"あべ委員","kind":"質問・要望","question":"では、区としては、今の段階で何ができるかという発想をぜひしていただきたいわけです。ぜひこの問題を区としてできることを考えていただきたいと思うのですけれども、その姿勢自体はあるのですか、ないのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"先ほど申し上げましたように、実際に法律等も動いていく可能性が高いと考えています。その中で区として何ができるのか、それは考えていかなければいけない問題だと考えています。","id":"exchange-128"},{"speaker":"あべ委員","kind":"質問","question":"考えていかなければいけないというのは、今はまだ考えていないけれども、これから考えるということですか。今は何を考えていますか。","respondent":"三ッ橋子育て応援課長","answer":"先ほど答弁いたしましたように、区といたしましては、引き続き、国や都の動向は注視していきます。区として何ができるのか、できないのか、どの部分に対応していくのかなどを含めて考えていくことが大事だと考えています。","id":"exchange-129"},{"speaker":"あべ委員","kind":"質問","question":"部長、今のご答弁でいいのですか。多分区としても認識されていると思いますが、品川区としては、今は何もしないという状況なのか尋ねました。","respondent":"柏原子ども未来部長","answer":"問題意識、現場のレベルのところではあるというところで認識も持っていますし、いろいろなケースがある意味で難しいということを申し上げております。","id":"exchange-130"},{"speaker":"筒井委員","kind":"質問","question":"結局、こうしたご相談を受け付ける相談窓口、所管はまず品川区でどこになるのか。今までのそうした件数や、それが多いのか少ないのか、区としてはどのような実感を得ているのかをお聞きしたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"離婚の相談などを、また様々な相談はしていますので、このような相談についてはそちらが窓口になります。件数については控えさせていただきたいと思いますが、全て、もちろん状況に応じて面会交流などもご紹介しております。","id":"exchange-131"},{"speaker":"筒井委員","kind":"質問","question":"実際、この事業をやるかやらないかに当たっては、需要があるのかというのは把握しておかなければいけないと思っているのですけれども、それほど頻度的に多いものなのかということを、具体的な件数というよりは、相談は本当に多いのかというか、感触というか、その辺りはどうなのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"様々な相談がありますので、特に面会交流をしたいとか、今回の陳情に関係するような相談については、多い少ないというのもなかなか難しい答えになるのですけれども、もちろん面会交流をしたいというご相談はあります。","id":"exchange-132"},{"speaker":"筒井委員","kind":"質問","question":"品川区のホームページで、それはちょっと案内とか周知が足りないのかと思っているのですが、そうしたことの改善もぜひお願いしたいと思うのです。そうした周知とか広報の改善をしてほしいのですけれども、その点、いかがお考えか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"様々な状況を勘案しながら、ご相談したい方が探せないというのは、さすがによくないとは思います。ただし、この案件は非常に慎重に進めなければ、その部分に関しては慎重に検討させていただきたいと考えています。","id":"exchange-133"},{"speaker":"たけうち委員","kind":"質問","question":"事務事業概要の５６ページに、養育の相談で何件、何件と件数が出ているではないですか。ここはそういう視点でお答えしてもらわないと、我々もせっかくこれを審査しているのだからと思うのだけれども、どうか尋ねました。","respondent":"柏原子ども未来部長","answer":"お話しできる内容については、きちんと審議といいますか、議論ができる内容での答弁をさせていただきたいと思います。申し訳ございませんでした。","id":"exchange-134"},{"speaker":"安藤委員","kind":"質問","question":"子どもが両親、ここについて品川区としては、どう認識されているのか伺いたいというふうに思います。２点伺います。","respondent":"三ッ橋子育て応援課長","answer":"面会交流につきましては、先ほど申し上げましたように、子どもたちにとって最善の方法をとるのが一番いいと思っているところです。明石市や港区に対しては、やはり先進的な事例だと捉えておりますので、それらはいろいろと勉強させていただきたいと考えています。","id":"exchange-135"},{"speaker":"せお委員","kind":"質問","question":"１点だけお伺いしたいのですが、養育費の立替保証を実施する区市町村を支援する」とあるのですけれども、こちらの事業については何か検討されていることはありますか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"今年度から東京都が始めた事業と捉えておりまして、区といたしましても、様々検討、勉強してまいりたいと考えています。","id":"exchange-136"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、２３区では、実際に面会交流支援をやられているのは、港区だけという理解でよろしいか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"私はそう捉えております。","id":"exchange-137"},{"speaker":"芹澤副委員長","kind":"意見","question":"会派からも養育費等を行政のほうに働きかけてきましたけれども、国と都の動きが今非常に活発になってきていると。今話し合ったように、区の関わりも前提になってきているのかと思いますので、引き続きこちらは議論していければと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-138"},{"speaker":"せお委員","kind":"質問・要望","question":"先ほど質問いたしました都の事業に関しても、こちらも動きがあるということで、そちらを注視していくべきだと私も思います。品川区としても、これから検討していってほしいと求めましたので、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"安藤委員","kind":"質問・要望","question":"家族の在り方という点からもそうですし、あと、子どもの権利が何よりも大切にされている社会ではないかと思います。ぜひ品川区でも先進事例だという話もありましたけれども、検討・研究を進めて実施できるところから実施していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"筒井委員","kind":"質問・要望","question":"それとも東京都という広域である程度やっていくべきものなのかということは、しっかりと今後も深めていかなくてはいけないのかと考えています。ただ、案内とか周知の点、現行の東京都の制度がありますので、そこはしっかりとご相談者にお伝えをしていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"あべ委員","kind":"質問・要望","question":"今のお話を伺っていると、それから、これまでの品川区での議論も頭に入れてほしいと求めました。よりよい親子関係のために、品川区としてぜひ全力を尽くしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"横山委員","kind":"質問・要望","question":"確認もしてきたのですけれども、相談者と一緒に考えて、よりよい解決に向けた情報提供を必要な方にお願いしたいと思います。区の家庭相談員に対して、区としてできることを引き続き実施していただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5012#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":94510,"voices":377}},{"id":"r02-20200923-5","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"総務委員会","time":"午前１０時００分～午後 ０時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"第６２号議案 第二戸越幹線整備工事（北品川立坑）請負契約の変更","agenda":"第６２号議案 第二戸越幹線整備工事（北品川立坑）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"資料の２ページ目の変更理由ですけれども、その他のところで、新型コロナウイルス感染拡大防止に向けたとあります。いずれにしても、工事の一時中止によるというのは、どのような事情なのか、そこだけご説明ほしいと求めました。","respondent":"松本河川下水道課長","answer":"その他の新型コロナウイルス感染拡大防止に伴う一時中止ですが、これは、請負者から感染予防ということで、緊急事態宣言の間、４月２７日から５月８日にかけて、平日の６日間、中止したものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"提案","question":"関連して、今回、金額が大きいので議案として提案されたのだと思います。金額の大小で議案になるかどうかは別にして、ほかの公共工事もこのような対応というか、追加の費用を支出しているという認識でよろしいのか尋ねました。","respondent":"東野経理課長","answer":"新型コロナウイルス感染症に対する工事請負契約の変更なのですけれども、現在、感染症対策のみで金額の変更をしている案件はございません。工事の一時中止等に伴いまして、工期の延長等の契約変更の措置は何件かしています。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"新聞でもそういった記事を読んだことがないのですが、なぜこのようなことがあるのですか。新型コロナウイルス感染症の拡大防止ということで国が動いたわけですから、見積書に出すならば、国にこれを請求するというのが筋ではないのか尋ねました。","respondent":"松本河川下水道課長","answer":"今回の新型コロナウイルス感染拡大防止に向けた工事の一時中止に関わる現場維持費につきましては、約４０万円を計上しています。下水道局の変更ガイドラインに計算方法があり、それに則って計算し、４０万円を算出しています。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"額は少ないですが、私は日本全国にわたって、建設業者および現場の業者にこのようなことをきちんとアピールしていくべきではないかと思います。意見だけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"約８億円の契約について、約２億円の増額ということですので、つまりは(1)から(4)が大きいということです。費用がどれにどれくらい、また一番多くかかるのはどれだったのかということを説明するよう求めました。","respondent":"松本河川下水道課長","answer":"(3)の仮設工が、約６,７００万円の変更です。(4)の共通仮設費が、約１,７００万円の変更です。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"すみません。一遍に聞けばよかったのですけれども、これらの変更が必要になった理由も、簡単で結構ですので、教えていただけますか。","respondent":"松本河川下水道課長","answer":"泥土を処分するに当たり、再資源化施設の受入基準に基づき試験を実施した結果、その基準値のものを処分できる再資源化施設を追加したものです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"つまり、土砂と泥土では、処分の金額が変わってくるという理解でよろしいでしょうかというのが１点です。最初のところと、あとは要望ですけれども、もし何か一言あれば、伺いたいと思います。","respondent":"松本河川下水道課長","answer":"今、委員のご質問のとおり、土砂と泥土の処分先によって金額が変わるものです。理由の掲載につきましては、今後、検討していきたいと考えています。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"意見","question":"具体的に、どのような計測管理をやるのか、施工するのかどうか。その１点だけお願いいたしますとの意見を述べました。","respondent":"松本河川下水道課長","answer":"ＪＲにつきましては、高架にターゲットという測量のポイントを設置いたしまして、その変位を見てあります。首都高につきましては、傾斜計というものを設置しまして、地盤が変位するか、しないかということを測ってあります。","id":"exchange-008"}]},{"id":"topic-02","title":"令和２年請願第９号 固定資産税及び都市計画税の軽減措置の継続","agenda":"令和２年請願第９号 固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ伺いたいのですけれども、品川区としては、この３項目について、東京都にどのように要望しているのか。そのスタンスだけご説明ほしいと求めました。","respondent":"伊東税務課長","answer":"区のほうにも、軽減措置ということで、要望等が上がっているところです。我々も区民の暮らしのためにそのような軽減措置を継続したほうがいいなと思っているところですが、具体的にどの場面、今のところ考えておりません。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"３０年以上続いているならば、そうすべきだと思うのですが、実際、区長会、副区長会では、都にどのような要望をしているのか。たしか毎年、区長会、副区長会でも要望していると思うのですが、その辺は、どうなのでしょう。","respondent":"桑村副区長","answer":"特にコロナ禍ですから、東京都が一方的に自分のところの議会で決めていくやり方については、むしろ反対だという考えなのだろうと思います。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"都から２３区にお金を交付金として出すのですけれども、毎年このようなやり方でやっているなら、恒久化する。ぜひ今後も区長会、副区長会で、また、財政課、企画調整課のほうで、都にしっかり進言してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問","question":"１点お聞きしたいのですけれども、この軽減措置の３つの項目について、品川区においては、軽減措置創設以来、適用を受けている件数や金額の増減の推移が、どうなっているか教えていただけますか尋ねました。","respondent":"伊東税務課長","answer":"それと、３番目は、件数的には約１００件で同じですけれども、金額的には３５０万円から３９０万円ということで、若干増加しています。前年比較というところでは、そのような状況です。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"意見","question":"増加したり、特に今年は新型コロナウイルス感染症の影響で、区民や区内事業者でダメージを受けているところはかなりあるかと思います。そういった方々のためにも、この軽減措置は、ぜひ今年もしていくべきではないかなと思っている次第ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、２番目の小規模非住宅用地に対する減免措置。この対象者には、品川区、東京都のどちらが、この減免措置について案内されているのか尋ねました。","respondent":"伊東税務課長","answer":"詳しくはわかりませんけれども、取りあえず１回出せば、その後は申請をしなくてもいい。様々な媒体、主税局で発行しておりますガイドブックや、先ほど言ったホームページのような方法で周知が図られていると認識しております。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"意見","question":"対象の方は、そのようなところを意識されているので、情報は知っているかと思います。該当の方にしっかりと周知できるように、すでに周知されているということであれば、安心しましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-03","title":"令和２年陳情第４８号 子どもが健やかに育つための陳情（陳情項目３）","agenda":"令和２年陳情第４８号 子どもが健やかに育つための陳情（陳情項目３）","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"だから、そういう視点からも、現状は分かりましたけれども、今後のことを考えると、このようなことは全然考えられないものなのでしょうか。必ず次を想定しておくというのは、もう世界の流れではないかなと思うのですが、その点についてお考えがあったら伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"あるいはリモートでの研修をしている男女共同参画センターは、皆有料で設定されておりまして、会議室の在り方の検討も必要になってくる。できるところからやってみて、またお声を聞きながら、進めていけるところは進めてまいりたいと考えております。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"それは分かるのですけれども、方向性としては、やはりオンラインのほうを考えていくべきではないかと思うのです。今、方向性の検討の項目の中に、例えばそのようなことも検討される余地はあると理解してよろしいか尋ねました。","respondent":"島袋人権啓発課長","answer":"今後、講習会等々を開催していく予定で、今進めているところです。その中では、アンケート等で区民の方たちの意見等も取れるかと思いますので、そちらを注視してまいりたいと考えているところです。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"だけど、方向性としては、ぜひオンラインのことも考えるべきだと思います。繰り返しになってしまいますので、これは要望にとどめたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"きゅりあん４階の特別講習室にＷｉ－Ｆｉがあって、その利用料金が５割減額になるので、そちらを利用していただきたいということでした。今、大井町駅前にも整備しているわけですから、そのような方向で、ぜひとも考え直していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"そちらの検討もせざるを得ないかなということもありますし、確かに公共施設におけるＷｉ－Ｆｉの環境整備はとても必要だと思います。そちらとのバランス、公共性等々を考えながら、公平な使い方ができる会議室を目指していきたいと思っているところです。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"これは進めるべきではないと申し上げたいと思います。ぜひとも有料にするのはやめていただきたいのですけれども、いかがか尋ねました。","respondent":"榎本総務部長","answer":"今、男女共同参画センターには会議室が１つしかないのです。移転しなければいけないところもありますので、そういった意味では、今の段階でＷｉ－Ｆｉ環境の要望には添えないかなという状況です。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"それは男女共同参画センターの事業をより拡大していって、区民に身近な存在になれば、また増えてくるのかなと思います。やはりＷｉ－Ｆｉ整備は当然進めていくべきだと思いますので、検討していただきたいのと、今までどおりでお願いしたいと申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"そこは重々加味してやってほしいと求めました。意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"現状の確認をします。どれくらいの登録団体があって、その団体の方からのＷｉ－Ｆｉのご要望の声や、どれくらいお部屋が活用されているのか。","respondent":"島袋人権啓発課長","answer":"何人というお示しはできないのですけれども、出入り口のところには、記入していただくように記載名簿を出しています。このところは、若干減っているような傾向が見られるようです。","id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"４９団体のうち、約半数は実体があるというか、活動されているということが確認されました。ぜひそこはご検討を頂きたいなと思いますが、再度、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"確かに、令和４年からきゅりあんの大規模改修が始まってまいります。その間、合わせて、男女共同参画センターの様々な貸会議室の在り方等も検討していく必要があるのではないかと考えているところです。","id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問","question":"先ほど質問もさせていただきました。今後、課題をしっかり検討いただき、きゅりあんの改修の時期に合わせてご検討していただくということで、今回の陳情に関しては不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すということと、採択でお願いします。やはり陳情要旨にもあるとおり、男女共同参画センターにＷｉ－Ｆｉを設置すべきだと私も思いますので、採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"やはり、今お話を聞いていて、貸出は区民に対して平等に行う。そういうものが様々整った上で、区はこれからも改善云々があるのでしょうから、そのときにまたＷｉ－Ｆｉ設置等を考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"吉田委員","kind":"意見","question":"ただ、条件整備は、区や議会が考えるべきことです。採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"率直に、今の東京都の財政調整の仕組みは、結局、自治体の財政を独自に作っていくという視点で、区はどのようにお考えか、伺いたいなと思います。大雑把な質問になってしまいましたけれども、その辺のところを品川区はどのように考えているのか、伺いたいと思います。","respondent":"品川財政課長","answer":"木造密集の関係や木密不燃化１０年プロジェクトなどがありましたけれども、各区、やはり両者が協力し合って事業を進めているという部分もあります。しっかりと国、都、各自治体とが連携して動いている事業もあるです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"使える補助金や制度をこちらが主体的に使うことはとてもいいことだと思うのです。特に財政調整の仕組みを見ても、まだまだ２３区独自施策、主体的に東京都との交渉に当たっていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"そして、国や都に出向くと思うのですが、どの部署に行くのですか。その辺も説明を求めました。","respondent":"品川財政課長","answer":"大体１月から２月、４月ぐらいまでのもあるのですけれども、年度末ぐらいに交付を受けるというものもあります。それから、どの部署にということですけれども、これは完全にそれぞれやっている部署でヒアリングなどをやっていくというものです。","id":"exchange-031"},{"speaker":"須貝委員","kind":"提案","question":"それもいいかげんな提案だったらだめだよと、じくじたる思いというか、やはり独自色というのはなかなか難しいのかなと思いました。大変だと思いますけれども、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで、ここで１回審査に入りますよという内示なのですかね。その辺のことを教えてほしいと求めました。","respondent":"品川財政課長","answer":"ただ、内容によっては、何回か行うということもあるかと思うのですけれども、基本的には１回としていると思われます。ですので、回数は何回ですかという質問に、なかなか具体的にお答えすることはできないのですけれども、そのような状況です。","id":"exchange-033"},{"speaker":"吉田委員","kind":"確認","question":"１団体が国からの補助金をもらうことに比べたら、そのような形になっていると理解してよろしいでしょうか。その辺だけ確認したいと求めました。","respondent":"品川財政課長","answer":"具体的な金額の調整等は、その後の交付申請書の審査等で若干微調整があるというのが大きな流れかとは思います。これもケース・バイ・ケースでいろいろ違うとは思いますので、そこのところはご了承いただきたいと思います。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"始めの年は実績報告が出せないわけですから、何か手間がかかるのか、その辺のことも説明を求めました。","respondent":"品川財政課長","answer":"原則は当年度が始まる前の１月か３月ぐらいで少し動きがあるものもあるのですけれども、急遽という形でもいろいろ出てくると思います。これもお答えになっていないかもしれないですけれども、ケース・バイ・ケースで流れは違ってくるかなと考えています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"確認","question":"初年度でも、内示が出れば、大体大丈夫という感じですか。ケース・バイ・ケースだろうとは思いますけれども、おおよそということで理解していいか、少し確認したいと求めました。","respondent":"品川財政課長","answer":"その計画の内容等を審査して内示を出しますので、基本的にはここで補助金の対象になるか、ならないかというところは決まるかと思います。しかし、何回も言いますけれども、これもケース・バイ・ケースでいろいろかとは思います。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"いろいろありがとうございました。今のお話を伺っていると、その辺に区としての創意工夫をきちんと盛り込んだ形で、ぜひ出る補助金はきちんと活用していただけたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"こちらから訴える気持ちを分かってもらうには、やはり会って話をしたり、聞いてもらうということも大事ではないですか。実際、どこまでお話ししていただけるか分からないのですけれども、説明を求めました。","respondent":"品川財政課長","answer":"２分の１まで出します、４分の１まで出しますとしっかりと書いてはあるのですけれども、やはり微妙なところがあります。どうしても国、自治体等でいろいろと言い合いというか、やりとりは出てきてしまうことはあるかと思います。","id":"exchange-038"},{"speaker":"須貝委員","kind":"意見","question":"本当にこれだと民間会社のサラリーマンの方が、会社でお得意先と対応しているような現状だと思います。国では忖度という話が出ていますので、私が思っていた以上に予算を持ってくる、補助金を持ってくるというのは大変なのだなと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]},{"id":"topic-05","title":"今定例会の一般質問に関わる所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","agenda":"今定例会の一般質問に関わる所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"実際、依命通達を自分でコピーして持ってきたのですけれども、８月３日に副区長が各部長宛てに出した依命通達です。具体的な質問は、原則１０％のマイナスシーリングを各部局にかけるということで、その趣旨、理由を質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2178#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":30975,"voices":131}},{"id":"r02-20200924-6","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"区民委員会","time":"午前１０時００分～午後 ３時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を70件整理しています。","topics":[{"id":"topic-01","title":"しながわ活力応援給付金事業の進捗状況","agenda":"しながわ活力応援給付金事業の進捗状況","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"その段階で申請率が８８.１％ということなのですけれども、約５週間ぐらいの時点でどれぐらい申請があったのか、そちらについてお伺いしたいです。そちらのほうお伺いをすれば、もしお分かりになれば、約５週間たった時点での申請率を説明するよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"くにば委員","kind":"質問・要望","question":"さらに追ってアプローチができるかという部分、ここを前回６月２９日に私は委員会でも申し上げたのですが、そこをぜひ頑張っていただきたいのです。それで現在当初予想と比べて、おおむね順調なのかどうかという、まずそのざっくりな部分を伺いたいです。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"申請率につきましては、受付開始当初から、多くの方々から申請をいただいている状況で、先ほどの８８.１％というところで推移しているところです。","id":"exchange-002"},{"speaker":"くにば委員","kind":"質問","question":"勧奨通知でどこまで拾えるかという部分だと思うのですけれども、最終的に勧奨通知を送って、それでも返信というか、申請がなかった方に対して、一番最後の拾い上げとしてのアプローチというのは、何かその施策をお考えか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"勧奨通知の発送につきましては、国の定額給付金よりも早めのタイミングで発送を考えています。生活福祉課、障害者福祉課といった担当課と連携して、申請されていない世帯に個別のアプローチできる部分に関しては行っていく予定です。","id":"exchange-003"},{"speaker":"くにば委員","kind":"意見","question":"一番最後の部分で、直接細かい部分にアプローチしていただけるということで、もろもろその施策を考えていただいていると聞き、安心しました。最終的にどこまで９９.２％辺りに近づいていけるかどうかということを私のほうも期待をしながら見守っていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"特別定額給付金１０万円のときはどんどん増やしていく感じで作業員を、給付をする方を増やしていたのですけれども、この今回の活力応援給付金のほうは増やしたりという変化はあったのかということを伺いたいと思います。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"コールセンターの体制ですが、コールセンターは電話機１５台、オペレーター１５名という体制で行っております。続いて給付作業につきましては、８月、９月につきましては、委託業者８０人体制ということで作業に当たっているところです。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっと教えてほしいなと思ったのと、やはり１人でも多くの方に届ける、聞き取りながら活かしてきたというようなものはないのかということを伺いたいのですが。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"特別定額給付金担当と連携しながら、今回のしながわ活力応援給付金に活かすような形で行っていくように考えてあります。ただ、先ほどご答弁しましたとおり、大半のお問合せというのが、申請書を受付後は給付時期に関するお問合せが多いという形になっております。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"この１０万円の給付金と連携はされているということなのですけれども、要は０.８％の方が申請されていないというところでの理由というか、いかがか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"申請をされなかった世帯が０.８％、分析しているというようには伺ってはいます。郵送物が届かないという、また理由がちょっと不明という方もいらっしゃるというところは認識しているところです。","id":"exchange-007"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと１点だけ確認、もうそこに本当に住んでいないかどうかということはどう確認するのかというのを、ひとつ教えてほしいと求めました。できるだけ多くの方にしっかりと届くようにというところで、かなりご努力されているということはよく分かったので、そこだけ教えてもらえますか。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"申請書を送りまして、返戻した数というのが約１,４００件近くありました。今回発送する、その勧奨通知をもう一度同じ住所に送ってみて様子を見るという形ではありますけれども、なかなか理由というものが分かりかねるです。","id":"exchange-008"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。宛てどころに届きませんと返ってきてしまうということで、その後何か対応ができるのかどうか、その辺の考えはどのようになっているか説明を求めました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"給付金事務においては、やはり申請をいただく形になるので、申請書をお手元に届けたいというところがありまして勧奨通知も送るところなのですが、それでも宛てどころなしで返ってきてしまったものについては、なかなか手だてが難しいところかなです。","id":"exchange-009"}]},{"id":"topic-02","title":"交通系ＩＣカードによる手数料収納開始","agenda":"交通系ＩＣカードによる手数料収納開始","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"対象手数料の(1)印鑑証明書等の等は何か教えてください。ＰＡＳＭＯ等の等を教えていただきたいのと、これにかかった経費を教えていただきたいのと、教えてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"実際には、それに伴いまして対応するレジも導入するということで、今年度の予算としては３７万円強という形です。税金や国保でＬＩＮＥ Ｐａｙを使った収納も既に始まっておりますけれども、窓口でのキャッシュレスサービスというものは初めてです。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"すばらしいです。例えばＳｕｉｃａだとそこに現金が入っているわけですから即決済という形で、課長に言うのも答弁は求めませんが、取れなかったか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"どこかで、このような形でこうなったという報告をしてほしいと求めました。本当にすばらしい施策だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"端的に伺いたいのが、こちら事業者に支払う決済手数料が何％なのか、あとこちら端末の設置が全窓口なのか、こちらの２点、まず伺います。","respondent":"木村戸籍住民課長","answer":"住民票が３００円ですので、９円ということです。それから端末に関しましては、この戸籍住民課の住民異動係というところの１つの窓口、１台でスタートというような形になります。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"もうこれがコンビニ等で支払えるようになったのが８年前とか、やはり乗られる方の８割、９割ぐらいですか。７割の方々が小銭を出さず、申し上げました２点、こちら２点をお伺いします。","respondent":"木村戸籍住民課長","answer":"Ｓｕｉｃａでもお支払いできますという形でいくと、比較的お若い方などはすっとそちらのほうでということで、それぐらいで見込んでいるところです。","id":"exchange-014"},{"speaker":"くにば委員","kind":"質問・要望","question":"当然ながらお金ですから、まだお伺いした感じでは厳密にこれを計算していないというような印象を受けたのですけれども、先ほどおっしゃった１億円余。今後に非常に期待しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"これ本当に、やはりキャッシュレス、すごくいいなとは思うのですけれども、今回交通系ということで、流通系のほうの導入の見通しについてもお伺いできればと思います。","respondent":"木村戸籍住民課長","answer":"今回のキャッシュレス化の対応の中で、いわゆる今おっしゃったような中身、何とかペイというものも含めて検討はしてきておるところではあります。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問","question":"もう１点なのですけれども、もう１点か２点か、こちらは今検討状況というものはどうなっているのでしょうか。お願いします。","respondent":"木村戸籍住民課長","answer":"クレジットカードはやはり、ある程度一定の金額というのですか、手数料の関係もあることはあるのですけれども、今検討の、いわゆる扱うものは少額なので、ちょっと今のところは入ってはおりません。","id":"exchange-017"},{"speaker":"松本委員","kind":"確認","question":"もう１点なのですけれども、一応念のための確認ということで、例えばモバイルＳｕｉｃａのような感じのものなどもあります。あるいはスマートフォンで、スマートフォンを持ってピッとできるようになっているのか、ここの部分はどうなっていますか尋ねました。","respondent":"木村戸籍住民課長","answer":"基本的にカードの機能が入っているものに関しましては読み取れるという形です。","id":"exchange-018"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"何点か確認をします。漏れてしまった方が５号認定になるような話を聞いたのですが、この４号認定で申請といいますか、まず教えてもらえますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"先ほど言いました１年間以上継続して事業を行っているとか、そのような、いわゆる客観的なもので判断するところがあります。このような状況ですので、これだから駄目ですということは、多分それに合致しなかったという部分だというように考えられると思います。","id":"exchange-019"},{"speaker":"小芝委員","kind":"質問・要望","question":"もしかしたら商店街の支援のほうに関わってくるかもしれないのですけれども、個人事業主の状況、分かれば教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"個人事業主ですと、どうしても倒産というよりは廃業に近いような形になるのかなと考えています。中小企業のみならず、昨日の家賃支援給付金なども対象になっているところですので、またこれもいろいろと支援を考えていきたいと思ってあります。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私も地域の業者等に話を伺うと、何というのですか、お客さん。そうした意味での、国や都の支援のさらなる継続を求めるとともに、そこはいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"３年間はお支払い、３年あればワクチンができたりとかという部分があって、このように少し長めの設定をさせていただいたところです。攻めのものになるのか、いろいろと方策はあろうかと思いますけれども、適宜その辺はしっかりやっていきたいと思ってあります。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"何というのですか、何というんですか、それで相談に応じていくというようなことも求められてくるのではないかと思うのです。経営のようなところでの、さらなる品川区の相談、支援のこの先というものはどのように考えているのかということを伺いたいのですが。","respondent":"遠藤商業・ものづくり課長","answer":"今うちのほうで形にしようと思っているのが商店街支援なのですが、商業のほうが課題を、五反田バレーのほうでそれなりの企業が。１２月ぐらいにはできるかなというところで、生き残っていくというような形でできればというところで幾つか考えさせていただいているです。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それこそ、やはり融資とともにですが、給付金というところも継続して国と都に積極的に求めていかなければいけない状況なのではないかと思うのです。私たちはコロナ禍ではなくても減税を求めていますけれども、１０％で落ち込んでいたところにコロナということなので、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そのようなものは一旦置いておいて、とにかく支援しようというところで、かなり緩くさせていただいたところです。経営変化対策資金２０１９というところで、最初消費税に対応できるようにということで、別の部分でしっかり対応させていただければです。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"確認","question":"区はどのように把握をされているのか、区が出したのか、ちょっとその辺を確認したいのですが。お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"払拭に努めているところで、先ほどＴシャツなども作られて、そちらにつきましては私ども助成などもさせていただいているところです。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"していくべきだし、ぜひ所管を越えて、そのようなことを求めていただけたらと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"松本委員","kind":"質問・要望","question":"私も武蔵小山エリアでパルムや戸越銀座などが、その辺りは、ちょっと今日の話とは違うのであくまで要望として少し申し上げておきたいと思います。お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"それから創業支援センターなどでもいろいろと支援させていただいているところですが、多くの方、今後大体８回ぐらいの研修などを受けまして。創業支援は大変重要なものだと考えていますので、今後もいろいろな形でさせていただこうと考えています。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問・要望","question":"要望なのですけれども、こういったことをどんどん広報していただくというところ、やはり景気というのは、何でしょう、気から来るというところもあると思いますので、ぜひ明るいほうもいろいろと広報してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問・要望","question":"特にＩＴ関係の五反田バレーなどはそうだと思うのですが、その辺の現状というものはどのように捉えていて、どのように分析しているか。その辺どのように捉えているか教えていただきたいのと、あと４番の倒産状況というのは、その辺はどのようになっているかということを説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"いわゆる経理などの部分はテレワークでできるけれども、テレワークの状況を聞いているようなところです。それから先ほどの企業の倒産状況ですけれども、こちら倒産だけになりまして、廃業については現在のところちょっと確認ができないです。","id":"exchange-028"},{"speaker":"大倉委員","kind":"質問・要望","question":"分かりました。もう１回教えていただきたいのと、これはまさにその後、最後どのように今後どう支援していけるかという考えがあったら説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"民間の調査機関では、今年は５万件を超えるだろうというような話があるので、やはりお辞めになる方が増えているのかなという認識はあります。","id":"exchange-029"},{"speaker":"くにば委員","kind":"提案","question":"私のほうからは大きく２点、質問や要望、提案をします。先ほど４万件が５万件になったという全国の数字もあるのですけれども、どのようなことを考えていらっしゃるかという部分、まずはそこを伺いますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"区内に限っては、かなりうちのほうも充実させていただいたので、少し減ってそれほどでもないのかなというふうに考えているところです。例えば、先ほど個別の支援ということでは、そのようなところでの支援を中心に進めていけばと思っているところです。","id":"exchange-030"},{"speaker":"くにば委員","kind":"提案","question":"提案であったりとか、要望であったりとかなのですけれども、再チャレンジの支援をしていくという。結局そのくくりというものは難しいではないか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そこの中で創業する方用の融資メニューなどもありますので、現状ではそのようなところで対応するような形になるのかなと思っているところです。","id":"exchange-031"},{"speaker":"くにば委員","kind":"質問","question":"一旦廃業なされた方が、もう一度引き続き同じ事業をする場合は、もう一度創業支援という形で受けられるのですか。第二創業のような形で受けることが可能なのかどうか、例えば１年半後にもう１回創業というか、創業支援融資を受けられるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"別の融資を受けていた場合には創業支援を認めないというような規定はあるかもしれない、そのときにこの創業支援もできればですので、そのようなものを組み合わせてその方に支援できればと考えています。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問・要望","question":"断念してしまったけれども、もう一度チャレンジをするという方に対して、ぜひ区として独自に支援をしてほしいと求めました。それが１点目でもう１点あるのですけれども、時間的にもう無理ですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問・要望","question":"どういった部分が品川区の強みであるか、どういった部分が業種としては品川区に多いけれども、区としての施策を打っていただきたいなと。それが今１つが屋形船なのですけれども、満遍ない支援以外に、品川区としての特色を出していく支援策について伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"その中でも唯一商店街の部分については、特別に給付という形で少し考えているところです。その辺のところで既に今の支援と、それからイベントなどを行うときに助成率なども少し変更させて、そのようなところで区の特色を出していければです。","id":"exchange-034"},{"speaker":"くにば委員","kind":"質問・要望","question":"１年、最終的にバウンドで、どれぐらいの角度で戻ってくるかというのは業種ごとに違うと思うのです。全体の業種ではなく、そこに関しての施策を今後考えていただきたいというのが要望というか、今後品川区がやっていくべきことなのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"くにば委員","kind":"質問","question":"それに対して再質問というか、そちらに関しては、その申請なさる方が借入れがあってもということでしょうか。借入れの残額があってもということか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"以前の融資が残っている場合ですと、区のほうでやっている融資が残っているとお使いいただけないのですけれども、一応そこがきちんと廃業の段階で、今回使うというときに終わっているようであればお使いいただけるという形になります。","id":"exchange-036"}]},{"id":"topic-04","title":"に戻りまして、(3)令和元年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"に戻りまして、(3)令和元年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"令和２年度全体の利用率や利用料収入の低下の見込み、各施設の運営ということで、こちらは試算していると思います。ですので、利用率、収入の見込みと見通しについて、まずはお伺いします。","respondent":"遠藤商業・ものづくり課長、古巻文化観光課長、中元スポーツ推進課長","answer":"産業支援交流施設のブライトコアホールの部分かと思いますけれども、全体で１８０日ぐらいありますので、大体十数％になろうかと思います。現在かなり… 最近は予約自体はそこそこ増えてはきているのですが、やはり同じぐらいの水準で推移するのかなというような形で、今見込んでいるところです。… そして令和２年度の全体での利用料収入の見込みですが、今後だんだん、前年度の８割ぐらいまでは戻るのかなというところで見込みでおります。","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"どうしても大きな声の会話は、スポーツが成り立たないという、そういったスポーツも多々あります。こちらの２点、これはやめてくれなどということを何か方針を出しているのかどうか、そちらについて伺います。","respondent":"中元スポーツ推進課長","answer":"教育総合支援センターのほうで作られているものと連携を常に、高齢者の方までも含めて、それに準じた形で方針として区のほうから情報提供して。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問","question":"ではバスケで利用している人が全くいなくなったのかどうかについても、そういった各スポーツによって違うと思うのです。施設として、実際その利用している方々に対して、そういった実際のオペレーションとしてどこまで感染対策ができているのかということを伺いたいです。","respondent":"中元スポーツ推進課長","answer":"１月からの予定でということでお申出がございましたので、区民の方には申し訳ないのですが、フリー利用は今お休みとさせていただいているところです。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問・要望","question":"結局こちら、やはりキャンセル料という部分を区の施設としてどこまで求めていくのかという部分で、再開に当たっての利用率は大分変わってくるかなと。例えばそのキャンセル料が多く求められる部分に関しては、やはりなってくると思います。","respondent":"古巻文化観光課長","answer":"１年後の予約などは大分増えていますが、今年度中の見込みはまだちょっと立たない状況なので、先ほどご答弁させていただきました。ＰＲに努めたりとか、利用率の向上に努めているというようには認識しておりますので、ちょっと今後の努力の結果がどう出てくるかを見ながら。","id":"exchange-040"},{"speaker":"くにば委員","kind":"質問","question":"考えるのは区のほうで考えるのか、それともこちらの指定管理者のほうで考えるのか、どちらのほうがこちらの取組をなさるのか尋ねました。","respondent":"古巻文化観光課長","answer":"区と文化振興事業団でタッグを組んでといいますか、連携しながら進めていくのが、やり方としては本筋なのかなと思います。丸投げでするということではなくて、区のほうも支援をしたりとか、様々な形で連携を取っていきたいというふうに考えています。","id":"exchange-041"},{"speaker":"くにば委員","kind":"意見","question":"１年後のイベントをどこで開催するかというときに、完全にフラットな状態でいろいろな施設の予約、どこにするかと考えると思うのです。そのために、現状であるとか、検討中のものも含めて、利用率向上のための積極的な施策、ありましたらお教えくださいとの意見を述べました。","respondent":"古巻文化観光課長","answer":"文化振興事業団のほうでどのように進めているのかというところ、そこは今委員からもご指摘などいただいた点も含めてよく検討しながら、何か区もアイデアを出していきたいというふうに考えます。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問・要望","question":"１０１名ということで、このコロナ禍において利用率という点で考えると、やはり低下率が低いということは非常に評価できる部分かなと思っています。そちらに関して見解を説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"逆にそのようなフリーランスの方なども増えてきている状況ですので、それは今回、今年度に入って少しずつ増えているようなところもあるのかなというふうには考えております。","id":"exchange-043"},{"speaker":"くにば委員","kind":"質問","question":"今、やはりオンラインセミナーに切り替えると、そういったホールでの利用というものは減ってしまうのではないかなと。こういったオンラインセミナーが増加するに当たって、そういったホールでの利用は下がるのかどうかの見通し、そこを説明するよう求めました。","respondent":"遠藤商業・ものづくり課長","answer":"３階のほうはいわゆるホールと言われて、あと４階の部分が、あるいはちょっと会議室が設けられているところです。このセミナーについては４階の部分、セミナーのオンラインの開催というところとは、多分連動はしないのかなというふうに考えているところです。","id":"exchange-044"},{"speaker":"くにば委員","kind":"意見","question":"昨年とその一昨年の区民委員会の答弁か何かあったような気がするのですが、そちらに関しては今後どういった形で展開をしていくか、今後利用がさらに増えていくためにどのような施策を打っているのかということを最後に説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"本当はもっとやりたかったところもあったのですが、ちょうどそのこれからやっていこうというところで止まってしまったようなところがあります。","id":"exchange-045"},{"speaker":"大倉委員","kind":"質問","question":"そうした手すりとか、人が触るようなところというのは今どのようになっているかというのを教えてもらいたいので、それではまずそれを説明するよう求めました。","respondent":"中元スポーツ推進課長、古巻文化観光課長、遠藤商業・ものづくり課長","answer":"まず休止期間の間に様々対策を検討し、手すりの清掃など、そのような人が触ると想定される部分につきましての清掃を強化しています。１日終了後に１回… それを通じてしっかりと消毒、共用部分は定期的に消毒をするというような形で、新たに清掃の強化を行っている状況です。 必要な消耗品の部分だけプラスの部分でかかりますということでお話いただいているところで、そちらについては了承しているというような状況です。","id":"exchange-046"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのが、どういうものがいいのかなというので、ちょっと教えてほしいと求めました。","respondent":"古巻文化観光課長、中元スポーツ推進課長、遠藤商業・ものづくり課長","answer":"費用面での考え方ですけれども、契約を変更したりなどという形ではなくて、適正な形で進むような対応をしていきたいというふうに考えております。… 体育館のほうにおきましては、ちょうど今年、実はオリンピック・パラリンピックの練習会場になる予定でございました。もししていないようでしたら… 清掃等の費用の件につきましては、消耗品は先ほどご説明したとおりです。","id":"exchange-047"},{"speaker":"大倉委員","kind":"意見","question":"利用しに行って、安心していろいろ活動してもらえるような取り組みは、ぜひしていただけるというお話なので、していただければなと。例えばきちんと２メートル、きちんと工夫をしていますよというような対応をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そしてホームページにも載せているという自治体もあるので、そうした公開、情報として出していただきたいということは改めて求めたいのです。なので、そうした改善をぜひお願いしたいのですが、いかがか尋ねました。","respondent":"古巻文化観光課長","answer":"運用上のガイドライン等もありますので、そういった中で必要な見直しについてはしていくのかなと考えます。私の口からちょっとどうしますと言いづらいところはありますけれども、いただいたご意見については承って、伝えてまいります。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これは要望にしておきますけれども。それで、この指定管理者のそれぞれの法人で、それぞれの業務に当たっている人数を伺いたいと思うのです。","respondent":"遠藤商業・ものづくり課長、中元スポーツ推進課長、古巻文化観光課長","answer":"ちょっと４階については受付部分と管理の部門ということで、二十数名だったように、２０名前後だったように記憶しております。申し訳ございません。令和元年度の人数ということで回答しますが、合計で１８人という形になってあります。これは理事長の方１名を含めた人数です。私のほうから文化振興事業団の職員数ということでお答えをしますが、令和元年度につきましては、３３名の職員で運用をしています。","id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこの中では、主にどのような声があるのかということを伺いたいのですが、主にでいいです。そこまででもないのか、このような取組は大事だと思うのですけれども、そういった中身を伺いたいと思います。","respondent":"中元スポーツ推進課長、古巻文化観光課長","answer":"もう少し高齢者の方に分かりやすい表示、文字の大きさなども含めて対応していきましょうということで、常に情報共有しながらやっているところです。もう一つのクレーム対応シートは、対応していくというもので… 文化振興事業団所管の２つの施設の関係ですけれども、そうではないのかといったところ、それから設備や備品に関しての関係ということです。","id":"exchange-051"}]},{"id":"topic-05","title":"イルミネーション事業","agenda":"イルミネーション事業","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"今年度もこちらの予算額について中心に質問したいのですけれども、まずはこちらの２,９３０万円余の内訳を教えてください。そちらに関しての経費はマイナスになっていてしかるべきなのですけれども、こちらが増額になっている理由を含めて、内訳を説明するよう求めました。","respondent":"古巻文化観光課長","answer":"こちら基本的には設置に係る委託の経費という形になりますので、人件費相当になる部分が大半になります。式典等は行いませんけれども、基本的には設置に係る経費が主で、ちょっと人件費等々の部分が増えてしまったという状況です。","id":"exchange-052"},{"speaker":"くにば委員","kind":"質問","question":"少し不思議な部分があるのですが、そこに関しての細かい数字というものは特に把握はなさっていないのでしょうかということが１点です。目黒川については、目黒区であるとか、あとは幾つかの企業との共催であるという部分の観点から中止になったのか尋ねました。","respondent":"古巻文化観光課長","answer":"値上がりの部分が少し高いようにも感じますけれども、そのような関係で人件費が上がってしまったというふうに認識をしております。そういったことで企業イメージが多少よくなくなってしまうようなこともちょっと考えて、涙を飲んで中止を決定したというように聞いております。","id":"exchange-053"},{"speaker":"くにば委員","kind":"意見","question":"いろいろ事業者の方々が入っているということもありまして、やはり企業側の都合というものも致し方ないのかなということは重々分かりました。そういったものが様々模索されていると思いますので、そちらに関して目黒川、大変期待をして見ていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"小芝委員","kind":"確認","question":"毎年このイルミネーション点灯の時期になりますと、大井町の駅前、イトーヨーカ堂前を歩いておりますと年の瀬を感じる、非常にセンチメンタルな心にもなったりするものなのですけれども、このイルミネーション事業自体は、まず確認なのですが、文化観光課単独の事業という認識でよろしいか尋ねました。","respondent":"古巻文化観光課長","answer":"庁内の所管という意味で申し上げますと、文化観光課単独になります。観光協会と連携しながらというような形ですので、文化観光課所管という形になります。","id":"exchange-055"},{"speaker":"小芝委員","kind":"質問","question":"これ１年間を通して中国武漢発の新型コロナによって、そういった期間を限定した上でブルーのライトアップを展開していただいたらどうかとは思います。所管が違いますのでお答えづらいと思いますけれども、お考えのほうをお聞かせ願えますか尋ねました。","respondent":"古巻文化観光課長","answer":"共感するところもあるのですけれども、ちょっとその辺りも含めまして、観光協会にも伝えることは伝えるようにいたします。はっきりしたご答弁ができないので申し訳ないですけれども、そういったことでご意見として承らせていただきたいと思います。","id":"exchange-056"},{"speaker":"小芝委員","kind":"質問・要望","question":"予算のほうも決まっておりますので、なかなか追加ということは難しいと思いますけれども、今後、また来年度に向けて考えてほしいと求めました。要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認なのですけれども、白しかできないのですかというのは、もう１回確認で教えていただきたい。これはこのままずっとこれを続けていくのですかという、今聞いていて疑問だったので、その点説明を求めました。","respondent":"古巻文化観光課長","answer":"ちょっとここにバリエーションを加えるような、そのような展開もできるのかなというように考えていますので、様々に工夫をしていきたいと思います。","id":"exchange-058"},{"speaker":"大倉委員","kind":"意見","question":"小さい規模でやっていても、なかなか人が集まってくるようなところにならない。さらなるこの大井町の観光の振興に寄与するような取組にしていただけるといいのかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"松本委員","kind":"質問","question":"いろいろ伺っていて、伺っている限り、これ全部設置委託料というところで区が丸抱えになっているのだと思うのです。何か改善しようというときなども、そもそも論でなぜこれは区が丸抱えをしているのか、そこの部分をお伺いしてよろしいか尋ねました。","respondent":"古巻文化観光課長","answer":"地域の方が地域の賑わいを創出していく、そういったような形でやっている事業という認識の下で、区のほうで設置についてはやっていこうと。とはいえ、様々な可能性も含めて検討して、よりよい形でイルミネーション事業を進めていきたいというふうに考えています。","id":"exchange-060"},{"speaker":"松本委員","kind":"質問・要望","question":"いろいろなところがあると思いますので、また私も研究して、いろいろと質問等させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"つる副委員長","kind":"質問","question":"何というのですか、やるからにはそういったところに対する意識、本当にちょっとした心がけだと思うのです。決められた予算の枠の中でできるのであれば、ぜひお願いしたいと思いますが、改めてご答弁をお願いします。","respondent":"古巻文化観光課長","answer":"色がどこまで、全面的にということは確かに難しいと思うのですが、何かワンポイントでもできることがあれば考えていきたいと思います。","id":"exchange-062"},{"speaker":"つる副委員長","kind":"意見","question":"それはそれで実際に働かれている方々に対して、いや、別にそのようなことは関係ないのだというご意見の方もいらっしゃるとは思うのです。できる限りの中での、そういったところも必要なのではないかと思いますので、ぜひ積極的に観光協会のほうと協議してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"}]},{"id":"topic-06","title":"１０月のイベント開催予定情報","agenda":"１０月のイベント開催予定情報","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"今年行こうと考えているけれども去年はどういった形だったのだろうということが、アーカイブ性としてすごい大事な部分ではあると思うのです。は今後の方針について、取組をどう考えていらっしゃるのか、ご答弁をお願いします。","respondent":"古巻文化観光課長","answer":"適正なというか、適切なものといいましょうか、そういったものを使っていくということは重要かなと思います。今いただきましたご意見も十分に踏まえまして、しっかりと考えて今後につなげていきたい、このように考えております。","id":"exchange-064"},{"speaker":"くにば委員","kind":"質問・要望","question":"このようにしてくれということがなかなか言えないという部分のお話を伺ったのですが、ウェブの生放送、生配信ですね。所管の課の中、グループの中で話合いを持たれて、ぜひ進めてくださいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"松本委員","kind":"質問","question":"区長、あるいは役員会などあるとは思うのですけれども、そういった連携していきましょうというような話合いというものはなされていないのでしょうか。どうなのか尋ねました。","respondent":"古巻文化観光課長","answer":"決して何も連携していないとか、なかなか、マンパワー的にちょっと実現が難しい面もあるというようなことでお話をさせていただいたのかなと思います。","id":"exchange-066"},{"speaker":"大倉委員","kind":"質問・要望","question":"これ、少し縮小した分予算が余ったりするのかなというところが分かれば教えていただきたいのと、いろいろな方が見る機会が増えるというところでも。そうすると、そのような人たちに発信してもらうというやり方も１つあるかなと思っているので、そういったところについてはどうか尋ねました。","respondent":"古巻文化観光課長、山崎文化スポーツ振興部長","answer":"この縮小した部分については当然予算の縮小をした上での実施になると思います。なかなか統一した対応というものは難しいのかなと思いますが、文化観光課のほうでも十分考えますので、なるべく事業の目的が達成できるように。本日この本委員会に１０月のイベント開催予定ということで、あえてこの５つのイベントをくくった形で報告をさせていただきました。","id":"exchange-067"},{"speaker":"大倉委員","kind":"意見","question":"ＹｏｕＴｕｂｅの視聴は増えているというのも大きくあるのかなということが１つと、見てもらえるような取組にしていただけるといいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"}]},{"id":"topic-07","title":"品川歴史館特別展「広がる品川臨海部－新地開発から八潮地域の誕生まで」","agenda":"品川歴史館特別展「広がる品川臨海部－新地開発から八潮地域の誕生まで」","exchanges":[{"speaker":"小芝委員","kind":"確認","question":"そこの突き当たりのお部屋でよろしかったでしょうか。その配置が、メインがたしか左側のほうにありますけれども、どの辺りを指すのか尋ねました。","respondent":"古巻文化観光課長","answer":"左手のと、あと右のちょっと奥のほうに小さいお部屋があるのですけれども、こちら２か所で特別展は大体開催をしております。今回も同じようなレイアウトで行わせていただくように、展示を今製作しているところだと思います。","id":"exchange-069"},{"speaker":"小芝委員","kind":"質問・要望","question":"そういったところをぜひとも歴史館の中に組み込んで、地域の方、そして区外の方にも知っていただきたい。本当に大変すばらしい試みだと思いますので、私もしっかりと伺わせていただきますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2880#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":75048,"voices":200}},{"id":"r02-20200924-7","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"厚生委員会","time":"午前１０時００分～午後 ４時３１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件整理しています。","topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(2)から先に行います。 それでは、(2)品川区成年後見制度利用促進基本計画の策定","agenda":"冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(2)から先に行います。 それでは、(2)品川区成年後見制度利用促進基本計画の策定","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"なぜ利用促進なのかということをまずご説明願いたいのと、あるいは知的障害の会の方などから、その点へのお考えも伺いたいのですけれども。２点、お伺いしたいのですけれども、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"各種法的支援や福祉サービスの利用、生活支援を行うということで、このように認識しています。それから、そういったことがあるのであれば、いかにそこを防ぐかということを検討していくことが重要であろうと考えています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"そこら辺のご認識や姿勢を伺いたかったのですが、いかがでしょうか。補佐や補助の制度があるというのは、ここでは関係ないことだと私は思うのですけれども、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"それを必要としている方がいらっしゃるので、こういった計画は必要であるというふうに認識しております。もし問題点があるのであれば、この計画策定の中で、それをしっかり検証して生かしていく必要があろうと考えております。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"それも事実ですから、そこら辺の抵触をクリアするように、計画を定める場合にも注意をしていってほしいと求めました。２．基本計画の内容の(1)計画の目的のところで、まず、この国の計画に基づいて品川区も作るという仕組みになっているのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"今、検討委員会の委員は１１名を予定しています。区がやるのか、社協がやるのか、連携してやるのかといった辺りも含めて検討委員会の中で進めていくというふうに考えております。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"委託するとしたら、どこに委託するのでしょうか。それとも内部の職員の方で作られるのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"現時点の予定では、区福祉部の職員、保健所の職員、それから社会福祉協議会の職員といった辺りの内部で検討することを考えております。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここで言うとチームということですか、今、いわゆる地域包括支援センターを高齢者福祉課に置いているような形で何か置くということが可能なのか。どうやらどこかでこの成年後見制度が入ってきていて、基本的には高齢者虐待防止法の２８条で、その辺りを教えてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"既に実績のある社協がありますので、どういうところの役割分担をしていくかということが正にこれからの検討課題であろうというふうに認識しています。いわゆるケース検討をするという、どういった形で対応できるかというのは、必ずケース検討をするということで。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"希望されたいというときには、しっかり区のほうで担保できるような形に中核機関も仕上げていただきたいというところが１点要望です。それと、もう１回お聞きしますけれども、高齢者虐待防止法の先ほどの会議の中で、成年後見制度を利用しないこともあるということなのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"当然そういう対応をしているのですけれど、何らかの形で明らかに必要だと思われるものについては、必ず一度通るようにはなっているという仕組みになっております。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"計画期間が３カ年ということで、これからは見直しをしながらずっと３年間に１回、計画を作り替えていくことになるのでしょうかというのが１つ。まずは計画の素案という形でできるのがいつ頃で、厚生委員会にそれを報告していただけるのがいつ頃なのかということもお伺いしたいと思います。","respondent":"寺嶋福祉計画課長","answer":"その他の上位計画等とのバランスもありますので、その辺も見ながら検討していくことになろうかと考えています。それから、この委員会につきましては、公開を予定しています。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"そういうものにしていくという計画の目標は、国の計画を見るとそのような感じがするのですけれども、こういうものに沿って区としても行っていくということでいいのか説明を求めました。","respondent":"寺嶋福祉計画課長","answer":"先ほど申し上げたとおり認識しているところですけれども、今のところ、そういった事例がまだ入っていないということも先ほどお伝えしたとおりです。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところの、全く問題ないということではない部分は区に届いていないのかもしれないですが、私はそういう細かいところが様々あると思うのです。これだけ全国的に課題ということにもなっておりますので、そういうところも含めて、前進できるような形での計画にぜひしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-02","title":"特別定額給付金事業の進捗状況","agenda":"特別定額給付金事業の進捗状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"１,８００前後だと思いますが、これは大体どういう世帯が支給済みになっていないのか、把握されていたらその点をお伺いしたいです。４にある未申請者への勧奨通知の発送、８月５日にやったとありますけれども、その数字も伺えればと思います。","respondent":"寺嶋特別定額給付金担当課長、櫻木生活福祉課長","answer":"細かく１,８００の住所を全部見て回ったということではないので、この内容については、こちらでは把握できかねます。それから、勧奨通知につきましては、１万６９２通（世帯）、発送をしております。 私からは、ホームレスの申請と受給について答弁申し上げます。４月以降、おおむね月に１件程度ということで、おおむね受給していると私どもは認識しております。","id":"exchange-010"},{"speaker":"渡部委員","kind":"質問","question":"無事、終了するのかなというところなのですが、１件だけお伺いしたいのは、今回、国の制度として、日本全国の自治体がこれに携わってきた。ないなら、これは上げてほしいと思うのですけれども、いかがか尋ねました。","respondent":"寺嶋特別定額給付金担当課長","answer":"改善をお願いして、一定程度改善されたということもございまして、パイプが全くできていないということではないです。積極的に発言はしていきたいというふうに考えておりますし、これはしっかり財産として伝えていきたいというふうに考えております。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３万３,７０８件ということで、私も質問したことがありますが、何かそういったものを聞き取ったものがあるのかどうか。そういう意味での内訳みたいなものがあれば教えてほしいと求めました。","respondent":"寺嶋特別定額給付金担当課長","answer":"コールセンターがつながりにくくなったということで、つながらないのだというお叱りのお電話をいただいたこと、これもかなりの件数がございました。世帯の確認、そこを教えてもらえないかとか、そういう問合せが意外と多かったということを担当から聞いたことを記憶しています。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問","question":"何か国のほうに戻すような、そういうお問合せが多かったというような声を上げるということは、何か制度上あるのですか。制度上はない。","respondent":"寺嶋特別定額給付金担当課長","answer":"一旦全額国から歳入しているのですけれども、当然多めに入っているので、その精算作業という形になります。もしそのときに声を上げるタイミングがあれば、ぜひ伝えていきたいと思います。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"情報の確保の仕方と活用の仕方というのは、所管が違うかもしれないですが、どうなっているのか伺いたいです。どうなっているのか、あるいはどうしていくのか。","respondent":"寺嶋特別定額給付金担当課長","answer":"情報があれば、より利便性がということがありましたので、ご本人の同意があった場合について振込をする形をとったというふうに聞いております。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問","question":"その件について、担当も違うのかもしれませんが、また別の機会にお聞きします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ちなみに、委託の職員というのは、どれぐらいの体制だったのか尋ねました。","respondent":"寺嶋特別定額給付金担当課長","answer":"コールセンターには電話が１５台ありますとか、操作するパソコンは１５台ありますということで、場合によっては夜もという形を含めての対応ということでやらせていただきました。","id":"exchange-016"}]},{"id":"topic-03","title":"令和３年度分品川区立高齢者住宅（単身用）補欠登録者の募集","agenda":"令和３年度分品川区立高齢者住宅（単身用）補欠登録者の募集","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"募集内容として、補欠登録者６０人程度と書いてあるのですけれども、実際にこの募集期間に、毎年、何人ぐらいが申込まれて、何人ぐらいが登録されているものなのか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"平成２９年度は５９名ということで、平均６０名前後に申込みしていただきまして、ほとんど皆様が名簿登録するような形になっております。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"今のが申込みをされた人数で、そのまま登録されているということか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"そのとおりです。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今、応募された方の人数ですけれども、入れた方の人数も教えていただけたらと思います。１２月第１週、１１月の末から１２月にかけてみたいなことが多かったと思うのですが、この理由が何かあるのかということも説明を求めました。","respondent":"菅野高齢者地域支援課長","answer":"取消し等辞退された方が１３名、計３５名ということで、６０％前後の方が解決するという比率になっております。１２月から１１月に変えたということに、例えば１カ月とか、おおむね同じような期間に募集するようにはさせてもらっています。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひこれはもっと数を増やしていただきたいと思うのですけれども、その点についてはどうでしょうかということと、年に１回しか募集がないですね。例えば特養ホームと同じような形で、せめて年２回とかの形で、いかがか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"募集期間が年１回ということなのですが、実際に入居できる方の数等を勘案しますと、やはり年１回の募集が妥当な回数ではないかと考えています。随時、高齢者地域支援課の窓口で丁寧に相談対応させていただきまして、住宅のあっ旋事業等につなげしています。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もちろん民間住宅のあっ旋も何度もご相談に伺っているのですけれども、そこでもなかなかないというのが現実なのです。そういう点で言えば、年２回というところは、ぜひ今後ご検討いただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-04","title":"医療的ケア児地域生活支援促進事業に係る運営委託事業者の選定","agenda":"医療的ケア児地域生活支援促進事業に係る運営委託事業者の選定","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"１事業者、公募期間がちょうど２週間ということですが、この点はいかがなのでしょうか。お伺いしたいと思います。","respondent":"松山障害者福祉課長","answer":"この事業を開始するということは、医療的ケアにとって非常に推進するものと認識しておりますので、参加していただくことを予定しております。公募期間につきましては、区のほうでは２週間というのが通例のものですので、決して短いという認識はございません。","id":"exchange-022"},{"speaker":"西村委員","kind":"質問","question":"３点ほどお伺いさせてください。看護師の方や保育士の方の常駐の体制を今お伺いしたのですが、お伺いしたときに常に相談ができるのか、どのような環境なのかを尋ねました。","respondent":"松山障害者福祉課長","answer":"３点目ですけれども、年齢層についてです。確かに乳幼児、未就学児が中心になると今のところは考えております。","id":"exchange-023"},{"speaker":"西村委員","kind":"意見","question":"隣り合わせに児童センターがあるというところがすごく魅力だと思います。健常児と触れ合うことで身体能力がすごく上がったということを聞いていますので、ぜひそれは期待をしていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"あくつ委員","kind":"質問","question":"ほわわ品川があって、そことの役割分担、どういうふうに医療的ケア児の役割分担をお考えになっているのかというところ。国のほうでも永田町子ども未来会議、どういった形で連携をしていくのか、そういったことも含めての今回の選定なのかどうかお聞きしたいと思います。","respondent":"松山障害者福祉課長","answer":"東品川のほわわとの役割分担につきまして、東品川のほわわは、児童発達支援という事業所を行っております。医療的ケア児等支援関係機関連絡会にも、フローレンスにもご参加いただく予定ですので、その中で連携を密にしていく。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"確認","question":"一応念のため確認しますが、こちらの新しい施設は、お子さん一人の場面はない、基本的には親子でずっと一緒だと、こういうことでいいか尋ねました。","respondent":"松山障害者福祉課長","answer":"委員ご指摘のとおり、親子での参加になります。","id":"exchange-026"}]},{"id":"topic-05","title":"品川区立障害児者総合支援施設","agenda":"品川区立障害児者総合支援施設","exchanges":[{"speaker":"西村委員","kind":"質問","question":"１点だけお伺いさせてください。今、コロナ禍でもありますので、先方の見直しの中でそういった影響もあったのかということだけ尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"運営事業者のほうからは、申出のときに、今後のことを考えると、人を多く集めて行う事業については厳しいだろうということで、理事会等で判断をされたというふうに聞いております。","id":"exchange-027"},{"speaker":"おくの委員","kind":"質問","question":"私も利用者の方からお話を伺いましたし、やめないでほしいと、非常にいいということで伺っているのです。福祉施設ですから、１年もたたないうちに、どんと公募に出してしまうということ自体が私には全く理解できないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"おくの委員","kind":"質問","question":"というふうに私は思いました。それで、なぜこれが公募になったのか、そういうことがいつどこで決まったのか、そういうことをお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"公募の実施につきましては、期間を３年とし、次回公募する旨のご説明をしています。建物全体にかかる管理を区が実施しており、それぞれの事業にかかる部分の管理運営を指定管理者が実施しておりますが、公募を実施するものです。","id":"exchange-029"},{"speaker":"おくの委員","kind":"質問","question":"建物全体の管理運営という点では、今の事業者に共同事業体という形で管理運営をやってもらっても構わないのではないか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"そこに建物管理を実施させる方法等も検討したのですが、それは難しいということで、結果として区が建物管理をすることになったという経緯があります。今回はそういった課題を解消し、一体的な管理を実施できるようにするための公募ということになっております。","id":"exchange-030"},{"speaker":"おくの委員","kind":"質問","question":"事業体の方々は、今も建物管理は難しいとおっしゃっているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"私は、運営事業者から建物管理は難しいというふうに聞いておりますが、今回、公募をするということにつきましては、昨年度、事業者にはお伝えしておりますので、この間で検討はしているかと思います。","id":"exchange-031"},{"speaker":"おくの委員","kind":"質問","question":"公募ということは、平成３０年８月に決まっていた規定の方針ということで発しているという、そういうことなのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"はい、そのとおりです。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"今、どこで公募が決められたのかというのは、２０１８年７月３０日の厚生委員会で説明しているというご答弁だったのでしょうか。そのような中で、１年もたたないうちにそういうふうに公募するということがどこで決められたのか伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"７月３０日の厚生委員会のやり取りの中で、当時の担当課長のほうから、３年後に公募を行うという旨を回答しています。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それを改めて確認させてほしいと求めました。５年たったら、またそこのところを５年後も選ぶというようなことでほとんどされてきたと思うのですが、どう考えられているのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問","question":"委員長、途中ですけれども、いいですか。もし４５分で中断するとしても、もう１回そこは、１回中断という形でお願いしたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"２０１５年に、４法人の共同事業体ということで、本当に期待を込めて選定をしたわけです。そういうところでは、その困難を乗り越えて期待を背負ってやってきた、そのことに対してどう考えているのかということを伺ったのです。","respondent":"築山障害者施策推進担当課長","answer":"先ほども説明させていただいたのですが、区が実施しているというのが望ましい形ではないので、それを本来望ましい形である総合的・一体的な管理運営実施のために公募するという趣旨でありますので。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"始まって１年弱ですけれども、またこれを続けてほしい、そこのところはどう考えられているのかということを聞きたいのです。今回もしこういう公募という形になったとしても、利用者の意向も汲むべきだと思うのですが、その点についてはどう考えられているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"運営法人のほうには、先ほどもご説明いたしましたが、昨年度から公募を実施する旨は伝えておりますので、検討はされていることかと思います。利用者の意向ですが、この辺りも、今回の公募は建物管理の部分から始まっているところですので、そのために実施するというものです。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この２０１５年の選んだ経過、それから、そこのところに対して区としてどう評価されているのかということについてもお聞かせほしいと求めました。それともう１つ……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１回確認したいのですが、その中に区民とか利用者の声というのは、全く関係ないのでしょうか。１点目、伺います。","respondent":"築山障害者施策推進担当課長","answer":"今回ご説明させていただいていることは、総合支援施設の公募を実施するというご報告についてです。ですので、今回はあくまでも公募の実施に関する説明をしているというところでご理解をいただきたいと思います。","id":"exchange-039"},{"speaker":"あくつ委員","kind":"確認","question":"課長を個人的にどうのこうのというのはないですけれど、その説明が私はちょっとよく分からないです。公募のプロポーザルの中においては生かされる、当然生かされる、こういうことで確認させていただいてよろしいか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"事業者選定については、区民の声も審査項目の１つにはなってくるかと思います。","id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１つ確認をさせていただきたいのが、効率的で効果的な区民サービスの提供とうたってありますが、具体的にはどのようなことが必要なのですか。こういうものが２０１５年からいろいろなことがありましたけれど、それについて何か区民から、こういうお声が上がっているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"建物管理というところで、それも含めた総合的・一体的な施設の管理運営を行うために実施するというところが理由となっております。具体的にはというご質問がございましたが、これは例えば相談から支援へのつなぎといったようなことが該当してくるかと思います。","id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問","question":"少し質問が前後しますけれど、３団体においても、形式的には公募の要件を満たすのかどうかということが１つ。この３点をお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"それから、２点目ですが、審査については、公平公正な選定を実施いたします。その後、体制等、区との協議の準備期間を踏まえますと、妥当な期間かと考えています。","id":"exchange-042"},{"speaker":"あくつ委員","kind":"質問・要望","question":"審査については公平公正にやっていただけると、こういうことは今、確認させていただきました。それと８、１回目の２０１５年ですか、前の公募のときと大きく変更した点があるのかどうか。","respondent":"築山障害者施策推進担当課長","answer":"その下の(6)ですが、共同事業体の構成団体による、それぞれの責任区分を記した協定書を提出していただきます。」ということで、こちらも具体的に明記をさせていただき、これについて「事前に区に協議するもの」としております。","id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"８の共同申請の(5)と(6)のところですけれど、代表としか協議を行わないという、わざわざこういう文言も付け加えられたのですかね。結局決まった後に責任区分を記した協定書を提出していただくということですから、前と何が違うのか、そこについてもう少し詳しく説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"現在の状況ですけれども、現在は個々で協定を結んでおりますので、共同事業体による協定書等は存在しておりません。代表としか協議しないというのは、総合的かつ一体的な管理運営を実施していただくために、そのような表記をさせていただいたものです。","id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問・要望","question":"総合的・一体的な管理をするのに、代表団体としか協議をしないというのはなぜなのでしょうか。私はこの意味がよく分からないのですが、そこについて教えてほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"総合支援施設は多数の業務がありますが、代表法人には包括的に責任を持って担っていただきたいというところがあります。区が参加を認めた場合は、その限りではないですので、協議内容によっては構成団体も交えた協議を行う場合もあります。","id":"exchange-045"},{"speaker":"あくつ委員","kind":"確認","question":"それはなぜこうなったのか、そこはなかなかお答えいただけないので、これ以上は申し上げません。もう１回確認したいのですが、にっせいかんについては、いつまでの契約になっているのか説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"ですので、１０月１日から９月末までというのが１つの区切りになります。次のクールですが、デイ・ケアのサービスは実施しませんので、それ以外の事業について、また次の９月末までというふうに、１年ごととなっております。","id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"今の点でお聞きしたいのですが、９月末をもってということでしたが、もう来年度の更新はされているということでいいのでしょうか。今回ではなくて以前の議会でそのような質問もありましたけれど、令和４年１０月１日まで、お考えになるのか説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"クリニックにつきましては更新の手続きを行っているところです。こちらは地域活動支援センター等で利用しまして、そこで対象者を拡大したサービスを実施していきたいというふうに思っているところです。","id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"考え方、やり方ですから、これはもうトラブルが起きて当たり前ですよということをそのときに申し上げました。絶対に不安にさせてはいけないし、またサービスを受けられるように強く強く要望いたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"おくの委員","kind":"質問","question":"具体的なことですが、８の(1)で「共同事業体」となっていて、「法人」となっていない意味についてお伺いしたいと思います。(5)、(6)のところで、「法人」という言葉が使われていない意味についてお伺いしたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"それから、３点目の審査会、選定委員会についてですが、メンバーにつきましては、これから決めていくことになります。選定委員会では、それを踏まえて指定管理者候補者の選定をするということになります。","id":"exchange-049"},{"speaker":"おくの委員","kind":"質問","question":"(1)から(4)まで「法人」という言葉が使ってあって、(5)、(6)で「法人」ではなく「団体」という言葉が使ってあるのに特段意味はないのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"特に大きな違いはございません。失礼いたしました。","id":"exchange-050"},{"speaker":"おくの委員","kind":"質問","question":"それから、審査会と選定委員会というのは、仕組みとして、実際に選ぶのは選定委員会だと考えてよろしいのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"はい、そのとおりです。指定管理者候補者を選定委員会で選定いたします。","id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"提案","question":"その点、代表法人がどれだけ共同事業体をまとめていけるのかというのでしょうか、そういったところに関してどうお考えかということ。そういうところについて、区は考えていただけるような提案とか、どのように考えているのでしょうかということの意見を述べました。","respondent":"築山障害者施策推進担当課長","answer":"実際に区職員だけで避難所運営を回していくことは現実的なところで難しいところも出てくるかと思います。今後、それから、そういった地域生活支援拠点としての役割を担っていく施設というふうに考えております。","id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今それぞれの方向をお話しいただいたので、それが実現するような形で、この方法はぜひ進めていってほしいと求めました。もちろん指定管理者選定委員会の方々も十分にご理解の上で審査されると思うのですが、改めてその点をきちんと確認してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほどの２０１８年７月３０日のところで、３年後には公募をするということでの議事録は教えていただいて確認させていただきました。これは区自身が選んだことですから、しっかりと重く受止めていただきたいと思うのですが、そこの受止め方はどう考えられているのか説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"２点目、３点目に関してですが、建物管理の実施というところで課題がございました。それは区といたしましても、こうなってしまったことを課題だということで受止めまして、それを踏まえて、今回、公募をすることになったところです。","id":"exchange-054"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところを確認させていただきたい。事業所を変えるということを前提に今回の公募が出されているのではないという確認をさせていただきたいのですが、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"はい、委員のおっしゃるとおりです。","id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、それから家族の方々が本当に大混乱になっていくのではないかということを危惧しているのですが、それについてはどう考えておられるのか。そこのところをどう考えているのか、利用者の意向をぜひ聞き取っていただきたいと思うのですが、その点についても説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"品川区民の福祉の向上ですので、品川区内の障害児者にとって、よりよい方向に向かっていくようにしていきたいというふうに思っております。利用者の意向というところは、選定の中で利用者満足度等も審査項目の１つにはなってくるかというところで考えております。","id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"利用者の中に本当に混乱が起こっていると思うのですが、そういうことをどう考えているのかということについてもお聞かせほしいと求めました。これらのことは反映されるのか、ぜひしていただきたいと思うのですが、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"ご質問の件ですが、まだこちらは公募もしておりませんので、この後どうなるかは未定の状態です。ですので、委員がおっしゃられたことは、選定の際の判断材料の１つにはなってくるかというふうに思っております。","id":"exchange-057"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"利用者、それから現事業者の実績、そこのところを選考の中できちんと大きく位置付けて反映させていただきたいということを強く要望しておきます。利用者意向、現事業者の実績、ここを反映するように強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]},{"id":"topic-06","title":"令和元年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"令和元年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今日の報告を伺っても、分かりやすいところで言いますと、５９ページの真ん中より少し下の総括のところです。字数はもちろん増えるから、だからこそ全面的に変えていただきたいと私は思うのですが、例えばそういうことです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"いや、だから、具体的に書いていただきたいというところを指摘しているわけです。〔「最初の説明で分かっていますから進めてください」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういうことをお願いいたしたいと思います。全般に対して要望したいのですが、どのように考えられるかということを、たまたま障害者……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問","question":"それから、今、具体的に書いてくださればと言ったところの内容を教えていただけますか。５９ページと６５ページ。","respondent":"松山障害者福祉課長","answer":"個別具体的な案件ですので、お一人のことだけを取上げて言っているわけではなく、西大井地区全般にある事業所、複数箇所に関わっているです。グループホーム連絡会につきましても、区内のグループホーム全体を含めた連絡会を主催していただいているです。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"平塚ゆうゆうプラザ、ゆうゆうプラザのところですが、ゆうゆうプラザの利用率は何を差しているのか教えてほしいと求めました。地域ミニデイの利用率がどうなっているのかというのは、この中には出ていないと思うのですが、その辺が分かったら教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"例えば事業者の管理者だったり、担当者だったり、そういった対象者ごとの定期的な会議を開催しております。正にこれが会議の重要なテーマの１つでありますので、逆に、そういう場として活用させていただいているところです。こちらは貸室の利用率になっておりまして、地域ミニデイもその貸室の中で枠をとらせてもらって実施しているという状況になっております。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"お互いに学び合いながらよりよくしていくということでの交流をされているということで確認していいかということをあとでお願いしたいと思います。私はその利用実績を、ぜひこの中にそういう形で入れていただけたらというふうに思いますが、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長、菅野高齢者地域支援課長","answer":"そういった事例を横に展開させていく、そういう場としても活用しています。研修等も随時、１つのところでやるのではなく、例えば合同でやるとか、そういった取組みも進めさせていただいているところです。 モニタリング・評価の目的に沿って項目立てて記載していますので、この一事業を取出すということにつきましては、検証が必要かと考えています。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでは、モニタリングについては、全く見直しがされないでそのままということになったのかお聞かせほしいと求めました。そしてトータルがどうだったのかという辺りが見えるような形にしていただきたいということで申し上げてきたところですが。","respondent":"宮尾高齢者福祉課長、寺嶋福祉計画課長、松山障害者福祉課長","answer":"外部委員は、本日ご報告申し上げているこちらのモニタリングに関しては、まだ外部委員が入るモニタリングの前の段階の資料となっているところです。… 今少し、言い間違いがありましたが、福祉部所管のものにつきましても選定の中に外部委員に入っていただいております。… 令和元年度のところですが、生活訓練が６８.２％、一番下の数字が生活訓練。それから、機能訓練が２９.８％、生活介護が７８.３％という形で……。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"引き続き、ぜひそういうふうに全体像が見えるような形でのご検討をよろしくお願いしたいと思います。４月からと言っても、それとも同じような状況が続いているのか、そこら辺のところだけ教えていただけますか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"現在の状況ですが、相談については件数としてそんなに大きく変わってはいないですが、児童の計画相談を開始いたしました。それから、愛成会が実施している生活介護については、利用者数が増えてきております。 就労継続支援Ｂ型については変わりありません。定員の変化はございません。","id":"exchange-066"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"就労Ｂはかなり、１６.２％という令和元年度の実績ですけれど、この１０名に対して１６.２％というのが今年度も続いている状況なのでしょうか。増える見込みはあるのかということも含めて、分かったら説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"就労継続支援Ｂ型ですが、昨年度２名で、今年も、現在まだ２名ですので、稼働率については記載のとおりになっているところです。ちょっと難しい、福祉的支援が必要だという方で事業所を利用したいという希望が今後は出てくるかなというふうに思っております。","id":"exchange-067"},{"speaker":"渡部委員","kind":"質問・要望","question":"これが１年後、去年課題になっていたものがどうなったかというのは、担当課はそれぞれ受けているわけですか。その改善が必要な事項と出しているわけだから、それに対してちゃんと受けているのかどうかというのは心配になる、それはどうなのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"人材確保が難しいとか、なかなか簡単に解決できないものについては、複数年続けて課題として上がってくるということがあります。このタイミングでの報告なので、恐らく、その辺は今後の課題として改めていければと思います。","id":"exchange-068"},{"speaker":"渡部委員","kind":"意見","question":"要は、改善点が出ていたら、その改善がどうなったかということが知りたいといいますか、特に安全面の強化などと書かれてしまうと、「おい、大丈夫か」という話になりますので、その辺をしっかり押さえていらっしゃるならば、それはそれで問題はないので、引き続きとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問","question":"もちろん努力されて増やそうとした部分はあるのかもしれませんが、そういう部分についてお伺いします。そして今年度、人数を増やすためにこれだけの指定管理料を上げてほしいというか、人員を増やすためのそういった交渉とかはされているのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"各法人とヒアリングの機会を設けまして、そこで課題ですとか現状を共有させていただき、今後に向けてということでお話をさせていただいたところです。地域拠点相談支援センターとしては、グローの考えとして、もう少し受けていただきたいということで要望をしています。","id":"exchange-070"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今年度ももう半年たったので、まだ続くわけですから、ぜひその辺は直していただくように意見を言っていただきたいということ。もう１つは、指定管理料の話でということになると思うのですが、その辺は利用者の方と全体で考えていただいて指導してほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"引き続き、運営法人と協議をしていきまして、多くの方がご利用できるように進めていきたいと考えています。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ。これはそもそも１２床あるけれど、令和元年度１８.７％となっていますが、具体的な数字が分かれば説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"多いときだと、１日５名ぐらい受けていらっしゃるところになっております。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"意見","question":"１８.７％だったものが、５０％まではいかないけれど、利用者からも実はお声を聞いています。非常に受けられるようになってきたということでお話を聞いていますので、そういったところもしっかり評価していかなければいけないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"}]},{"id":"topic-07","title":"品川区国民健康保険条例の一部を改正する条例付則に規定する規則で定める日を定める規則の一部改正","agenda":"品川区国民健康保険条例の一部を改正する条例付則に規定する規則で定める日を定める規則の一部改正","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"たしかうちの会派の質問で、傷病手当の対象になった人は１人もいないということだったような気がするのですが、国保で感染した人はいないということなのか尋ねました。","respondent":"池田国保医療年金課長","answer":"実際に支給をしたのは１件ということで、不支給が２件。は書類に不備がございまして、現在、処理中になっているところです。","id":"exchange-074"}]},{"id":"topic-08","title":"ロタウイルスワクチン定期接種の開始","agenda":"ロタウイルスワクチン定期接種の開始","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"どういう負担になるのですか。お伺いいたします。","respondent":"鷹箸保健予防課長","answer":"現在につきましては、その７,０００円全額ではなくて、ワクチン接種にかかる費用の一部を区のほうで助成させていただいている形になります。全て区の持ち出しになっております。","id":"exchange-075"},{"speaker":"鈴木（博）委員長","kind":"質問・要望","question":"要望があるのですが、小児科医の間でどうしたらいいのだということで問題になっていますが、ぜひ品川区では救済措置の検討をお願いしたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今まで１回７,０００円で１人２回までの助成額が品川区のほうで出ていたと思うのですが、これで年間何人くらいの方がワクチンを受けられていたのか。実際は医療機関によって多少違うのかもしれないですが、自己負担はどれぐらいあったのかということも分かったら教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"８９.８％とか９１.９％ということで、おおむね９割の方がこの助成を１回目も２回目も受けていらっしゃいます。例えば７,０００円自己負担をお願いした場合、２回で済むロタリックスの場合と同じだけ自己負担、大体半額助成ぐらいな形です。","id":"exchange-077"},{"speaker":"西村委員","kind":"質問","question":"１点だけすみません。２回接種か３回接種かは、区民の方がご自分で選ぶような感じか尋ねました。","respondent":"鷹箸保健予防課長","answer":"医療機関のほうでどちらのワクチンをされるかということは大体決めていらっしゃいますので、かかりつけの先生が選ばれているワクチンを、かかりつけの先生のところに行って受ける、そういう形になると思います。","id":"exchange-078"},{"speaker":"あくつ委員","kind":"確認","question":"それと、高齢者のほうは間に合わなかったので、２回送るというお話、１回でいいのですか、中に同封されているということでいいのですね。２,５００円と書いてあるけれど、無料で受けられますよというものが同封されているということで確認させていただいてよろしいか尋ねました。","respondent":"鷹箸保健予防課長","answer":"ただ、国の方針がありますので、併せてそれをお知らせさせていただいたということは、お子さんに対してのご質問の答えです。この方針が出たのがぎりぎりだったので、自己負担をとらないでいただきたい、そこの間違いはないようにと考えているところになります。","id":"exchange-079"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それぞれ子どもの場合と高齢者の場合のインフルエンザの接種率を教えていただきたいのと、今回、実施になったということなのでしょうか。その財源のことについても説明を求めました。","respondent":"鷹箸保健予防課長","answer":"２番目のご質問の自己負担分を助成する費用の財源ですが、東京都からを考えておりますが、１０月に入ってから確実になるということです。","id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3578#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":92429,"voices":235}},{"id":"r02-20200924-8","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"建設委員会","time":"午前１０時００分～午後 １時３８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件整理しています。","topics":[{"id":"topic-01","title":"会議の運営上、順番を変更して、初めに、(4)令和元年度指定管理者による管理に対するモニタリング・評価","agenda":"会議の運営上、順番を変更して、初めに、(4)令和元年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"２件ともなのですが、この総括シートの中で示しているのがなぜなのかなということを率直に思いましたので、伺いたいと思います。令和元年度で管理運営委託料が上がって、使用料が下がっているという状況になっておりますので、そこの理由を伺いたいと思います。","respondent":"森住宅課長","answer":"区の方針に基づきまして、ＬＥＤ化等の対応をしているところでございまして、多少。区営住宅のほうは下がっているですが、基本的には、そのものが平成３０年度と比べて多少下がってきたというところかなというふうに考えています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"確認","question":"そうすると、どうなると評価が高いというか、回数が多いほうが評価が高いということになるのでしょうか。そこの確認と、指定管理者が負担をしなければならないということになってしまうということなのか、そこの仕組みを伺いたいと思います。","respondent":"森住宅課長","answer":"滞納者１件あたりの対応回数についてですが、これは回数が多いからといっていいかという話ではないのかなというふうには考えております。緊急対応といたしまして、一定金額、支払いをしています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"最後に、職員の方、東急コミュニティーのほうは常勤職員３名というところでやっていらっしゃると。品川宅建管理センターのほうは常勤職員３名、管理主任が４名ということで、そこを伺いたいと思います。","respondent":"森住宅課長","answer":"当然、区営住宅などでは高齢者も多いことから、基本的には対応も少し東急コミュニティーよりは多いのかなというふうには考えているところです。そういった部分と、本社機能と連携をしながら、こちらの品川区については３名の常勤職員ということでやらせていただいているです。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"バイクの当日利用率のところが１００％を超えているのですが、これはどういうことなのかということでお聞きしたいと思います。それと、裏面の３のところで、アンケートを行っているということで、そのアンケート結果がどのように生かされているのか、伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"２点目の、２３か所ありますので、それぞれ異なった部分が出てきたです。それぞれ、先ほどもご説明させていただきましたように、サービスの向上に努めていくというようなところに資するように役立てているところです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"整理整頓の話は１つありましたけれども、こうやって改善されましたということとかがあったらご紹介いただけたらというふうに思います。先ほど、統括責任者のお話もありましたけれども、２３か所でどのように何人の方があたっていらっしゃるのか、そこを伺いたいと思います。","respondent":"川口交通安全担当課長","answer":"最低でも４０ｃｍから６０ｃｍの寸法が欲しいというような意見・要望があった場合には、また、そういう要望があれば細かい対応もしています。２点目の体制なのですけれども、それぞれの場長、各自転車等駐車場を管理している者に対して指示をしています。","id":"exchange-005"},{"speaker":"のだて委員","kind":"確認","question":"そういった体制のところが、この整理整頓を小まめにやっていくということにも反映していくというふうに思います。そこは、きちんと確認できるような体制にしていくということが必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"支払いシステムについて伺いたいのですけれども、マスコミには、報道等には出ているのです。非常に使いこなす世代になってきていると思いますけれども、そこのところはどのように展望があるのか、説明を求めました。","respondent":"川口交通安全担当課長","answer":"支払いをしているのですけれども、ここを、いわゆる交通系のＩＣカードのようなものでワンタッチで支払いができないかという希望等がございました。今後、実現可能性について検討してまいりたいというふうに、今のところ考えているところです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"これは倍くらい、もっと、３倍のところもありますよね。結構いい収益なのかななどと思っているのですけれども、その考え方はいかがか尋ねました。","respondent":"森住宅課長","answer":"区のほうで平成２９年度に長寿命化計画を立てまして、外壁の補修であったりというような計画を立てていて、それに基づきながらやっているです。区民住宅のほうは多少、それぞれの使用者の使用料として適正なものをいただいているというふうに考えております。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問","question":"計画的なところでしているのだろうなということで、平成２９年度のところでそれをいろいろ考えているというところでは、何となく動きが分かりました。大分きちんとされているとは思いますけれども、その辺も含めてのこの改善の取組なのだろうなと思いますが、その辺はいかがか尋ねました。","respondent":"川口交通安全担当課長","answer":"指定管理者の責任者を通じて、シルバー人材センターの管理の方に要望をお伝えして、その内容を伝えて指導していくという形をとっています。区に対しても、その辺のところは、指定管理者と連携を密にしながら改善に資するように実施をしています。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"大体、常時１人か２人いらっしゃるのですけれども、非常にサービスがいいのですよね。「番号は何番ですか」とかと言ってくれたりして、サービス向上を図ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"令和２年１１月都営住宅入居者募集","agenda":"令和２年１１月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"都営住宅の募集ということですが、今年に入っての募集数と募集倍率を教えていただけたらと思います。","respondent":"森住宅課長","answer":"今年度になりますと、５月に募集されたものが公表されております。区内の倍率といたしましては２５.３倍、都内全体で見ますと１４.２倍、都内で５.１倍ということになってあります。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"区内では２５倍ということで、この都営住宅を含め、公営住宅が求められているということだと思います。ですので、ぜひ、この都営住宅の増設を都に要望すべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"都の都営住宅の方針といたしましては、都営住宅の増設というところについては、都のほうでの方針ではないのかなというふうに考えています。区といたしましては、その都の方針にそれぞれ従って、都営住宅等の募集等していきたいというふうに考えています。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"多摩部では空きがあるというお話でしたが、やはり都心に多くの方が住んでいるということだと思うのです。やはり需要があるのですから、区もそこの方針を改めて、増設を求めていっていただきたいということで要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"}]},{"id":"topic-03","title":"航空機騒音の短期的な測定の実施","agenda":"航空機騒音の短期的な測定の実施","exchanges":[{"speaker":"田中委員","kind":"意見","question":"短期的な測定が実施されるということなのですけれども、なぜ短期的なのかというところ。ほかに、五反田文化センター以外の候補があったのかなということを、もしご存じであったら報告していただければと思うのですがとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"国のほうは本格実施開始以降、区内で言いますと３か所、測定局を設置して把握をしたいと。Ａルートのほうの五反田方面について設置がされていないというところで、国からは、その辺を中心に区の施設を検討したというふうには聞いてあります。","id":"exchange-014"},{"speaker":"田中委員","kind":"意見","question":"この短期間で２週間にわたって測定ということなのですけれども、その２週間を過ぎた後には、２点お知らせくださいとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"先ほど設置は完了し、今後というお話をさせていただきましたが、設置は完了していまして、９月２３日から１０月６日の間の２週間でいうところです。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"たしか一般質問でお答えがあったと思うのですけれども、それほど時間はかからずに公表されるのかといったところも確認させてほしいと求めました。区に対する羽田新ルートに関する問い合わせ状況についてもお知らせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"それから、固定化回避に向けた検討会、１回目が行われてありますが、２回目の実施時期、これは前回、委員のほうから重ねて国のほうにと。当然、区としても開催時期について、今のところ２回目の開催予定時期がいつだというところの回答はいただいていないです。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"今回のこの短期的な測定の実施について、区としてはどのように捉えているのかというところ。区としてどのように求めていくのか、何を求めているのか、ということをお知らせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"短期測定の実施についての区の受け止めですが、あるいは設置場所、しっかりやっていただきたいなです。固定化回避に向けた検討会について、さまざまな技術的な視点で検討を加えながら、その途中の検討状況については注視していますが。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"検討会のスケジュールを確認してほしいと、区としても要望すべきということを訴えているのですけれども、区として求めていってほしいと思うのです。要望書であったり、きちんと書面での、そういう区としての申し入れといった形ではしていくのかというところを確認したいと求めました。","respondent":"鈴木都市計画課長","answer":"当委員会でもご説明しましたが、５月に区長が国土交通省を訪問しまして、この件については強く要望して実現した結果です。その５月の要望でも「具体的に」という文言もしっかり入れしていますので、今、出すということは考えてございません。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"区としての強い要望を国が聞き取って検討会が実現されたということでしたので、区としてもっと本当に求めていくべきだと思うのですけれども、そのところに関してどうお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"この検討会の進め方につきましては、繰り返しになりますが、大臣自ら会見の場で、年度末にはしっかりと取りまとめてお示しすると。年度末の公表結果を待ちたいですが、その途中、途中の状況は、担当者レベルでは当然ながらしっかり求めていきたいところは変わらないです。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"区に届く問い合わせの状況の報告もしてほしいですし、何を要望したというところも報告してほしいですし、きちんと報告をしてほしいと思います。私たち生活者ネットワークは全くそのように思っていなくて、区として、きちんと白紙撤回を求めてほしいということは重ねて要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"どういうところで、それを継続的に、やはり固定で見ていかなければいけないということにもつながってくるのではないかというふうに思うのです。区と国との協議の中で、どういった話し合いがあったのか伺えたらと思います。","respondent":"鈴木都市計画課長","answer":"本格実施・運用開始前に、この本格実施・運用に向けての測定局設置については、特に数については意見を伝えてあります。４か所と測定局を設置していただきたいという要望は、丁寧な説明の観点の中ではありがたい、しっかりやっていただきたいという受け止めです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"増設も要望してほしいと求めましたし、あと１回、２回の検討会でまとまってしまうのかなという危惧があるわけなのです。区のほうで要望していくべきではないかと、ぜひ要望していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"判断的なところは国のほうでしっかり検討していただいて、やるべきことはやっていただくというのが、区としての考えです。検討会について、どういう内容で進めるかについては、会の主催である国がしっかりと検討を行って考えるべきであって。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"すみません。路上なのか、それとも屋上なのか、その場所についてお知らせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"建物の屋上だと思います。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"自民党品川総支部で固定化回避の要望書は出して、来年３月、年度末は期待しています。現実どうだったかというのも、ぜひ分かるようにしていっていただきたいなと思いますので、お願いだけにしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"「夏季、冬季にそれぞれ１週間の測定を実施します」という、この冬季というのは何月頃とかというのは出ていましたでしょうか。お願いします。","respondent":"鈴木都市計画課長","answer":"夏季２週間、北風については「夏季、冬季にそれぞれ１週間の測定を実施」。江戸川区のほうには発生するルートがありますので、このルートの測定については、冬季１週間程度行われるのではないかという理解です。","id":"exchange-025"},{"speaker":"田中委員","kind":"確認","question":"でも、それでもやはり品川区の上空は飛ばないからということで測定はストップしてしまうのですか。その辺の確認はしてほしいのですけれども、どうなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"品川区内には固定局が３局ございまして、五反田文化センターでも短期で設置するわけですが、国のほうは行っていくと。区としても、当然、それでいいのではないかという受け止めです。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"今、八潮で、北風ルートのときにもうるさく聞こえてくるということがあるので、それについても測定の結果がもし出せるならば、出してほしいなと思っているのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"圧倒的に影響が多いのは、上空を飛ぶ南風のときのＡとＣですので、この数字を公表していただくと。この数字の音を実際に見ていただくということで、十分ではないか、まさに、これが大事ではないかというふうに考えてあります。","id":"exchange-027"},{"speaker":"大沢委員","kind":"確認","question":"１月、２月という話が出たのですけれども、季節の「季」と期間の「期」と２つあるわけではないですか。ここのところを確認です。","respondent":"鈴木都市計画課長","answer":"もう９月末ということで、国のほうは、そういう形でのこの資料への表現ということになっているかと思います。〔「この季は、季節の季だよね」と呼ぶ者あり〕 季節の。そのような考えです。","id":"exchange-028"}]},{"id":"topic-04","title":"立会川緑道整備工事","agenda":"立会川緑道整備工事","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"整備しなければいけないということがあるので、あきらめる部分は往々にしてあるのですけれども、そういうものも今後生かしていただきたいなと。子どもたちが自然に触れ合えるような、そういう雰囲気があると助かるなという感じはあるのですけれども、いかがか尋ねました。","respondent":"溝口道路課長","answer":"委員ご指摘のように、これまでふたかけして、地域の方々に親しまれてきた緑道であるというのは、私どもも十分認識しております。総合的に見て、やはりまずは原点にあります道路というところに重点を置いて整備をしていきたいというふうに考えているところです。","id":"exchange-029"},{"speaker":"西本委員","kind":"確認","question":"１点、緊急車両が通行できるということなのですけれども、これは通常は止めるということでよろしいのでしょうか。確認します。","respondent":"溝口道路課長","answer":"通常は車止め等を設置して、そういったものを設置することによって、通常は車が入れないような形になります。緊急時には、中まで入って消防活動にあたれたりとか、そういった緊急活動が行えるような道路にしていくということで考えております。","id":"exchange-030"},{"speaker":"西本委員","kind":"確認","question":"１つ確認を忘れました。これは、これだと変わらないのですけれども、ここはやはり整備はもう難しいのか尋ねました。","respondent":"溝口道路課長","answer":"まず１つは、もう既に民地側の高さが決まっているということで、なかなか道路の高さが変えられない。ですので、今回、やむを得ず、こういった段差がついた形での整備になっております。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"２ｍですから、それほど行き来ができないのですよね。どういう自転車の使い方がいいのか、分けられれば一番いいのかななどと思うのですけれども、その辺の工夫はいかがか尋ねました。","respondent":"溝口道路課長","answer":"自転車の、青色のカラー表示はしていこうと思っています。初めてここを正式に通すような形になりますので、利用形態を見ながら、必要な対策というのは今後もとっていきたいというふうに考えているところです。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問・要望","question":"お散歩コースだったりとか、やはり楽しめる場所になっているので、話をしてほしいと求めました。この辺のところが、こんなに減ってしまうのかと、断面図を見て驚いてしまったので、この辺りをお知らせいただければ。","respondent":"溝口道路課長","answer":"今回の整備計画・方針、説明会などというのを重ねながら来ているところですので、この形でできれば整備をしていきたいというふうに思っています。四季を楽しみながら歩いていただける、そういった工夫は、今回整備の中でしていきたいというふうに考えているところです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、今回、４年間で整備していくということで、１工区から４工区とあります。両側から整備されていくということになっていますけれども、なぜそういう進め方になるのかということについて説明を求めました。","respondent":"溝口道路課長","answer":"１工区、前年度実施したところにつきましては、まず最初に荏原町駅側のほうを。そういった中で、工区的にはいろいろ分かれてはきますが、順を追って整備をしていきたいというふうに考えているところです。","id":"exchange-034"}]},{"id":"topic-05","title":"第二戸越幹線整備工事（北品川立坑）","agenda":"第二戸越幹線整備工事（北品川立坑）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"２番目の、受入基準を満たさなかった泥土処分の受入施設を追加するというのはよく分からなかったので伺いたいと思います。そして、３番目の、工事現場出入口の形状がなぜ変更になったのかというところでご説明ほしいと求めました。","respondent":"松本河川下水道課長","answer":"３番目の出入口ですが、出入りの方法を改めて検討し、舗装の構造や安全の内容に変更が生じたためです。立坑の構造につきましても、先ほどご説明しましたように、地下水位が変わってあります。","id":"exchange-035"},{"speaker":"のだて委員","kind":"意見","question":"泥土の受入れのところで、再資源化、受入基準を満たさなかった分を、ほかの処理施設に受入れていくということなのですよね。敷地内で溜めておくところを作るということなのか、その辺がよく分からなかったので、もう一度説明いただけますかとの意見を述べました。","respondent":"松本河川下水道課長","answer":"当初、想定していましたのは、外部の施設で処理をする予定でございました。そこの受入基準を満たさなかった土壌がございましたので、その土を、今度、受入れられる施設に切り替えたということで変更が生じたものです。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"それとも、別々だったのでしょうか。それとも、下流部はまた別というふうな感覚なのか、この辺の工事の概要というのを教えてほしいのですけれども。","respondent":"松本河川下水道課長","answer":"それに合わせて、ご説明しました下流部の立坑を、今、構築しています。それに関わる経費といたしまして、４０万円ほど、今回変更させていただいているところです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"目黒川の水位を下げるというか、抜け道として、この第二戸越幹線整備という形になっていると思うのですけれども、そういう形でいいのですよね。今、最終的には上流と下流が合流するという形で、これによって目黒川の氾濫が大分減るというふうな想定で設計されているということか尋ねました。","respondent":"松本河川下水道課長","answer":"今回のこの第二戸越幹線工事というものは、目黒川から水をとるというものではなくて、平塚地区であるとか、そちらの雨を目黒川に流すための下水道工事です。","id":"exchange-038"},{"speaker":"石田（秀）委員","kind":"確認","question":"なぜこのようなことを聞くかというと、一緒に一体で公園整備をするではないですか。それだけ確認したいと求めました。","respondent":"松本河川下水道課長","answer":"こちらの立坑の跡地ですが、将来的には、管理をするために、人が入るためのマンホールの蓋というものは必ずできる予定です。検討していますが、もしかすると、そういった空気が抜けるための施設等が地上部に出る可能性はあります。","id":"exchange-039"},{"speaker":"石田（秀）委員","kind":"質問","question":"そのマンホールとか空気口というのは、もう公園課と打ち合わせをして、例えば、一番端っこの邪魔にならないようなところにしようとか、そういう話というのは、もちろんやっていらっしゃると思うのだけれども、我々はそういう感覚でいていいのか尋ねました。","respondent":"松本河川下水道課長","answer":"もちろん、ここは公園用地ということで考えてありますので、そういった施設を邪魔にならないところに設置したいということで、これから具体的な検討に入っていきたいというふうに考えてあります。","id":"exchange-040"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"いろいろ防災行政無線を使っていると思うのですけれども、非常に聞きやすかったのはなぜだろうと、非常に不思議だったのです。それとも地域がそうなのか、何かそこは変わっているのか尋ねました。","respondent":"大森災害対策担当課長","answer":"区としての認識ですと、聞きにくかったというご意見というのは、区民の皆様からはそんなには受けていない状況ではあります。回答になっていないかもしれないのですが、そのような形です。","id":"exchange-041"},{"speaker":"西本委員","kind":"意見","question":"通常、聞きにくいと、すごく言われるので、いや、これだったらいいんじゃないのと思いました。いい方向にあるのだったならば、そちらのほうが聞きやすいのかななどと思ったので、感想を言わせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4302#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":34186,"voices":132}},{"id":"r02-20200924-9","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"文教委員会","time":"午前１０時００分～午後 ３時０８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件整理しています。","topics":[{"id":"topic-01","title":"旧三井文庫第二書庫の国登録有形文化財登録","agenda":"旧三井文庫第二書庫の国登録有形文化財登録","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"やはり区民が触れられるように方策を何らか取っていただきたいと思うのですけれども、そのような工夫というのをしていただきたいのですけれども、いかがか尋ねました。","respondent":"有馬庶務課長","answer":"文化財には指定文化財と登録文化財と２種類ございまして、変更ですとか、かなり制約が出ます。文化財週間というものが１１月にはありますので、そのようなことも考えられるということで、検討しています。","id":"exchange-001"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、品川区内に今、指定文化財、登録文化財、今回のものを入れて、それぞれ何件になるのか尋ねました。","respondent":"有馬庶務課長","answer":"いろいろな工芸品とか絵画とか天然記念物とか、全部含めて２０件です。それから登録文化財については、今回の旧三井文庫を合わせて５件ということになります。","id":"exchange-002"},{"speaker":"あべ委員","kind":"質問","question":"今回の登録も教育委員会でいろいろとご尽力されたということで、めでたくと言ったらいいのでしょうか、無事に運んでよかったと思います。今後考えていったらいいのではないかとも感じるのですけれども、今、教育委員会はどのような形で考えていらっしゃるのか尋ねました。","respondent":"有馬庶務課長","answer":"古民家が１つなったのですけれど、その辺は兼ね合いを考えながら、コースなどは考えていきたいと思います。文化財をＰＲすることは、いろいろと計画を練っていきたいと考えています。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問・要望","question":"でもその分、一つ一つが、なかなか地域にも区外の方々にも認識されていない部分がまだまだ多いのではないかと思います。文化財あるいは文化について区民にもっと親しんでもらうという機会を、年３回と言わず増やしてほしいと求めましたので、要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"そこに子どもたちが当然行くでしょうから、当然お考えになられると思うのですけれど、ではお考えを。","respondent":"有馬庶務課長","answer":"せっかくの場ですので、我々の所管している大森貝塚も併せて、子どもたちは品川歴史館にも行っていますので、それと併せて、ここもこういう文化的な価値があるのだということは、子どもたちにも紹介していきたいと考えております。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問・要望","question":"今回の旧三井文庫を入れて５件というお話でしたが、まずホームページに記載するなどのことをやっていただきたいと思っているのですが、お考えはいかがか尋ねました。","respondent":"有馬庶務課長","answer":"ホームページの掲載については、所有者様との同意を得られればというところで進めていけたらと考えています。今回の三井文庫は区所有ということで、区所有では初めてですので、これは今後、ホームページに上げていきたいと考えています。","id":"exchange-006"}]},{"id":"topic-02","title":"令和元年度保護者アンケートおよび児童・生徒アンケートの結果","agenda":"令和元年度保護者アンケートおよび児童・生徒アンケートの結果","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"幾つかお伺いしたいのですが、この原因はどういうふうに分析しているのか、まず１点お伺いしたいと思います。何というのでしょう、具体的にどういう活用を求めているのかというのを、もう少し伺わせていただきたいというのが３点目です。","respondent":"工藤指導課長","answer":"最初の段階は１年生だと思われるのですが、お考えがどうなのかというのが分かるというところでは、分けさせて集計をしているところではあります。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"続けて質問しますけれども、児童・生徒には聞いていないのですけれども、これはなぜでしょうか。むしろ主役である子ども自身の意見を聞くべきなのではないかと単純に思ってしまったのですが、そちらについてはいかがか尋ねました。","respondent":"工藤指導課長","answer":"それをよりよい教育活動にするために必要なものであると考えていますので、課題はやはり、より成果につながるように見直しをしていく。先ほど来説明しているように、結果として学校生活での満足度というのは、様々な設問項目で取れていると把握はしています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"どう考えているのですかと質問したのですけれど、今後、要因分析が詳細にできるような検討はしていきたいというご答弁があったのです。その後の検討の進捗といいますか、今後、その後どうなったのかというのをお伺いしたいというのが質問です。","respondent":"工藤指導課長","answer":"本アンケートの概要版でもご説明した、「社会の様々な人々の個性を尊重し、認め合いながら関わることができる」という項目があります。それで、全体として肯定的な回答が、４年生の段階で９４.４％だったのが、９年生で９４.２％になっている。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり子どもを取り巻く環境全体というのですか、子どもの権利委員会などからも指摘され続けているわけですから、要望としましては。指摘していきたいと思いますが、本日はそのような問題意識を述べさせていただいて終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問","question":"この調査なのですけれども、いつ頃から実施されているのかということと、内容は多分、ほぼ、割と似た内容で、プラス、その時々の課題も少し入れるというような構造になっているかと思うのですけれど、そこの概要を説明するよう求めました。","respondent":"工藤指導課長","answer":"保護者アンケートにつきましては平成２４年度から、児童・生徒アンケートにつきましては平成２５年度から実施しているものです。項目を入れ替えたりもありましたけれども、よりそれを推進したいと思って、今回精査したというところがあります。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問","question":"特に７年生以上のカリキュラム、教育内容、まだまだこれはニーズに合っていない部分があるのではないかというような見方をしたことがあるかどうか。やはり１０年単位で推移を見ていくというようなこともあってもいいのかと思うのですけど、そういうこともされていますか尋ねました。","respondent":"工藤指導課長","answer":"ただ、全体として肯定的な回答がそれほど下がらないというところは、ご理解をいただいているところかと思っているところです。３年間経つと、これまで１回で行っていたものを、そういった分析も含めて今後はしていきたいと考えているところです。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"少し事務量の見直しをということだと思うのですが、今年からＧＩＧＡスクールで、１人１台のパソコンというのが配備されることになります。いきなり１００％にはならなくても、学校現場にとっても負担の減になるのではないかと思いますけど、その辺のご見解はいかがか尋ねました。","respondent":"工藤指導課長","answer":"私どもも、回答率が非常に高いところがありますが、１００％にならないというところはあります。それは、様々な方法を検討しているところで、その取り方についてもまた様々検討しながら進めたいと考えているところではあります。","id":"exchange-013"},{"speaker":"筒井委員","kind":"質問","question":"１６.１％、児童・生徒に至っては１９％と高いのですけれど、どういった理由なのか。理由のさらなる詳細というか内訳が分かりましたら説明を求めました。","respondent":"工藤指導課長","answer":"生徒の１９％の中がどういうところかというのは把握していないところはあるのですけれども、そういう意味では、やはり興味があって調べる。そういったところが、これまでの実際に入学する生徒などの状況から把握しているところというのは、以上のようなことです。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"公立の学校で、全国大会にも出場されているということなので、そういったことも要因なのかとは思っております。１桁から、このように２桁になった理由というのは、どう分析されていますか尋ねました。","respondent":"工藤指導課長","answer":"その理由については、私どもは把握していないところではありますけれども、そういうところが１点あります。ですので、この１９％が単純に昨年度と比較してということではないというところをご理解いただければと思います。","id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"ちょっと確認なのですけれども、昨年の６番ですか、話合いで意見を言える。今回のところなのですけれど、５ページというのですか、（４）で、２年生ですと、「人の目を見て話をしたり、聞いたりすることができる。","respondent":"工藤指導課長","answer":"さらに、自治的な活動の領域であるとか文化創造の領域もありますので、そういったバランスを考えながら今後さらに検討したいと思います。これは先ほど来、それがやはり９年生にかけて上がってくる傾向が、成果として見られているのではないかとは考えているところです。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"これから、そういった方々と対話をしてということがすごく求められてくると思いますので、その辺りも引き続き注力していただきたいと考えています。特に７年生から９年生ですか、ぜひ伝え続けていただきたいと思うのですけれども、一言お願いします。","respondent":"工藤指導課長","answer":"児童・生徒の成長にとって非常に有効であると私どもは認識していますので、発信するよう、学校については指導してまいりたいと思います。","id":"exchange-017"},{"speaker":"せお委員","kind":"質問","question":"児童・生徒アンケートの（３）ですか、概要にも書かれているのですけれども、「社会の様々な人々の個性を尊重し、認め合いながら関わることができる。」というのは、どのような場面を想定して質問されているのか、どのような目的などがあって質問されているのかというのを説明するよう求めました。","respondent":"工藤指導課長","answer":"やはり自分ができることを考えた上で、その方に、「何かお困りですか」と声をかけることができるような児童・生徒に育ってほしい。そういう意味では、「社会の様々な人々の」というのは、そういった意味でつけさせていただいているところがあります。","id":"exchange-018"},{"speaker":"せお委員","kind":"質問","question":"そうすると、それを教える学校生活、教えていくような場面というか、そういったものというのは今現在、どのようなところで教えているのか尋ねました。","respondent":"工藤指導課長","answer":"個性を尊重するという教育は全教育活動の中で行うべきであると考えていますので、そういった中、全般と私どもは捉えているところはあります。個々の事象というのはあるとは思いますけれども、全ての場面に必要であると認識しています。","id":"exchange-019"},{"speaker":"せお委員","kind":"質問・要望","question":"パラリンピックに興味がありますかというので、なかなか難しいところではあるのですが、少しずつ教育の場面で伝えていってほしいと求めました。以上です。","respondent":"工藤指導課長","answer":"先ほど部活動の件で答弁がありましたが、ちょっと漏れておりました。そういったことも、効果に、選択の際の興味が上がるというところにつながっているというのも考えられると思います。","id":"exchange-020"}]},{"id":"topic-03","title":"令和２年度「秋の読書フェア」","agenda":"令和２年度「秋の読書フェア」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"上のほうはテーマが出ているのですけれど、「秋の子ども読書の日フェア」のテーマがないのはなぜなのかというのが１つ。図書館法第１４条で、住民参加の保障として図書館協議会の設置が求められているということなのですけれども、その辺も説明を求めました。","respondent":"横山品川図書館長","answer":"２点目の、「秋の読書フェア」のテーマの各館の方針につきましては、各図書館で工夫するという仕切りで運営しています。３点目の住民参加につきましては、また指定管理の方の意見を聞きながら話し合いをして進めるような形で、テーマ等の設定をしています。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"中高生をどうするか問題というのがずっとあるかと思うのですが、こういうフェアのときに、ぜひ考えていただきたいと常々思っているのです。一番図書館から離れがちな世代に、どういうアプローチをされているのか、教えていただけますか。","respondent":"横山品川図書館長","answer":"ティーンズの世代の読書離れが非常に問題とされているのを図書館でも認識しておりまして、またＰＲしていこうという活動を進め始めているところです。改めてティーンズという形では打ち出しはされていないのですが、範囲としては入っているというのは認識して進めております。","id":"exchange-022"},{"speaker":"あべ委員","kind":"意見","question":"そうした新しい試みと同時に、こうしたルーチンの定期的な活動の中にもやはり入れ込んでいってほしいと求めました。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"横山委員","kind":"確認","question":"細かいところで申し訳ないのですけれど、周知方法についてなのですが確認させてください。その辺りの状況と、「秋の子ども読書の日フェア」のほうは、統合チラシは今回はなしということなのか尋ねました。","respondent":"横山品川図書館長","answer":"逆に図書館で館内チラシであるとかお声がけなどという形でお知らせするほうが効果的という意味で、若干、今までの経緯で周知の仕方が違っているところがあるところです。","id":"exchange-024"}]},{"id":"topic-04","title":"ゆたか図書館の空調設備改修工事","agenda":"ゆたか図書館の空調設備改修工事","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれど、近年、大分出てきていると聞いています。今回の図書館も、空調を使っているとどうしても換気が悪くなりがちだと思うのですけれども、換気可能なタイプかどうか分かりますか。","respondent":"横山品川図書館長","answer":"申し訳ありません。ゆたか図書館では空調を使いながら一定の期間、これからも、実際の自然換気というのは併用しながら運用していきたいと考えています。","id":"exchange-025"},{"speaker":"あべ委員","kind":"意見","question":"今後、情報収集などもしながら、状況をお教えほしいと求めました。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]},{"id":"topic-05","title":"令和元年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和元年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"Ａ・Ｂは微減というか、ちょっと減っているのですけど、Ｃグループは結構増えている感じなのです。はＡ・Ｂのほうで何か改築や図書館の改修があって減ってしまったのか、何か理由が分かれば教えてほしいと求めました。","respondent":"横山品川図書館長","answer":"移転に伴いまして、新しい層を開拓して、単純に読書人口が大崎地域で増えているという傾向もあります。これは全体に減っているわけではなく、図書館の利用の仕方が多様化しているという状況を表しているものと考えております。","id":"exchange-027"},{"speaker":"たけうち委員","kind":"質問・要望","question":"地域やイベントなど、一方で３番のところを見ると、区民ニーズの把握と図書館利用の促進を図っていくことが求められている」。その辺をちょっと伺いたいです。","respondent":"横山品川図書館長","answer":"Ｃグループ、病院の先生に来ていただいて講演会をしていただき、その関連の本も見ていただくとかという交流をさせていただいています。図書館全体としてもそれをバックアップし、より進めていこうと、図書館全体で取り組もうとしています。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"意見","question":"それぞれのグループのよさもまた見ながら、共有しながら推進してもらえればと思いますので、よろしくお願いします。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"あべ委員","kind":"質問","question":"これを拝見した中で気になったのが、ＡグループとＣグループで、「改善が必要とされた原因の分析および対応方針」のところで、有資格者の配置について引き続き努力するというのは、Ａ・Ｂ・ＣのうちＡとＣで有資格者の配置が必ずしも予定どおりできていないことを意味するのか尋ねました。","respondent":"横山品川図書館長","answer":"７割に近い有資格者数を持っておりますので、より司書の方を中心に進めていただきたいという意味合いを込めて、こういうふうにしています。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"Ｂで７割。お金の面も含めて、内容的に令和２年度、どういう見直しがかけられているのか説明を求めました。","respondent":"横山品川図書館長","answer":"ただ、開館した後のコロナに対応できるような動線であるとかしつらえであるとかレイアウト等も、事業者と職員が一体になって考えておりました。削減されて、みんなそれぞれの新しい業務に取り組んで、むしろ負荷がかかって申し訳ないと思っているようなところです。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"これまでなかったような仕事も出てくる中で、ステイホーム中の大きな心の柱になったのではないかと、利用者の方々からも伺っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"それはどういう対応をされるのかというのと、管理委託料などが記載されているのですが、そちらにはないというのは何でなのかというのをお伺いしたいと思います。","respondent":"横山品川図書館長","answer":"運営５年間のうちの４年目という形になっておりますので、３年目ですので、外部監査が予定されております。入館者数や貸出数などの動きのほうが、皆様に実績を知っていただく指標として適切だろうという形で、若干違うものを載せしています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"それと裏面の３番ですか、３年以内の離職率などについて、品川区としては現在把握しているのでしょうか。以上、３点伺います。","respondent":"横山品川図書館長","answer":"Ａグループ「総括」に書いてあります年間計画に基づいた継続的な実施という形については、後で回収したりというような出入りがあったりするので。中まで把握というか、提案に基づいて事業をお願いしているという形ですので、そこまでの報告は今現在求めていません。","id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"その辺は４年目にという話もありますので、また関わってくるのかもしれないのですけれど、やはり専門職ですよね。そういった状況については報告を求めて把握すべきだと思うのですけれど、ぜひお願いしたいのですが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"包括的に日々、事業者と連絡を取り合う中でお伝えしていますし、それについて従事者もお答えいただいているところであります。長く勤めていただいている、安心して勤めていただいているという状況を、報告書で確認させていただいているところです。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"定期的に運営されているかというのをチェックするためにモニタリングシートを出してもらっているわけですから、ぜひ委員会に報告していただきたい。やはり職種がころころ変わっては積み上げられないわけですから、再び最後にお伺いして質問を終わりますけれど、いかがか尋ねました。","respondent":"齋藤教育次長","answer":"総括シートは企画部で調整しております。どのような形で出すかの様式については企画部で統一的に調整しておりますので、委員の今のお申し出につきましては、企画部にお伝えします。","id":"exchange-036"},{"speaker":"横山委員","kind":"質問","question":"５ページの、Ｃグループの部分なのですけれども、積極的に評価したことのところで、雑誌スポンサー制度ですとか、またビブリオバトルというところ、課題に積極的に取り組んでいるということなのですが、令和元年度の実施の状況と、現在の状況を教えていただけたらと思います。","respondent":"横山品川図書館長","answer":"商業支援施設等がありますので、こちらにご協力いただきながら、宣伝効果を図書館で発揮できるように協力関係をつくりたいと努力しています。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"課題に積極的に取り組んでいただいているということで、その姿勢というか、努力していただいているということはすばらしいと思っています。小さな失敗みたいなものを繰り返し、それを改善するという形で成果に結びつけていただきたいと思うのですけれども、その辺りはいかがか尋ねました。","respondent":"横山品川図書館長","answer":"三回、打合せをしまして、新しい意見を出して取組みをしようという活動を取り続けているところです。これからも委員のご意見を励みに進めさせていただきたいと考えています。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問","question":"司書の資格なのですけれども、やはり一定の資格を得る、あるいはそのための勉強をするというのもとても大切なことだと考えています。現場で働きながら、品川区の図書館では、司書の資格取得のための何かバックアップの制度みたいなものというのは持っていらっしゃるのか尋ねました。","respondent":"横山品川図書館長","answer":"ただ、やはり期間がかなりかかるので、勤めてから少し経ってから、そちらのほうにどうだという声がけをしながら進めているです。様々な形で働く場という形なので、資格の取り方についてもそれぞれ対応できるような形でやっているところで、制度としてはそれぞれにあります。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問","question":"先ほどの割合は司書の資格、司書補も入れての数字か尋ねました。","respondent":"横山品川図書館長","answer":"報告されているのは司書の資格です。","id":"exchange-040"},{"speaker":"あべ委員","kind":"意見","question":"事業者と、その辺もご本人の経歴形成の面からも、ぜひ後押ししてほしいと求めました。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"特にファミリー世帯の数が増えたということは、本当にシンプルな疑問なのですけれど、そういったことはあるのか尋ねました。","respondent":"横山品川図書館長","answer":"お迎えの際に子どもを連れてきてという方のご利用も非常に多いので、そういう意味で、ほかのグループよりも目立つような増加になっているところだと思います。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"ただ、Ａグループ、Ｂグループもぜひ工夫して、来館者数などをぜひ伸ばしていっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-06","title":"休憩前に引き続き、文教委員会を再開いたします。 それでは引き続き、(5)令和元年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"休憩前に引き続き、文教委員会を再開いたします。 それでは引き続き、(5)令和元年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"来館者数や事業実施数が継続的に減っているというのは、やはり子ども家庭支援センターへの統合といったものが理由なのでしょうかというのがまず１点。そうだとしたら、その理由は何なのか、伺いたいと思います。","respondent":"崎村子ども家庭支援センター長、三ッ橋子育て応援課長、吉田保育施設調整担当課長","answer":"子育て支援センターでは、日中、フラっと広場の利用者数が約１,０００人ぐらい減っているところです。令和元年度については… 改善が必要な事項ですけれども、個人情報を扱っているため、なお一層のセキュリティの向上が必要だということで改善の理由としております。… 改善が必要とされた点の内容で、キャリアアップ補助金などは今まで使われていなかったのかということなのですけれども、今までも使ってまいりました。","id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"透明性・公平性の確保の点から課題が明らかになったと思うのですけれど、直近の状況というのはどうなっているのかを聞かせてください。直近の事業者交替の、正式には次回、第４回定例会に案件が出てくると思うのですけれど、現在の状況というのはどんな感じか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"９月４日〔同日後刻に「９月３日」と答弁訂正あり〕に指定管理の選定委員会が行われまして、その中で、事業者について、福栄会からの指定管理の申請内容を審査し、また審査委員には外部委員を含めまして、公平性を保つよう審査を行い、今、決定について進めているところです。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"それと、管理運営委託料の内訳を、ざっくりでいいのですけれども教えていただけますでしょうか。そこの２点をお願いします。","respondent":"崎村子ども家庭支援センター長、三ッ橋子育て応援課長","answer":"利用の実人数、利用される回数、お１人当たりの利用回数が減っているというところが原因なのかと捉えております。子育て支援センターでは、丁寧に対応しながら、引き続き子ども家庭支援センターにつないでいただいて。 管理運営費の内訳ですが、人件費、事業費、事務費となっておりまして、一番多いものが人件費で１億２,０００万円程度、それから事業費が……。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問・要望","question":"今後、運営を変えてほしいと求めましたが、いかがでしょうか。そこにはやはり原因があるのではないかと思うのですけれど、そこはどのように捉えていらっしゃいますか尋ねました。","respondent":"三ッ橋子育て応援課長、崎村子ども家庭支援センター長","answer":"状況に応じて、ファミリー・サポート・センター事業というのが非常に子育てをしやすい状況というのがなかなか難しいところが課題と捉えております。… 例えば０歳から２歳までお預かりできるとか、１２歳以上もお預かりできるところがあるとか、そういったこともあります。子育て支援センターで拡充するのか… 平塚ファミリー・サポート・センターにつきましては、光熱水費まで含んでおりますので、その関係があります。","id":"exchange-047"},{"speaker":"あべ委員","kind":"質問・要望","question":"自治法その他、法令に準じない形で手続きを進めるというのは非常によろしくないことですので、そこはぜひ気をつけて進めてほしいと求めました。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"ひがしやつやま保育園のほうはどういう事情で使えるようになったのかとか、もう少しその辺をご説明いただきたいというのと、何に活用することを検討しているのか伺いたいと思います。","respondent":"立木保育課長","answer":"５年間の期間限定というところは変わっておりませんで、それ以降の土地利用ができないということで確認しております。それ以後の土地の活用方法につきましては、私のほうには伝わってきておりませんので、お答えすることができません。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"それ以降の使用はできないと確認したということなのですけれど、それはそれぞれ、どちらに確認をしているものなのか伺いたいと思います。ぜひ１年といわず、さらに永続的に使えるようにしていただきたいのですが、いかがか尋ねました。","respondent":"立木保育課長","answer":"それぞれ、ひがしやつやま保育園のほうも、まちづくり部門、それから企画部に確認しています。それから、まちづくりのことに関しましては私は答える立場にございませんが、そういったところは所管に伝えします。","id":"exchange-050"},{"speaker":"あべ委員","kind":"確認","question":"確認ですけれど、１年足らずになりましたというのは、保護者にはいつ頃お伝えする、あるいはもう既にしているのか。在園の方々は、ご兄弟の関係などもあるので早めにしておいたほうがいいと思うのですけれども、まず保護者への確認について説明を求めました。","respondent":"立木保育課長","answer":"こちらの運営方針につきましてのお知らせは、これから保護者の方に対してお知らせするのと同時に、これから入園を考えているご家庭の方に対してもお知らせを出していく予定です。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"これから入園を考えている方へのお知らせというのは、どういう形で行うのか。それとも、さらに近隣の方などにお知らせするのか、詳しく説明を求めました。","respondent":"立木保育課長","answer":"これから、どちらかの保育園への入園をご希望されるご家庭に関しましては、保育園のご案内等での記載に加えまして、それから入園の希望の方に対しては、通知文でも、手渡しできるものに関しましてはお渡しするような形で、窓口等でもご案内するように考えております。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"何といったらいいのでしょうか、できるだけ、こういう形でない安定的な保育園運営に移行していただきたいと考えています。ぜひ庁内でも働きかけをしていただきたいと思うのですけれど、その辺、お考えはいかがか尋ねました。","respondent":"立木保育課長、若生保育支援課長","answer":"こちらの公設民営の期間限定の園に関しましては、待機児童の部分を何とか緊急的に対策をするという部分での緊急措置というところがございました。子ども・子育て支援事業計画の中でもっとしていくことだと考えていますが… こちらの東品川の周辺ですけれども、今後、来年度開設予定の園が３園、東品川でもあります。当然、こちらの閉園も見越した上で、再開発等を踏まえまして、開園の計画は進めているところです。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問・要望","question":"考え方なのですけれども、やはり保育園の中の子どもたちというのは１つの社会をつくっているわけですから、安定した保育をお願いいたします。最後、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"たけうち委員","kind":"質問・要望","question":"あそこの土地の活用とか、また地元のいろいろな要望等のことになると思うのですが、その辺のスケジュールのことはどんな感じなのか。南ゆたか保育園についてで結構です。","respondent":"吉田保育施設調整担当課長","answer":"同じ荏原第四中学校跡地に２つの保育園があるうちの南ゆたか保育園なのですけれども、今年度中に、引っ越し元の園舎に戻る予定です。そこで仮園舎としての利用は最後となる予定です。","id":"exchange-055"},{"speaker":"たけうち委員","kind":"確認","question":"前に資料が出ているのがあったかと思って、ちょっと確認させていただきました。分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"ほうさん保育園のほうは、令和３年４月より卒園まで在籍できないクラスの入園を停止となっているのですけれど、ひがしやつやま保育園の場合、入園停止の措置というのは行わないのか尋ねました。","respondent":"立木保育課長","answer":"令和４年に入園するお子様に関しましては、検討するという形ですので、来年度に関しましては入園停止の措置は行わない予定です。来年の４月入園に関しては、入園停止の措置というのは、どのクラスも行わない予定です。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問","question":"その理由は、さらに延長する可能性があるということか尋ねました。","respondent":"立木保育課長","answer":"１年は延ばせるというところは確認できているのですが、それはまた来年度、関係部門と調整しながらという形になると思います。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"そこはしっかりと、きちんとした説明と、ご理解をいただくような工夫というか取組みを行ってほしいと求めました。その点、いかがか尋ねました。","respondent":"立木保育課長","answer":"昨年度、ひろまち保育園の件で、いろいろと陳情等も頂きました。今年度、来年４月の入園に向けて事前にお知らせをするということで、今後もこのような形で早め早めの周知は心がけてまいりたいと思います。","id":"exchange-059"},{"speaker":"芹澤副委員長","kind":"質問","question":"趣旨としては、閉園通知が８月２８日にあって、１か月以内に申込みの締切りが来ると。こういった、ほうさん保育園の令和４年度の一部の転園される方に対しての周知というか、スケジュール感はどのようなお考えなのか尋ねました。","respondent":"立木保育課長","answer":"それで、夏、７月ぐらいに転園のお申込みをいただいて、結果が９月１０日に発表になってあります。それ以外の、翌年度に向けて保育園の検討をされるご家庭に対しても影響は少ないだろうと思われますので、夏ぐらいのご案内等を考えているところです。","id":"exchange-060"},{"speaker":"芹澤副委員長","kind":"意見","question":"前提はやはり５年で終わりになるというのを、終わる際、またやはりちゃんとしたスケジュール感の中でご案内をしてほしいと求めました。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"}]},{"id":"topic-07","title":"の２の所管事務調査","agenda":"の２の所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ご説明に対しての質問なのですが、いつ、どんな感じの協定を区と結んだのかというのをご説明いただきたいというのが１つ。Ａ３の５ページですか、これは文章だと分かりにくいので、どういうことを言っているのかというのをもう少し説明ほしいと求めました。","respondent":"崎村子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"そちらのほうに照会していただいたり、そういった、要保護児童の対応についての情報共有と連携といったところで協定を締結したところです。区もそれに合わせて本年２月に協定を締結したところです。 支援のしやすさの部分について重ねて説明します。児童相談所と子ども家庭支援センター、特に子ども家庭支援センターにつきましては、先ほどもご説明がございましたように。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"フォローをどう考えているのですか、検討の経緯はどうだったのですかという、そういう素直な質問が出ていました。こうした、当日も出た懸念については、またこれからフォローをどういうふうにしていくのかというのを伺わせてほしいと求めました。","respondent":"加島児童相談所移管担当課長","answer":"子どもたちの学習環境の整備の面での連携、安全確保された面から、なかなか外部への外出というのが難しくなります。区内の中でどこまで用意できるかということを考えたとき、一時保護された子どもたちにとって、１つの心の安らぎとなるのではないかと考えております。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"すごく、特に家庭自体が重たい問題を抱えているというケースがほとんどですから、３年経たずに辞めてしまうというような話もありました。一体型もあるとは思うのですが、重い部門、ここで言うところの業務量というところか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"設計上、子ども家庭支援センター機能の相談員数が執務室に収まり切るかというところと捉えてお答えいたします。設計上は、今現在、開設時点では収容できると考えております。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問・要望","question":"確認の意味も含めて、組織について教えていただきたいのですけれども、１層目は虐待防止ネットワーク推進協議会。それで、２層目の協議会地域分科会というのは子どもだけの組織なのか尋ねました。","respondent":"崎村子ども家庭支援センター長","answer":"我々子ども家庭支援センターや保健センター、その地域の子どもをどうやって守っていくですとか見守っていこうかといったことの意見交換をする。全体が４つの虐待の部分で一緒に行っていて、２層目、３層目については子どもの部門で実施しているといったところです。","id":"exchange-065"},{"speaker":"あべ委員","kind":"質問","question":"１３地域あるということは、１３会議にそれぞれ児童相談所の方が出てきているということなのですか。本当に１３でやっていいのかという気にもなってしまうのですけれど、何か課題とか、今後こうしたいというのがあれば説明を求めました。","respondent":"崎村子ども家庭支援センター長","answer":"やはり、その地域でどういった方がいるのかというのを、児童相談所としても把握していただくというのは大切なことであろうかと考えています。それで、お声をかけさせていただいて、児童相談所の業務のお話ですとか現在の虐待の状況などをご説明していただいているところです。","id":"exchange-066"},{"speaker":"あべ委員","kind":"質問・要望","question":"一般質問でも取り上げましたけれども、私は大賛成というか、ぜひその方向でやってほしいと求めました。子ども家庭支援センターの中でもかなり力を入れて担っていってほしいと思うようなところなのですけれど、どういうふうに考えていらっしゃいますか。","respondent":"崎村子ども家庭支援センター長、加島児童相談所移管担当課長","answer":"地域分科会なのですけれども、これは年１回、各１３地域で行っているものです。といいますのも、先ほど言った全体会は、それを子どもに特化して関係機関と意見交換をするといった場を設けさせていただいているところです。 子ども家庭支援センターは、関係機関とのネットワークのつながりを活かした、虐待予防に特化した関わりができると考えております。そしてまた児童相談所、現在は児童虐待が発生した後に対応しておりますが、そうではなく。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひその方向で行ければ行っていただきたいと期待しております。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"たけうち委員","kind":"質問","question":"区の子ども家庭支援センターの見解では、全くゼロとは言えないけれども、それほどではないのではないか。その割合というのですか、ざっくりで結構なのですけれども、どのような感じなのか尋ねました。","respondent":"崎村子ども家庭支援センター長","answer":"児童相談所から子ども家庭支援センターに送致といったことが開始されまして、その対応なのですけれども、近隣からの泣き声の通告。我々のほうで対応するものもありますし、ケースによっては児童相談所のほうにもう一度お戻しするといったこともあります。","id":"exchange-069"},{"speaker":"たけうち委員","kind":"質問","question":"これは私の勉強不足かもしれないですが教えてもらいたいのが、各２３区の中でほとんどの区で、今のところ明確になっているのでしたか。その辺はどうなのか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"目黒区ともに児童相談所の開設の意向を持っていますが、まだ現在、開設予定時期までは明らかになっておりません。品川区が区立児童相談所を設置した場合、世田谷区が児童相談所を設置した際、そのような形で担当地域の変更が行われるのか。","id":"exchange-070"},{"speaker":"たけうち委員","kind":"質問","question":"いろいろな、でも情報がダブってどうなのかということで、いずれにしてもこれは東京都の考えでしょうから。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"横山委員","kind":"質問・要望","question":"幾つか伺っていきます。その辺りはいかがか尋ねました。","respondent":"加島児童相談所移管担当課長、崎村子ども家庭支援センター長","answer":"区民に親しまれる児童相談所をということを掲げておりますので、参考にできるところがあれば私どももその志を引き継いでまいりたいと考えております。こういった、そもそも在宅に復帰したときへの支援計画ですとか… 考えられるのは、一時保護から家庭復帰をする際には、必ず児童相談所から個別ケース検討会議の開催を依頼されます。","id":"exchange-072"},{"speaker":"横山委員","kind":"質問・要望","question":"東京都であったり先行の３区であったり、ご協力いただいてお願いしたいということは、ぜひ要望させてほしいと求めました。もともと平成３０年度が２名ですか、２件ということなので、ぜひ今後に引き継いでいただきたいと考えています。","respondent":"崎村子ども家庭支援センター長","answer":"そういった家庭内事故の報告が多くなっているといったところで、１１３件の内訳としては、そういったところでご説明させていただいたところです。４ページの児童虐待防止会議や虐待ケース進行管理会議につきましては、月１回実施しています。","id":"exchange-073"},{"speaker":"横山委員","kind":"質問・要望","question":"直近の動きのあったものや、区のサービスが必要なものという形で、どういったケースを確認していくのかというところ。検討していっていただきたい、今後どうしていくかということを検討してほしいと思うのですけれども、その辺りのお考えを説明するよう求めました。","respondent":"加島児童相談所移管担当課長","answer":"先行３区のやり方では、３区の体制を参考に、こちらの会議体の持ち方についても考えてまいりたいと考えています。私どもはそのような方法で、両機関の情報共有、それから緊急度の認識を図ってまいりたいと考えているところです。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問・要望","question":"１点だけお伺いしたいのですが、２番「愛の手帳の判定」のところを、ぜひ違うところに移していただきたい。業務整理、どこか児童相談所ではなく移せないかというのは思っているところなのですけれども、そちらのほうのお考えなど何かありますか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"児童相談所、またはどちらの機関で行うのが適切かというのを、関係課とも協議してまいりたいと考えます。国の児童相談所運営指針で、愛の手帳の判定は児童相談所と言われておりますので、今はそのような体制を基本に据えているところです。","id":"exchange-075"},{"speaker":"せお委員","kind":"質問・要望","question":"先行３区など、そちらの業務内容の調査をしていただいて、検討していっていただきたいと思っています。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5014#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":69429,"voices":191}},{"id":"r02-20200924-5","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"総務委員会","time":"午前１０時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"各所管で審査され、提案や要望をさせていただきました。初めに総務委員会に所管する部分の概要を伺いたいと思うのですけれども、また行政情報、伺いたいと思いますとの意見を述べました。","respondent":"山本情報推進課長、黒田人事課長、秋山選挙管理委員会事務局長","answer":"自宅のパソコンで業務を行う場合、その自宅のパソコンに庁内のパソコンにあるデータを保存できないような仕組みを取り入れます。… 補正予算の電話相談センター等対応経費のご質問ですが、医療職の資格を持っている方の派遣をお願いしています。感染状況によりますけれども… 選挙啓発物品ですけれども、出前模擬選挙等に使う記載台の購入を予定しております。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"総合審査ということなので、全体的なことも伺いたいと思うのですが。歳入、歳出もそうですけれども、特に一般財源を積極的に使っているもの、上乗せしているものの中で特徴的な事業は何か、伺いたいと思います。","respondent":"品川財政課長","answer":"新型コロナウイルス感染症対応地方創生臨時交付金が約１１億円程度入ってきておりますので、ＰＣＲ検査経費、そういった部分に充当しております。主なところとしては、そういうところになっております。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"若干伺いたいのですけれども、区内は３病院に指定されているわけでありますが、地域医療に非常に体を張って貢献していると考えています。３病院への支援は歓迎したいと思いますが、事業を拡大していく必要があるのではないかと思うのですけれども、伺いたいと思います。","respondent":"品川財政課長","answer":"これは今後また、どういうふうにしていくかというところでの検討材料になるかと思います。ただ今回の補正に関しては、また今後の展開等を見ながら考えていきたいと考えています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"東京都や国にしっかり補てんを求めていくことは、義務教育ですから当然だと思うのですけれども、その点伺いたいと思います。区職員が直接区民の声に耳を傾け、対応をしてほしいと求めましたが、この点はいかがか尋ねました。","respondent":"品川財政課長","answer":"今後、対応できるものはしっかり対応していくという体制をとって、今後も続けていきたいと考えています。ご質問にありました職員対応等は、いろいろ状況があると思いますけれども、職員対応の部分も必要があれば補充していく等。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり国の交付金が１桁足りないと考えていますので、引き続き求めてほしいと求めました。あえて反対はしませんけれども、マイナンバー自体は進めるべきでないという姿勢は変わらないということだけ、申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"ここにかなりの金額を支援するということになっていますが、品川区内には中小規模の企業や商店街もたくさんあります。今回、屋形船に支援するならば、そこへの支援も同等に行うべきだと私は思うのですが、どういうふうになっているのか尋ねました。","respondent":"品川財政課長","answer":"これまでも１０億円以上を投入して、今回のコロナ対策の中でもかなり、金額としては大きく投入している部分かと思います。こういった形で、やはり中小企業に対しては積極的に、今までも事業をやってきているところです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"次に、地域スポーツ等推進経費で、感染拡大防止対策体温測定器購入ということで、これを置くということですが、どういう測定器なのですか。説明を求めました。","respondent":"品川財政課長","answer":"体温が測れるという仕組みになっていまして、いわゆる効率化という面で、今回導入を行うものです。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"いろいろ往来するのですから短時間で効率よくやって、本当は区庁舎でもやってほしいのですけれど、私はやるべきではないかと思います。ならば、清掃車の巡回回数を増やすのが当たり前のことであって、なぜ家庭用生ごみ処理機の購入助成を増やさなければいけないのか尋ねました。","respondent":"品川財政課長","answer":"実績も昨年で７月ごろまでで４２件、今回は１１２件となっておりまして、ごみの量が一気に減るという大きなメリットがあります。やはり推奨していくためには、ごみの全体の量を少しでも減らそうという趣旨の中で、今回購入助成についても補正予算として上げているという形です。","id":"exchange-008"},{"speaker":"須貝委員","kind":"意見","question":"やれるかどうか、そういうことも考えたら、何か不思議な行動に出ているのかなと。清掃車の回数増というのが、経費がかかっても私は常識だと思うのですが、もう一度お答えくださいとの意見を述べました。","respondent":"品川財政課長","answer":"これは、ある意味リサイクルを進めるというところでの費用として、予算計上しているということでご認識いただきたいと思います。今のところ何とか対応できているですので、今後またごみの量次第では、どうしていくかというところは検討の材料の一つかなとは思っております。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"伺いたいのは、保育従事者にはそれが計上されなかったというのは、所管の判断ということなのでしょうか。それとも区として、それは所管に任せておこうということで判断されたのか、その辺について伺いたいと思います。","respondent":"品川財政課長","answer":"保育従事者に今回ついないという件に関しては、介護サービスと障害福祉サービスの従事者にＰＣＲ検査をという判断をしたものです。新型コロナウイルス感染症にかかった場合、リスクが非常に高いというところで、今回ＰＣＲ検査を入れたです。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"マスクをしている保育士だと、特に０歳児は、とても子どもたちの表情が乏しくなってしまう。そこから広がる、保育に関わっている人はいろいろな仕事と関係しているわけですから、その辺についてのお考えを伺いたいと思います。","respondent":"品川財政課長","answer":"保育従事者、医療従事者等に関しても、それぞれ個別の事情があるというところは認識しています。新型コロナウイルス感染症の動き等も日々変動するところがあります、そういった状況も見ながら、対応については考えていきたいと考えています。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"これは確認ですが、前の補正の時に伺いました感染予防対策のためのいろいろな物品の購入、前にも言いましたけれども。その後契約書などは確認していないのですが、今回につきましてもぜひその辺については、ウイルスに効果のあるものにしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"確認","question":"２点確認させてください。５００万円余という金額の中で、消毒とかいろいろあると思うのですけれども、どういうものか確認したいと求めました。","respondent":"品川財政課長","answer":"東急バスと京急バスの内訳ですけれども、たしか東急のほうが、バスの台数もありますので額は大きくなっていると認識しています。雨の日に窓を開けても雨が入ってこないという、ひさしのようなものがありまして、こういうものを設置する費用に使うものです。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"確認","question":"バス事業者のほうは分かりました。ＰＣＲ検査ですけれど、そうすると想定している人数は大体、どのぐらいなのか、最後に確認したいと求めました。","respondent":"品川財政課長","answer":"想定人数ですけれども、ざっくりですけれど３,５００人程度を想定しております。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"その上で、どれぐらいの件数を想定されているのかをお伺いさせていただきたいのが１点です。７月で終わった後問い合わせがあった方に対しては、どういう対応をされているのか、確認させてほしいと求めました。","respondent":"品川財政課長","answer":"今後に向けて、どういうところで活用できるか、十分に検討していきたいと考えています。４月から７月の間で申請を受けて、今回の補正がもし決まった場合には、しっかりと対応していくというふうに考えております。","id":"exchange-015"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"申請の仕方もオンラインでというふうにちょっと伺いましたが、使うべき方がしっかりこの支援を使えるように、してほしいと求めました。家庭用生ごみ処理機購入助成に関しましても、新たに予算がつきましたということを申請したい方が知っていただけるように、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"区民と事業者への支援を強めていただきたいのと、ＰＣＲ検査ですけれども、理由は利用者が重症化するリスクがあるということであります。もちろん学校も病院もそうですけれども、ぜひ対象を広げていただきたいと、要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから生活者・ネットワークがずっと要望しております、いろいろな仕事とのマッチング事業とか、そういうことも考えられると思います。その上で賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"を変更して先に、予定表の４のその他のうち、(1)所管質問","agenda":"を変更して先に、予定表の４のその他のうち、(1)所管質問","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今、委員長がおっしゃったとおりなのですけれども、８月３日の依命通達にて、令和３年度、原則１０％のマイナスシーリングをすると記されておりましたが、その理由を伺いたいと思います。","respondent":"品川財政課長","answer":"そういう中で、やはり歳入減が大きく見込まれるということで、１０％のマイナスシーリングをかけたというケースがあります。こういうことによりまして、職員全体としても予算を見込む中で十分そのことを認識しながら、今回１０％のマイナスシーリングをしています。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"新型コロナウイルス感染症のための財源に充てるよう求めてきましたが、今回の依命通達は、全ての部局に一律１０％を求めると。こういう対応というのはなぜなのか、あまりにも乱暴ではないかと思うのですけれども、いかがか尋ねました。","respondent":"品川財政課長","answer":"いわゆる光熱費とか物品購入、維持費、そういった部分に１０％のマイナスシーリングを要求しているものです。あくまでも経常経費の部分にシーリングを行うです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"あくまで経常的な経費であって、政策的な経費ではないという説明でよろしかったのか、伺いたいと思います。そういう事業の予算をマイナスするという考えはないということなのか、改めて伺いたいと思います。","respondent":"品川財政課長","answer":"経常経費のほうは、先ほども申しましたように基本的な維持管理の部分、光熱費部分が主なものです。政策経費のほうは、この政策予算で対応しておりますので、これにつきましては１０％のマイナスシーリングは該当しないということになってあります。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"区民生活に直結する事業については、ぜひそういった予算編成を進めていただきたいのと、当然コロナ禍の影響で増えてきているのは当然だと思うのです。ぜひ原則一律１０％のマイナスシーリングという考え方は、見直してほしいと求めましたが、最後にいかがか尋ねました。","respondent":"品川財政課長","answer":"前年度の執行率などを見て、そういうところでまだまだ見直しができそうだというところを探っていくというものが、本来の趣旨です。ですので、しっかりとそういう部分については予算をつけて、対応してまいりたいと考えております。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"それがどういうふうに各所管に伝わるか分かりませんけれど、よほどきちんと趣旨を言っておかないと、当然抑え目に来るのではないでしょうか。政策的予算だけでなく経常的予算の中でも、考えていただくようにしてほしいと求めましたが、その辺について何かあれば伺いたいと思います。","respondent":"品川財政課長","answer":"やはり政策的に安定して事業として成り立っている部分については、経常経費で行っているところもあります。シーリングのほうは当然行い、進めていっているというものですので、大丈夫です。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺ぜひ、予算要求をそれぞれの所管に求めるとき、きちんと伝えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"まず根拠として、実はこういう情報が入ったとか、何かあるのでしょうか。こういう情報が国から来たとか、ある情報機関から入ってきたとか、そういうものがあったら説明を求めました。","respondent":"品川財政課長","answer":"やはり区民全体の所得を考えると、どうしても今年度の所得を考えれば前年度よりはかなりのダウンが予想されるかと思います。やはり区民税も大きく減少するということは予想されますので、そういったところからも今回１０％のマイナスシーリングという対応をしています。","id":"exchange-025"}]},{"id":"topic-03","title":"なお聴取する順番を変更いたしまして、先に(3)品川区庁舎機能検討委員会の実施状況","agenda":"なお聴取する順番を変更いたしまして、先に(3)品川区庁舎機能検討委員会の実施状況","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひこの１０名という人数を拡大して、希望者全員が傍聴できるように改善してほしいと求めましたが、いかがでしょうか。今の区議会もそうですけれど、「今日は傍聴者がいらっしゃいます」ぐらいの案内に改善していただきたいと思うのですが、それぞれいかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"会場のキャパシティーも考えまして、適切な傍聴人数を検討していければと考えています。第１回目につきましては、どうしてもはじめは傍聴規定をご説明して、傍聴の方に入室いただくという流れをとっております。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、希望者全員が入れるような対応をとるべきだと思うのですが、改めて伺いたいと思います。２週間ないし少なくとも１か月後には議事録は公開に、公開も改善していただきたいと思うのですが、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"２点目、第２回に関しまして、それから入っていただくという方法をとっております。３点目、議事録ですが、こちらも次回の委員会でご承認を受けた上で、公開をしています。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"課長にその事実があるかどうか、確認したいのですけれども、私が聞いたところでは４人から出ているというのです。このエレベーターが止まるという発言があったかどうか、複数あったかどうかも含めて、お伺いしたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"３点目、冒頭の説明のときに申し上げましたとおり、複数の方からいただいていたと考えています。そうしたものも含めて、様々な考え方、ご意見を委員の方からいただいて、今後の機能の検討のまとめのほうをつくっていきたいと考えています。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、この新庁舎建設候補地にある「にぎわい」というのは、何を指しているのですか。そこを伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"広町地区におけるまちづくりの検討の中で、都市環境部のほうでしっかりと検討を進めているものかと考えています。行政機能というところで、新庁舎建設候補地をお示しさせていただきました。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"では、にぎわいというのは都市開発課が決めるのですか。庁舎計画担当課長に聞いているのですけれども、このにぎわいは庁舎計画担当でなく、都市開発課が検討するということなのか尋ねました。","respondent":"榎本総務部長","answer":"広町地区全体のゾーニングということで、要はこのＴ字型になっている道路の右側と左側で大きく機能を分けています、ということです。今の第２庁舎のところまで色が同じになっていると思いますけれども、区としてこれから検討していくという形です。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりご意見の中でも「障害の有無にかかわらず」というのが出てくるぐらいですから、その辺についてはぜひ、配慮をしてほしいと求めました。傍聴のこととか、先ほどの中塚委員の繰り返しになるかもしれませんけれど、改めて障害者への配慮などの点も含めて、何かあれば伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"２点目、そういう方々に対しての合理的な配慮を行い、様々な方が委員会に参加できるような体制をとっていきたいと考えています。全ての意見を網羅すると長くなってしまいますので、複数あったものですとか、主だった意見をまとめて、報告にさせていただきたいと考えています。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"当然していかなければいけないわけですから、この検討のところから、そういう方たちが意見を言いやすいような配慮をしてほしいと求めました。だからぜひその辺の配慮は、事務局のほうでやってほしいと求めましたので、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"それも大人数ができるような、そういう住居というのですか、部屋も確保されていくのでしょうか。品川区は４０万人、仮に万が一放射能汚染等があったとき隔離できるような、そういう部屋も用意しているのか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"今後検討を進めてまいります。ただ、コロナの感染対策といったご意見を踏まえてですとかでそのような検討が、今後出てくる可能性はあるかと考えております。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"２３区で実際にはまだ我々も経験していないので、寝起きできるような場所があるといいと思いまして、お聞きしてみました。内容は分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"何点かお聞きしたいのですけれども、全学校とつながっていける環境というのがあるのですけれども、私もこれは学校で聞いたことがあります。そういったものを災害対策本部ですか、３７校、一律配信することは可能なのか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"恐らく検討会の委員の趣旨としましては、行き来する時間がなくなれば効率的に業務ができるというような観点もあるかと思います。そういったところも含めての機能を、今後検討してまいるです。","id":"exchange-035"},{"speaker":"松澤委員","kind":"質問","question":"防災普及啓発機能も検討してほしいというご意見、これも多分今あるしながわ防災体験館ですか、私の個人的な意見なのです。駐車場でもいいのですけれど、そういう消防団の訓練ができる施設をつくっていただけるとか、そういったお考えはありますか。","respondent":"濱中庁舎計画担当課長","answer":"２点目、消防団の訓練用地がなかなか難しいというお話をいただきました。その点の検討は、今後そういったご要望も庁舎機能検討委員会等の意見を踏まえて、検討していくところかと考えています。","id":"exchange-036"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひ消防団の場所を、皆さん大変な思いで、少しでも練習できる場所を提供していただきたいと思っています。ペットとの共存という部分で屋上にするのか分からないですけれども、そういうドッグラン的な施設の設置の検討というのは、あるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"新妻副委員長","kind":"提案","question":"スケジュールのことだけお伺いいたします。何かそういう影響が出ているのかどうか、そういうことがありましたら、教えてほしいと求めました。","respondent":"濱中庁舎計画担当課長","answer":"庁舎機能検討委員会のスケジュールに関しまして、５月に第１回を予定していたところ、３月というスケジュールを組みました。ただ今後、また緊急事態宣言が出るようなことがあれば、こういったスケジュールも少し延ばしていく可能性もあるかとは思っております。","id":"exchange-038"}]},{"id":"topic-04","title":"立会川緑道整備工事（４工区）請負契約","agenda":"立会川緑道整備工事（４工区）請負契約","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"今度は４工区、６の現況写真、くつろいでいるところでした。地域からの意見はお聞きしていると思うのですけれども、そこだけ、どういう整備になるのかだけ聞きたいと思います。","respondent":"東野経理課長","answer":"私ども経理課ということですので、知っている範囲でお答えしたいと思います。高齢者の方への配慮につきましても、地元の町会等と話し合いを進めながら、施工に当たっていくというふうに聞いてあります。","id":"exchange-039"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ちょっと不勉強で教えていただきたいのですけれど、この事業自体が１工区から４工区となっているのですけれど、そもそも４工区に分けているのはどうしてなのか、教えていただけますか。","respondent":"東野経理課長","answer":"年間の工事スケジュール等を組む中で、１工区も大体、去年同じぐらいの時期に契約いたしまして、３月までの工期ということで伺っております。同じような工事スパンで進めるということで、４工区に分けたものだと考えられます。","id":"exchange-040"},{"speaker":"湯澤委員","kind":"質問・要望","question":"これは工区によって多分、それぞれ区のほうでこういうイメージでやっていただきたいということで、工事が行われるという感じなのですか。全てが一緒ではなく、それぞれの工区ごとに違った形の工事になっていくということなのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"湯澤委員","kind":"質問・要望","question":"建設委員会所管のほうの質問で申し訳ありません。静かな環境で安全に通れるところでありますので、ぜひすばらしい、安心した道になるような工事をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"須貝委員","kind":"質問","question":"４工区の樹木がうっそうとしているというお話が出ましたが、質問というよりはなぜここの場所、どうも剪定されていないのです。今はどうしても確かに通りにくい、歩きにくいということもあると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-05","title":"令和４年度以降の成人式参加者の対象年齢","agenda":"令和４年度以降の成人式参加者の対象年齢","exchanges":[{"speaker":"湯澤委員","kind":"質問","question":"２０歳で行うとした場合、令和４年度に２０歳になるのではないかと思うのですれども、そういった子たちにどういうふうに周知をしていく予定なのか。既に社会人になられている方もいらっしゃるかなと思うので、その辺はどうお考えか、説明を求めました。","respondent":"立川総務課長","answer":"例えば１８歳で品川区はやるよということになりますと、今の高校１年生も一緒にやるみたいな、十分周知していきたいと考えております。当然、まだ少し早いですが中学３年生であるとか、高等学校のほうにも、広報を丁寧にしていきたいと考えているところです。","id":"exchange-044"},{"speaker":"湯澤委員","kind":"意見","question":"２０歳なら２０歳、１８歳なら１８歳と、本当は一律のほうが分かりやすいかと思うのです。例えば２０歳と決定したならば「２０歳の成人式」とか、誰もが品川区は２０歳なのだなと分かるような、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"松澤委員","kind":"質問","question":"２部制での開催ということで、「品川地区・大井地区・八潮地区は午前中ですよ」というような、何かはがきなどの通知が来るのか尋ねました。","respondent":"立川総務課長","answer":"８月末ですけれども、この委員会と前後してしまいましたけれども、公表させていただいたところです。今後、１２月に案内状を各該当者の方にお送りいたしますので、そこでより詳しく説明をします。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問","question":"今後もこういう意見をお聞きしながら、私はできれば今後は、成人というより２０歳の何か記念になるような行事ということで考えてほしいと思います。２０歳になってきゅりあんで中学時代の同級生、なぜ成人なのに酒やたばこは駄目なのだと、私は続けていっていただけたらありがたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"新妻副委員長","kind":"確認","question":"お声がありましたので次の１月の開催について、確認します。来年の１月、その中でも２部制として、その経緯を少しお知らせほしいと求めました。","respondent":"立川総務課長","answer":"いわゆる実施方法について決定している区のほとんどが２部制を採用するということでございまして、そちらをまず参考にさせていただいたところです。より安全に実施できるような方法で、場合によっては３部制という選択をする可能性も、考えております。","id":"exchange-048"},{"speaker":"新妻副委員長","kind":"質問","question":"そういうことが検討課題に挙がったのかどうかをお伺いしたいのですが、様々な形で、いろいろなところで進んできているかと思います。オンラインでの成人式という考え方もあるのではないかと思うのですが、いかがか尋ねました。","respondent":"立川総務課長","answer":"報道で、横浜市はオンラインでやると言って、その後撤回したというお話がありました。ＹｏｕＴｕｂｅ等を利用して会場の様子を生配信するといったことも、まだ検討中ではありますが、いろいろ工夫して実施したいと考えています。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2180#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":43388,"voices":138}},{"id":"r02-20200924-10","meetingId":"r02-cm09","date":"2020年9月24日","dateIso":"2020-09-24","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5378#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1004,"voices":8}}]);
